window.SOCIAL_DATA=window.SOCIAL_DATA||[];window.SOCIAL_DATA.push({"id": "civ-4", "subject": "公民", "chapter": "第四章", "title": "中央政府", "total": 367, "levels": {"必考": 37, "常考": 18}, "boss": {"title": "大魔王卷", "ids": ["c4-500", "c4-501", "c4-502", "c4-503", "c4-504", "c4-505", "c4-506", "c4-507", "c4-508", "c4-509", "c4-510", "c4-511", "c4-512", "c4-513", "c4-514", "c4-515", "c4-516", "c4-517", "c4-518", "c4-519", "c4-520", "c4-521", "c4-522", "c4-523", "c4-524", "c4-525", "c4-526", "c4-527", "c4-528", "c4-529", "c4-530", "c4-531", "c4-532", "c4-533", "c4-534", "c4-535", "c4-536", "c4-537", "c4-538", "c4-539", "c4-540", "c4-541"], "videos": [{"t": "影音詳解 1", "url": "https://youtu.be/4i-OXVidlNI"}, {"t": "影音詳解 2", "url": "https://youtu.be/KJg8Zd1Lmzs"}]}, "mapname": {"c4-map-emerg": "總統發布緊急命令流程簡圖", "c4-map-cabinet": "行政院 15 部架構圖", "c4-map-judicial": "司法院職權架構圖", "c4-map-budget": "中央政府預算、決算流程簡圖", "c4-map-noconf": "不信任案與解散制度", "c4-map-veto": "覆議制度流程簡圖", "c4-map-impeach": "總統、副總統彈劾方式"}, "concepts": [{"id": "c7", "name": "中央政府的互動與制衡機制", "n": 113, "level": "必考", "card": {"說明": "為落實權力分立與防止政府濫權，我國五院與總統之間設有密集的牽制與制衡機制。行政權與立法權之間設有「質詢」、「不信任案與解散立法院」以及「覆議制度」；立法院、監察院與司法院之間則設有「公務員彈劾移送」與「正副總統彈劾審理」等互制程序，維持國家體制之動態平衡。", "關鍵名詞": "• <b>質詢權</b>：立法委員在開會期間，就施政方針與報告向行政院院長及各部會首長提出質詢的權力。<br>• <b>不信任案（倒閣）</b>：立法院對行政院院長施政不滿時提出之表決案；若通過，行政院院長應辭職，並得同時呈請總統解散立法院；若未通過，一年內不得對同一院長再提。<br>• <b>解散立法院</b>：立法院通過對行政院院長之不信任案後，總統得宣告解散立法院，令全體立委重新改選。<br>• <b>覆議</b>：行政院認為立法院決議之法律案、預算案或條約案窒礙難行時，經總統核可後移請立法院重新覆決的制度。", "因果／影響": "覆議機制提供行政院抗衡立法院強行通過不當法案的救濟途徑，而不信任案與解散國會機制則可打破行政與立法間的嚴重政局僵局，交由全體國民重新投票仲裁。", "出處": "自修第 283～286 頁／教學式講義第 41～42 頁（試題寶典評量第 31 頁、評量單第 8 回）。", "標示": "講義列為「<b>必考重點分析</b>」，會考與模擬考之「<b>精熟題必考熱點</b>」。"}, "imgs": ["c4-map-noconf", "c4-map-veto", "c4-map-impeach"], "clusters": [{"t": "不信任案與解散立法院", "n": 43, "ids": ["c4-6", "c4-7", "c4-16", "c4-20", "c4-28", "c4-32", "c4-40", "c4-41", "c4-43", "c4-58", "c4-59", "c4-62", "c4-73", "c4-82", "c4-84", "c4-94", "c4-109", "c4-118", "c4-123", "c4-141", "c4-147", "c4-170", "c4-174", "c4-300", "c4-302", "c4-303", "c4-304", "c4-319", "c4-320", "c4-334", "c4-371", "c4-377", "c4-393", "c4-410", "c4-511", "c4-513", "c4-522", "c4-527", "c4-531", "c4-532", "c4-537", "c4-538", "c4-541"]}, {"t": "覆議制度", "n": 16, "ids": ["c4-79", "c4-117", "c4-152", "c4-153", "c4-198", "c4-203", "c4-332", "c4-369", "c4-370", "c4-392", "c4-401", "c4-501", "c4-510", "c4-514", "c4-515", "c4-520"]}, {"t": "正副總統彈劾、罷免的分工", "n": 20, "ids": ["c4-8", "c4-17", "c4-25", "c4-57", "c4-61", "c4-90", "c4-107", "c4-115", "c4-144", "c4-179", "c4-184", "c4-190", "c4-202", "c4-307", "c4-308", "c4-338", "c4-357", "c4-407", "c4-533", "c4-540"]}, {"t": "預算、決算流程", "n": 11, "ids": ["c4-31", "c4-55", "c4-101", "c4-167", "c4-309", "c4-316", "c4-331", "c4-383", "c4-400", "c4-519", "c4-528"]}, {"t": "官員產生方式比較", "n": 18, "ids": ["c4-27", "c4-52", "c4-102", "c4-110", "c4-116", "c4-133", "c4-142", "c4-193", "c4-195", "c4-204", "c4-315", "c4-367", "c4-373", "c4-391", "c4-402", "c4-406", "c4-505", "c4-539"]}, {"t": "五院分工與制衡", "n": 5, "ids": ["c4-29", "c4-76", "c4-181", "c4-336", "c4-521"]}]}, {"id": "c3", "name": "立法院：最高立法機關", "n": 63, "level": "必考", "card": {"說明": "立法院為我國最高立法機關，也是中央民意機關，由全體人民依法選出的立法委員組成，每屆任期四年，連選得連任。立法院院長、副院長由立法委員互選產生。立法院核心職權包含制定與修改法律、審查中央政府總預算、質詢行政官員，並對總統提名之特定公職人員行使人事同意權。", "關鍵名詞": "• <b>中央民意機關</b>：由全體國民選舉產生之代表所組成，代表全國人民行使立法與監督權的中央機關。<br>• <b>人事同意權</b>：立法院對總統所提名的司法院、考試院、監察院相關官員及審計長，進行審查並投票決定是否同意任命的權力。", "因果／影響": "立法院掌握國家法律制定與預算把關權，若行政機關施政不力，立法院可透過質詢、刪減預算甚至提出不信任案進行強烈監督。", "出處": "自修第 275～277 頁／教學式講義第 39 頁（試題寶典評量第 30 頁、評量單第 7 回）。", "標示": "講義與自修均列為「<b>必考／重點精華</b>」，各類段考卷出現頻率最高。"}, "imgs": [], "clusters": [{"t": "提案權：修憲、領土變更、正副總統彈劾與罷免", "n": 24, "ids": ["c4-4", "c4-38", "c4-46", "c4-69", "c4-72", "c4-89", "c4-112", "c4-122", "c4-125", "c4-140", "c4-154", "c4-162", "c4-183", "c4-187", "c4-192", "c4-205", "c4-323", "c4-330", "c4-349", "c4-361", "c4-376", "c4-387", "c4-408", "c4-516"]}, {"t": "人事同意權", "n": 11, "ids": ["c4-9", "c4-12", "c4-100", "c4-158", "c4-164", "c4-318", "c4-321", "c4-339", "c4-358", "c4-365", "c4-518"]}, {"t": "制定法律、審查預算、質詢", "n": 19, "ids": ["c4-13", "c4-35", "c4-51", "c4-64", "c4-67", "c4-86", "c4-93", "c4-127", "c4-132", "c4-185", "c4-189", "c4-208", "c4-317", "c4-346", "c4-356", "c4-375", "c4-378", "c4-381", "c4-412"]}, {"t": "立法委員與院長的產生", "n": 9, "ids": ["c4-106", "c4-126", "c4-194", "c4-310", "c4-313", "c4-329", "c4-344", "c4-380", "c4-529"]}]}, {"id": "c6", "name": "監察院：最高監察機關", "n": 52, "level": "必考", "card": {"說明": "監察院為我國最高監察機關，行使彈劾、糾舉及糾正權，並設審計部對各機關年度決算行使審計權。監察院置院長、副院長、監察委員與審計長，均由總統提名，經立法院同意後由總統任命。監察委員得對違法失職之中央與地方公務人員行使彈劾權與糾舉權，並得針對行政機關之不當施政提出糾正案。", "關鍵名詞": "• <b>彈劾權</b>：監察院針對違法或失職之公務人員（不含總統、副總統及民意代表），向司法院懲戒法院提出審理懲處的權力。<br>• <b>糾舉權</b>：監察院針對違法或失職之公務人員，向該公務人員之主管或上級長官提出，要求停職或妥善處置的權力。<br>• <b>糾正案</b>：監察院針對行政院及其所屬機關之不良施政或違失業務，向行政院或相關部會提出，督促其改善的權限。<br>• <b>審計部</b>：監察院下設之獨立專門機關，專責審核中央政府各機關年度決算，並編製決算審核報告向立法院提出。", "因果／影響": "監察權自立法權抽離獨立，專責嚴密監控各級公務人員操守與各行政部門預算執行，能有效防範官員貪瀆並防止國會專制。", "出處": "自修第 281～282 頁／教學式講義第 40 頁（試題寶典評量第 30 頁、評量單第 7 回）。", "標示": "自修與講義均列為「<b>必考／易混淆重點</b>」，尤其是彈劾、糾舉與糾正之對象與程序。"}, "imgs": ["c4-map-budget"], "clusters": [{"t": "彈劾、糾舉（對人）", "n": 32, "ids": ["c4-3", "c4-36", "c4-47", "c4-53", "c4-70", "c4-114", "c4-135", "c4-149", "c4-168", "c4-173", "c4-177", "c4-178", "c4-180", "c4-197", "c4-201", "c4-206", "c4-305", "c4-311", "c4-314", "c4-328", "c4-342", "c4-343", "c4-355", "c4-368", "c4-374", "c4-382", "c4-388", "c4-390", "c4-394", "c4-508", "c4-512", "c4-523"]}, {"t": "糾正（對事：行政機關）", "n": 8, "ids": ["c4-23", "c4-87", "c4-120", "c4-161", "c4-364", "c4-411", "c4-507", "c4-536"]}, {"t": "審計部：審核決算", "n": 8, "ids": ["c4-18", "c4-42", "c4-98", "c4-130", "c4-157", "c4-188", "c4-351", "c4-398"]}, {"t": "監察院的組織與產生", "n": 4, "ids": ["c4-5", "c4-139", "c4-324", "c4-397"]}]}, {"id": "c4", "name": "司法院：最高司法機關", "n": 49, "level": "必考", "card": {"說明": "司法院為我國最高司法機關，掌理民事、刑事、行政訴訟之審判及公務員之懲戒。司法院設院長、副院長及大法官若干人，皆由總統提名，經立法院同意後由總統任命。大法官組成「憲法法庭」，負責審理法律是否牴觸《憲法》、政黨違憲之解散案件，以及審理立法院提出之總統、副總統彈劾案。", "關鍵名詞": "• <b>大法官</b>：司法院組成成員，負責組成憲法法庭解釋憲法、審理法規違憲、政黨解散案與正副總統彈劾案。<br>• <b>懲戒法院</b>：司法院下設專門機關，專門審理監察院彈劾移送或主管機關移送之公務人員違法失職案件。<br>• <b>憲法法庭</b>：由大法官組成，專責審理法律違憲、政黨違憲解散及正副總統彈劾之審判法庭。", "因果／影響": "司法院以法規為準繩獨立審判，超出黨派之外，既能維護社會公平正義，又能作為憲法的守護者，制衡立法與行政權力。", "出處": "自修第 278～279 頁／教學式講義第 39 頁（試題寶典評量第 30 頁、評量單第 7 回）。", "標示": "講義標為「<b>重點分析</b>」，試題寶典評量列為「<b>易錯觀念</b>」。"}, "imgs": ["c4-map-judicial"], "clusters": [{"t": "憲法法庭：違憲審查、正副總統彈劾、政黨解散", "n": 31, "ids": ["c4-34", "c4-37", "c4-39", "c4-50", "c4-71", "c4-78", "c4-88", "c4-95", "c4-96", "c4-111", "c4-119", "c4-129", "c4-143", "c4-146", "c4-156", "c4-160", "c4-200", "c4-301", "c4-322", "c4-325", "c4-326", "c4-348", "c4-359", "c4-385", "c4-395", "c4-399", "c4-409", "c4-503", "c4-517", "c4-524", "c4-526"]}, {"t": "懲戒法院：公務人員懲戒", "n": 6, "ids": ["c4-63", "c4-150", "c4-159", "c4-327", "c4-352", "c4-506"]}, {"t": "各級法院：訴訟審判", "n": 12, "ids": ["c4-2", "c4-14", "c4-54", "c4-74", "c4-85", "c4-137", "c4-148", "c4-163", "c4-175", "c4-341", "c4-396", "c4-535"]}]}, {"id": "c5", "name": "考試院：最高考試機關", "n": 34, "level": "常考", "card": {"說明": "考試院為我國最高考試機關，獨立行使考選與人事任用資格之審定。置院長、副院長及考試委員，皆由總統提名，經立法院同意後任命。考試院下設考選部（主管公務人員、專門職業及技術人員等國家考試）與銓敘部（負責公務人員之銓敘、撫卹、退休及其任免等事項）。", "關鍵名詞": "• <b>考選部</b>：掌管公務人員高等、普通、初等考試及專技人員國家考試之考試院附屬機關。<br>• <b>銓敘部</b>：負責審核公務人員任用資格、等級俸給、撫卹與退休保障之考試院附屬機關。<br>• <b>銓敘</b>：指審核公務人員之任用資格（如資歷、考績等），依法審定其等級與俸給。", "因果／影響": "將用人考選權與資格審定獨立於行政權之外，確保國家考試公開公平公正，杜絕行政機關首長任用私人與用人唯親之流弊。", "出處": "自修第 280 頁／教學式講義第 39 頁（試題寶典評量第 30 頁、速讀秘笈第 4 頁）。", "標示": "講義與速讀秘笈標為「<b>重要觀念</b>」。"}, "imgs": [], "clusters": [{"t": "銓敘部：銓敘、退休、撫卹", "n": 18, "ids": ["c4-15", "c4-26", "c4-44", "c4-56", "c4-66", "c4-91", "c4-104", "c4-108", "c4-113", "c4-121", "c4-176", "c4-182", "c4-354", "c4-405", "c4-500", "c4-502", "c4-504", "c4-509"]}, {"t": "考選部：國家考試", "n": 16, "ids": ["c4-33", "c4-68", "c4-77", "c4-97", "c4-134", "c4-166", "c4-172", "c4-199", "c4-337", "c4-345", "c4-350", "c4-366", "c4-389", "c4-403", "c4-404", "c4-525"]}]}, {"id": "c2", "name": "行政院：最高行政機關", "n": 32, "level": "常考", "card": {"說明": "行政院為我國最高行政機關，由行政院院長、副院長、各部會首長及政務委員組成。行政院院長由總統直接任命，副院長及各部會首長則由行政院院長提請總統任命。行政院負責國家各項政策的規畫與法案執行，職權涵蓋內政、外交、國防、財政、教育、法務、經濟、交通、勞動、農業、衛生福利、環境、文化、數位發展、運動等各部事務。", "關鍵名詞": "• <b>最高行政機關</b>：負責規畫國家政策與依法執行法案的中央最高決策與執行體系。<br>• <b>行政院院長</b>：行政院首長，俗稱閣揆，由總統直接任命，負責綜理院務並向立法院負責。", "因果／影響": "行政院依法向立法院負責，院長及各部會首長須向立法院提出施政方針與報告並備質詢；此一設計使最高行政權力在執行政策時隨時受到民意代表的監督。", "出處": "自修第 273～274 頁／教學式講義第 38 頁（試題寶典評量第 29 頁、評量單第 7 回）。", "標示": "講義列為「<b>必考重點</b>」，自修標為「<b>重點核心</b>」。"}, "imgs": ["c4-map-cabinet"], "clusters": [{"t": "院長與部會首長的產生方式", "n": 10, "ids": ["c4-75", "c4-124", "c4-138", "c4-151", "c4-155", "c4-209", "c4-335", "c4-379", "c4-386", "c4-534"]}, {"t": "執行政策：各部會業務", "n": 15, "ids": ["c4-10", "c4-45", "c4-49", "c4-65", "c4-128", "c4-131", "c4-165", "c4-186", "c4-191", "c4-196", "c4-210", "c4-211", "c4-312", "c4-362", "c4-363"]}, {"t": "行政院的其他職權", "n": 7, "ids": ["c4-22", "c4-80", "c4-81", "c4-99", "c4-103", "c4-171", "c4-340"]}]}, {"id": "c1", "name": "總統：國家元首", "n": 24, "level": "常考", "card": {"說明": "總統為我國國家元首，對外代表中華民國，對內統率全國陸海空三軍。總統由人民直接選舉產生，任期為四年，連選得連任一次。總統依據《憲法》及《憲法增修條文》規定行使職權，包括依法公布法律、發布命令、任免或提名行政官員、決定國家安全大政方針，並在遭遇重大變故時發布緊急命令。", "關鍵名詞": "• <b>國家元首</b>：國家的代表象徵，依法對外代表國家，對內統率全國陸海空三軍。<br>• <b>緊急命令</b>：總統為避免國家或人民遭遇緊急危難或應付財政經濟上重大變故，經行政院會議決議後發布之具有強制力的處分，發布後十日內須提交立法院追認，若立法院不同意則立即失效。", "因果／影響": "總統身為國家元首掌管國防、外交與國安大政，在危難時可透過緊急命令迅速調動國家資源；但憲法明定其命令須受行政院會議決議及立法院追認的制衡，防止元首權力無限擴張。", "出處": "自修第 272～273 頁／教學式講義第 38 頁（試題寶典評量第 29 頁、評量單第 7 回）。", "標示": "講義標為「<b>重點分析</b>」，試題寶典標為「<b>必考重點</b>」。"}, "imgs": ["c4-map-emerg"], "clusters": [{"t": "緊急命令：行政院會議決議→總統發布→10 日內立法院追認", "n": 14, "ids": ["c4-11", "c4-19", "c4-21", "c4-24", "c4-48", "c4-60", "c4-92", "c4-145", "c4-207", "c4-306", "c4-333", "c4-353", "c4-372", "c4-384"]}, {"t": "國家元首：統率三軍、國安大政", "n": 5, "ids": ["c4-1", "c4-105", "c4-136", "c4-347", "c4-530"]}, {"t": "總統的人事權與其他職權", "n": 5, "ids": ["c4-30", "c4-83", "c4-169", "c4-212", "c4-360"]}]}], "questions": [{"id": "c4-1", "no": 1, "c": "c1", "src": "教學式講義第 40 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "某人物發表演說時提到：「我統率陸海空三軍，我的責任就是維護全體國人生產安全，我會和國軍站在同一陣線，共同守護國家安全。」上述人物最可能為何？", "o": ["總統", "大法官", "行政院院長", "國防部部長"], "a": 0, "e": "總統是國家元首，統率全國陸海空三軍。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-2", "no": 2, "c": "c4", "src": "教學式講義第 40 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "阿寶在臉書上與網友起了口角，對話被對方截圖後，一狀告到地方法院。上述提及的地方法院隸屬於下列哪一中央政府機關？", "o": ["考試院", "立法院", "行政院", "司法院"], "a": 3, "e": "各級法院（含地方法院）隸屬司法院。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-3", "no": 3, "c": "c6", "src": "教學式講義第 41 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "監察委員得對違法或失職的公務人員行使彈劾權，但不包括下列哪一位官員？", "o": ["總統", "行政院院長", "國防部部長", "考選部部長"], "a": 0, "e": "監察院不能彈劾總統；總統、副總統彈劾案由立法院提出。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-4", "no": 4, "c": "c3", "src": "教學式講義第 41 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "政府研議修正《國家安全法》等法規，加以管制假新聞，但是在執行之前，需要先經過哪個中央政府機關通過該法律修正案？", "o": ["司法院", "監察院", "考試院", "立法院"], "a": 3, "e": "法律的制定與修正須經立法院三讀通過。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-5", "no": 5, "c": "c6", "src": "教學式講義第 41 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "我國中央政府機關中，除了立法院之外，還有哪一機關具有監督政府施政的權力？", "o": ["考試院", "行政院", "司法院", "監察院"], "a": 3, "e": "監察院可透過糾正、糾舉、彈劾、審計監督政府施政。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-6", "no": 6, "c": "c7", "src": "教學式講義第 42 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "當行政院認為立法院所通過的總預算案窒礙難行時，得經由總統核可後，移請立法院做何種處理？", "o": ["覆議", "解散立法院", "行使糾正權", "提出不信任案"], "a": 0, "e": "行政院認為立法院決議窒礙難行，得經總統核可移請立法院覆議。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-7", "no": 7, "c": "c7", "src": "教學式講義第 42 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "2018 年，保加利亞的行政首長鮑里索夫因無力解決政府腐敗的問題，遭保加利亞國民議會提出不信任案，但因表決未獲半數以上議員支持而沒有通過。若上述情況發生在我國，後續的發展應該會是如何？", "o": ["行政院院長須請辭", "總統得解散立法院", "立法委員須重新選舉", "一年內立法院不得再對同一行政院院長提不信任案"], "a": 3, "e": "不信任案未通過，一年內不得對同一行政院院長再提不信任案。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-8", "no": 8, "c": "c7", "src": "教學式講義第 42 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "朴槿惠是南韓第一位女總統，曾因「親信干政」事件成為南韓第一位遭到彈劾並解職的總統。若上述情況發生在我國，下列何者是我國總統彈劾案生效的必要條件？", "o": ["經國會改選", "經大法官解釋", "經憲法法庭審理", "經選舉人投票複決"], "a": 2, "e": "總統彈劾案由立法院提出，須經司法院大法官組成憲法法庭審理判決成立才生效。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-9", "no": 9, "c": "c3", "src": "教學式講義第 43 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "小田一生最大的願望就是擔任立法院院長，他必須透過何種方式才能達成心願？", "o": ["請總統直接任命", "先當選立法委員再參選院長", "由行政院院長提請總統任命", "由總統提名並經過立法院同意"], "a": 1, "e": "立法院院長由立法委員互選，所以要先當選立法委員。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-10", "no": 10, "c": "c2", "src": "教學式講義第 43 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(一)為行政院院長聽取教育部報告，並做出決議的示意圖。圖中內容屬於政府哪一權力的展現？\n圖(一)內容：教育部報告「因地震而毀損的校舍現狀」，行政院院長裁示「將撥款進行校舍重建」。", "o": ["立法權", "考試權", "監察權", "行政權"], "a": 3, "e": "行政院院長聽取部會報告、做出決議，是行政權（執行政策）的展現。", "rep": true, "img": "c4-q10", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-11", "no": 11, "c": "c1", "src": "教學式講義第 43 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "我國的國家元首為總統，是國家的代表象徵，除了出席國內外各項重大活動之外，總統的職權還包括下列何者？", "o": ["發布緊急命令", "制定、修正法律", "提名立法院院長", "編列中央政府預算"], "a": 0, "e": "總統可發布緊急命令。制定法律是立法院；立法院院長由立委互選；預算由行政院編列。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-12", "no": 12, "c": "c3", "src": "教學式講義第 44 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "某政府機關發布新聞稿：「本屆考試院院長、副院長及考試委員之 9 位被提名人，是本機關向各界廣徵適格人才，並經過審薦小組嚴謹專業之作業程序考量提名。本機關尊重『某院』人事同意權審查的結果，惟對部分人選未獲同意，仍表達遺憾。」上述「某院」指的是下列哪一中央政府機關？", "o": ["行政院", "立法院", "監察院", "司法院"], "a": 1, "e": "考試院人員由總統提名，所以發布新聞稿的是總統府；「某院」行使人事同意權的是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-13", "no": 13, "c": "c3", "src": "教學式講義第 44 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "下列是立法委員阿緯一週的活動行程，何者不應該出現在他的工作列表中？", "o": ["公布修正通過的法律", "審查中央政府的總預算", "向衛福部部長提出質詢", "聆聽行政院院長施政報告"], "a": 0, "e": "公布法律是總統的職權，不是立法委員。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-14", "no": 14, "c": "c4", "src": "教學式講義第 44 頁 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "小萍正在瀏覽某一政府機關的網頁，在其「業務綜覽」頁面看到圖(二)的畫面。根據圖中內容判斷，小萍應該是瀏覽哪一政府機關的網頁？\n圖(二)內容：法庭審判席插圖，標示「強化專業審理裁判」。", "o": ["立法院", "行政院", "司法院", "監察院"], "a": 2, "e": "「強化專業審理裁判」是法院審判工作，屬司法院。", "rep": false, "img": "c4-q14", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-15", "no": 15, "c": "c5", "src": "教學式講義第 44 頁 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "透過各類公職考試，政府機關可以公正的選取公務人員。辦理上述各類公職考試的中央政府機關，還有下列何項職權？", "o": ["發布緊急命令", "提案彈劾總統", "負責公務員撫卹、退休事宜", "解釋《憲法》、法律和命令"], "a": 2, "e": "辦理公職考試的是考試院，考試院也負責公務員撫卹、退休。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-16", "no": 16, "c": "c7", "src": "教學式講義第 44 頁 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "我國的立法機關對於政府施政表現感到不滿意時，可提出不信任案。依我國《憲法增修條文》規定，立法院提出不信任案時，其行使對象是下列何者？", "o": ["正、副總統", "司法院院長", "立法院院長", "行政院院長"], "a": 3, "e": "不信任案的對象是行政院院長。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-17", "no": 17, "c": "c7", "src": "教學式講義第 44 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "以下為某新聞報導，文中提及的「甲機關」和「乙機關」依序應為下列何者？「我國前駐外代表被控性騷擾女性部屬，違反對方意願進行肢體碰觸，遭『甲機關』通過彈劾、移送『乙機關』。『乙機關』審理後，判處撤職、停止任用 2 年，並罰款 30 萬元。」", "o": ["監察院、審計部", "監察院、懲戒法院", "司法院、憲法法庭", "司法院、最高法院"], "a": 1, "e": "駐外代表是公務人員，由監察院彈劾、移送司法院懲戒法院審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-18", "no": 18, "c": "c6", "src": "教學式講義第 44 頁 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "中央政府某機關首長表示：「行政院 112 年度中央政府總決算案，經過本機關審核，歲入決算增加為 2 兆 9073 億元，歲出決算審定為 2 兆 6277 億元，歲入歲出相抵後賸餘 2796 億元。」上述機關首長最可能隸屬於下列何者？", "o": ["審計部", "銓敘部", "憲法法庭", "懲戒法院"], "a": 0, "e": "審核中央政府總決算的是監察院審計部。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-19", "no": 19, "c": "c1", "src": "教學式講義第 44 頁 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "總統在國家遭遇緊急情況時發布的緊急命令，必須在 10 日內提交立法院追認，否則失效。上述此種政府運作設計的主要目的為何？", "o": ["避免政府濫權", "落實司法獨立", "避免施政失當", "避免濫用私人"], "a": 0, "e": "緊急命令須經立法院追認，是以立法權制衡總統，避免政府濫權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-20", "no": 20, "c": "c7", "src": "教學式講義第 45 頁 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(三)呈現出我國中央政府的分權制衡關係，根據內容判斷，圖中的甲處應會出現何種文字？\n圖(三)：行政院院長 -> 呈請解散 -> 總統 -> 被動解散 -> 立法院；立法院 -> ①甲 -> 行政院院長。", "o": ["彈劾", "覆議", "重新選舉", "提出不信任案"], "a": 3, "e": "立法院對行政院院長提出不信任案，通過後院長辭職並得呈請總統解散立法院。", "rep": true, "img": "c4-q20", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-21", "no": 21, "c": "c1", "src": "教學式講義第 45 頁 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "南美洲厄瓜多的電力供應主要仰賴水力發電，但在 2024 年，由於遭遇嚴重乾旱，厄瓜多陷入嚴重缺電的能源危機。為此政府宣布進入 60 天的緊急狀態，除實施斷電措施，也部署軍隊和警察保護能源基礎設施。若上述事件發生在我國，下列何者是政府依法最可能採取的應變方式？", "o": ["由法院核發保護令，避免人民陷入緊急危難", "由總統發布緊急命令，以加快動員反應速度", "由立法院訂定行政命令，限制民眾人身自由", "由部會首長直接修改法律，以即時調度能源"], "a": 1, "e": "在我國，緊急命令由總統經行政院會議決議後發布，並於 10 日內提交立法院追認。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-22", "no": 22, "c": "c2", "src": "教學式講義第 45 頁 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "現代民主國家是以選舉人透過投票的方式來落實主權在民的理念，圖(四)為我國選舉人行使投票權的情況。圖中圈選的選票上不可能印有下列何者的字樣？\n圖(四)：選民在投票所票匭前準備投入選票。", "o": ["總統", "立法委員", "行政院院長", "《憲法》修正案"], "a": 2, "e": "行政院院長由總統任命，不是人民選出，選票上不會有。", "rep": false, "img": "c4-q22", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-23", "no": 23, "c": "c6", "src": "教學式講義第 45 頁 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(五)為小萍在瀏覽某一政府機關網站時讀到的部分內容，根據圖中內容判斷，小萍最可能在瀏覽哪一機關的網站？\n圖(五)調查報告案由：「○○市府多名員警涉案，違法與不法業者接觸交往……核有重大違失，爰依法提案糾正。」", "o": ["立法院", "總統府", "司法院", "監察院"], "a": 3, "e": "對員警違失提出糾正、調查報告，是監察院的職權。", "rep": false, "img": "c4-q23", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-24", "no": 24, "c": "c1", "src": "教學式講義第 45 頁 第 16 題", "st": "講義", "ctx": "", "fig": "", "q": "根據我國《憲法增修條文》的規定，當國家處於緊急狀態，但現有法制不足以排除危難或應付重大變故時，得發布「緊急命令」。下列何者不會參與緊急命令的發布流程？", "o": ["總統", "行政院", "立法院", "憲法法庭"], "a": 3, "e": "緊急命令由總統經行政院會議決議後發布、立法院追認，司法院不參與。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-25", "no": 25, "c": "c7", "src": "教學式講義第 45 頁 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(六)是若瑜在監察院網站上看到的資料，根據我國中央政府的運作原則判斷，圖中的甲應為下列何者？\n圖(六)公文內容：「……公務員不得兼任業務……失職事證明確，監察院宣布彈劾這名處長，移送(甲)審議。」", "o": ["審計部", "總統府", "懲戒法院", "憲法法庭"], "a": 2, "e": "監察院彈劾公務人員後，移送司法院懲戒法院審理。", "rep": true, "img": "c4-q25", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-26", "no": 26, "c": "c5", "src": "教學式講義第 46 頁 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "某政府機關建置官方網站推出「公務人員退休金試算器」（如圖(七)所示），以便公務人員了解自身的權益。根據圖中內容判斷，此試算器最可能是由哪一政府機關所提供？\n圖(七)內容：「公務人員退休金試算器」，包含身分、退離給與、計算方式等欄位。", "o": ["審計部", "銓敘部", "考選部", "內政部"], "a": 1, "e": "公務人員退休事宜由考試院銓敘部主管。", "rep": true, "img": "c4-q26", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-27", "no": 27, "c": "c7", "src": "教學式講義第 46 頁 第 19 題", "st": "講義", "ctx": "", "fig": "", "q": "亞倫參加金頭腦比賽，其中一題的題目是：「下列哪一組我國公職人員的產生方式相同」，亞倫應該選擇下列何者才能順利晉級？", "o": ["監察院院長、行政院院長", "立法委員、行政院副院長", "總統、立法院院長", "大法官、監察委員"], "a": 3, "e": "大法官、監察委員都是總統提名、經立法院同意後任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-28", "no": 28, "c": "c7", "src": "教學式講義第 46 頁 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "新聞報導：「法國總統馬克宏於 2024 年末發表演出時承認，解散國會是個錯誤的決定，為國家帶來了更多政治動盪。」我國總統也有解散國會的權力，但是要在下列哪一前提下才能發動？", "o": ["立法院提案罷免總統，選舉人投票通過後主動解散國會", "不信任案通過，行政院院長宣布辭職並呈請總統解散國會", "大法官組成憲法法庭審理總統彈劾案通過後主動解散國會", "覆議案在立法院表決維持原決議，行政院長呈請總統解散國會"], "a": 1, "e": "總統只能在立法院通過不信任案後，經行政院院長呈請才能解散立法院（被動解散）。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-29", "no": 29, "c": "c7", "src": "教學式講義第 46 頁 第 21 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(八)為國會頻道所播放的畫面片段，圖中內容凸顯出我國中央政府的運作，符合下列何項原則？\n圖(八)電視新聞直播畫面：外交國防委員會「外交部業務報告並備質詢」，外交部長接受立法委員質詢。", "o": ["政黨政治", "分權制衡", "主權在民", "三權分立"], "a": 1, "e": "國會（立法院）監督行政院，體現分權制衡。", "rep": false, "img": "c4-q29", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-30", "no": 30, "c": "c1", "src": "教學式講義第 46 頁 第 22 題", "st": "講義", "ctx": "", "fig": "", "q": "第 60 屆美國總統就職典禮在美國首都華盛頓舉行，我國依慣例籌組代表團出席祝賀。出發前，代表團團長即(甲)立法院院長與其他七名(乙)立法委員，在(丙)外交部部長的安排下，至總統府與(丁)總統會面，總統表示期待慶賀團傳達我國人民衷心的祝福，以及對民主堅定的承諾。上文中畫線處的公職人員，哪二位的產生方式相同？", "o": ["甲、乙", "乙、丁", "丙、丁", "甲、丙"], "a": 1, "e": "立法院院長由立委互選，立法委員由人民選出；外交部部長由行政院院長提請總統任命。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-31", "no": 31, "c": "c7", "src": "教學式講義第 46 頁 第 23 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(九)是中華民國中央政府預算、決算作業流程，圖中作業流程不涉及下列哪一機關的職權？\n圖(九)：編列預算(行政院) -> 審查預算(立法院) -> 執行預算做成決算(行政院) -> 審核決算(審計部) -> 審議審核報告(立法院)", "o": ["行政院", "立法院", "考試院", "監察院"], "a": 2, "e": "預算決算流程只涉及行政院、立法院、監察院（審計部），不涉及考試院。", "rep": true, "img": "c4-q31", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-32", "no": 32, "c": "c7", "src": "教學式講義第 48 頁 第 30 題", "st": "講義", "ctx": "", "fig": "", "q": "宋朝宰相王安石力圖變法，但因個性固執，不採納眾人意見，加上用人不當，導致變法失敗，若某部連續劇讓王安石以穿越時空的方式，意外成為我國最高行政機關首長，然而他的作風依舊不變，引發朝野不滿。根據我國現行政體制判斷，下列何者最可能是穿越時空後的王安石將面臨的處境？", "o": ["由憲法法庭審理", "被監察院提案糾正", "遭立法院提出彈劾案", "遭立法院提出不信任案"], "a": 3, "e": "行政院院長若施政不得民心，立法院可對其提出不信任案。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-33", "no": 33, "c": "c5", "src": "教學式講義第 48 頁 第 31 題", "st": "講義", "ctx": "2018 年，有女性民眾通過政府辦理的消防警察特考，卻因身高 158.9 公分不符規定，受訓資格遭廢。該民眾不服，因而聲請大法官審理法律是否違反《憲法》。2024 年，大法官判決該規定違憲，認為其所設身高標準，使女性應考試、服公職的權益受到不利的差別待遇。由此案例可以看出，大法官扮演著守護人民基本權利的最後一道防線。而為了讓大法官所代表的司法權不受到任何干涉，維持獨立地位，在我國《憲法》中有特別的設計，例如：《憲法》規定法官為終身職；《憲法增修條文》則規定，司法院提出的年度司法概算，行政院不得刪減，但得加註意見，編入中央政府總預算案。", "fig": "", "q": "文中辦理消防警察特考的政府機關，應隸屬下列何者？", "o": ["行政院", "司法院", "考試院", "監察院"], "a": 2, "e": "消防警察特考屬國家考試，由考試院辦理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-34", "no": 34, "c": "c4", "src": "教學式講義第 48 頁 第 32 題", "st": "講義", "ctx": "2018 年，有女性民眾通過政府辦理的消防警察特考，卻因身高 158.9 公分不符規定，受訓資格遭廢。該民眾不服，因而聲請大法官審理法律是否違反《憲法》。2024 年，大法官判決該規定違憲，認為其所設身高標準，使女性應考試、服公職的權益受到不利的差別待遇。由此案例可以看出，大法官扮演著守護人民基本權利的最後一道防線。而為了讓大法官所代表的司法權不受到任何干涉，維持獨立地位，在我國《憲法》中有特別的設計，例如：《憲法》規定法官為終身職；《憲法增修條文》則規定，司法院提出的年度司法概算，行政院不得刪減，但得加註意見，編入中央政府總預算案。", "fig": "", "q": "文中提及的大法官除了審理法律是否違憲之外，還擁有下列哪一職權？", "o": ["審理總統、副總統彈劾案", "提出總統、副總統罷免案", "對總統提名的官員行使人事同意權", "向立法院提出施政方針與施政報告"], "a": 0, "e": "大法官組成憲法法庭，也審理總統、副總統彈劾案及政黨違憲解散案。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-35", "no": 35, "c": "c3", "src": "教學式講義第 48 頁 第 33 題", "st": "講義", "ctx": "2018 年，有女性民眾通過政府辦理的消防警察特考，卻因身高 158.9 公分不符規定，受訓資格遭廢。該民眾不服，因而聲請大法官審理法律是否違反《憲法》。2024 年，大法官判決該規定違憲，認為其所設身高標準，使女性應考試、服公職的權益受到不利的差別待遇。由此案例可以看出，大法官扮演著守護人民基本權利的最後一道防線。而為了讓大法官所代表的司法權不受到任何干涉，維持獨立地位，在我國《憲法》中有特別的設計，例如：《憲法》規定法官為終身職；《憲法增修條文》則規定，司法院提出的年度司法概算，行政院不得刪減，但得加註意見，編入中央政府總預算案。", "fig": "", "q": "文中提及的中央政府總預算案，須經下列哪一機關審查通過才可執行？", "o": ["總統府", "審計部", "行政院", "立法院"], "a": 3, "e": "中央政府總預算須經立法院審查通過。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-36", "no": 36, "c": "c6", "src": "教學式講義第 48 頁 第 34 題", "st": "講義", "ctx": "某位檢察官在任職地方檢察署期間，曾涉及多起爭議事件，包括對外籍被告問訊時，疑似使用歧視言論，還質疑被告對臺灣社會有無幫助。另外，在處理一件妨害婚姻案件中，他還不顧專責相關檢查的檢驗員外出執行勤務的情況下，堅持勘驗女性被告的身體，且勘驗完後也未讓被告在筆錄簽名，程序上有明顯瑕疵。該位檢察官由於涉嫌違反《檢察官倫理規範》，加上有損司法威信，遭彈劾通過，並送交「相關單位」做進一步的審理。", "fig": "", "q": "文中檢察官最可能是遭下列哪一公職人員彈劾？", "o": ["總統", "大法官", "監察委員", "立法委員"], "a": 2, "e": "公務人員（檢察官）由監察委員提出彈劾。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-37", "no": 37, "c": "c4", "src": "教學式講義第 48 頁 第 35 題", "st": "講義", "ctx": "某位檢察官在任職地方檢察署期間，曾涉及多起爭議事件，包括對外籍被告問訊時，疑似使用歧視言論，還質疑被告對臺灣社會有無幫助。另外，在處理一件妨害婚姻案件中，他還不顧專責相關檢查的檢驗員外出執行勤務的情況下，堅持勘驗女性被告的身體，且勘驗完後也未讓被告在筆錄簽名，程序上有明顯瑕疵。該位檢察官由於涉嫌違反《檢察官倫理規範》，加上有損司法威信，遭彈劾通過，並送交「相關單位」做進一步的審理。", "fig": "", "q": "文末提及的「相關單位」最可能為下列何者？", "o": ["銓敘部", "憲法法庭", "懲戒法院", "各級法院"], "a": 2, "e": "公務人員被彈劾後移送懲戒法院審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-38", "no": 38, "c": "c3", "src": "教學式講義第 49 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(一)是國會頻道播放我国立法委員的宣誓就職典禮，誓詞內容提到：「余誓以至誠，恪遵《憲法》，效忠國家，代表人民依法行使職權，不徇私舞弊……。」上述立法委員代表人民行使的各項職權中，不包括下列何者？\n圖(一)：立法院議場內立委宣誓就職畫面。", "o": ["任命行政院院長", "審查中央政府總預算", "議決全國通行的法律", "提出《憲法》修正案"], "a": 0, "e": "立法委員代表人民行使制定法律、審查預算、質詢等職權。", "rep": false, "img": "c4-q38", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-39", "no": 39, "c": "c4", "src": "教學式講義第 49 頁 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(二)為一則網友分享的訊息，根據訊息內容判斷，最有可能在下列哪一個的機關網站看到圖中這場言詞辯論？\n圖(二)內容：針對苗栗地方法院法官聲請釋憲案，即刑法第 239 條通姦罪是否違憲，此釋憲案會在憲法法庭舉行言詞辯論，並將在網站上同步直播。", "o": ["監察院", "總統府", "立法院", "司法院"], "a": 3, "e": "憲法法庭言詞辯論屬司法院。", "rep": false, "img": "c4-q39", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-40", "no": 40, "c": "c7", "src": "教學式講義第 50 頁 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(三)為一則新聞，根據標題判斷，下列哪一句敘述最可能出現在該則新聞內容中？\n圖(三)新聞標題：「公務員違法兼職 調查結果屬實 13人遭彈劾」", "o": ["行政院對監察院的彈劾提出覆議", "立法院提案罷免遭彈劾的公務員", "立法院對違法公務員所屬機關提出不信任案", "遭彈劾的公務員將送交司法院懲戒法院審理"], "a": 3, "e": "對違法失職公務員提出彈劾、移送懲戒法院，是監察院的職權。", "rep": false, "img": "c4-q40", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-41", "no": 41, "c": "c7", "src": "教學式講義第 50 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "2024 年底，時任南韓總統尹錫悅發布戒嚴令，不到一日便遭撤銷。國會認為該行為違憲，且造成社會動盪，因此提出對尹錫悅的彈劾案。若上述情況發生在我國，後續最可能會有下列何種發展？", "o": ["立法院提出不信任案", "交由選舉人投票複決", "由懲戒法院依法審判", "由憲法法庭合議審理"], "a": 3, "e": "在我國，總統彈劾案由立法院提出，交憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-42", "no": 42, "c": "c6", "src": "教學式講義第 50 頁 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(五)是某則新聞報導，其中部分螢幕被飲料杯擋住了。根據圖中內容推斷，被飲料杯擋住的文字最可能為下列何者？\n圖(五)電視Live直播：「立法院今天針對總統提名的口口口口行使同意權」。", "o": ["審計長", "行政院院長", "法務部部長", "立法院院長"], "a": 0, "e": "審計長由總統提名、立法院行使同意權。", "rep": false, "img": "c4-q42", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-43", "no": 43, "c": "c7", "src": "教學式講義第 51 頁 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "2024 年 12 月初，法國國會由於不滿意政府提出的 2025 年總預算案，通過對總理（法國的行政首長）巴尼耶的不信任案。若上述情況發生在我國，後續最可能會有下列何種發展？", "o": ["不信任案公告半年後由選舉人投票複決", "不信任案交由大法官召開憲法法庭審理", "行政院院長辭職，並得呈請總統解散立法院", "行政院將通過的不信任案，移請立法院覆議"], "a": 2, "e": "不信任案通過，行政院院長應於 10 日內辭職，並得呈請總統解散立法院。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-44", "no": 44, "c": "c5", "src": "教學式講義第 51 頁 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "根據我國辦理公職考試的中央政府機關統計，近年公職考試的報考人數逐年減少，從 2012 年的 51.5 萬人下滑到 2023 年 18.6 萬人，反映公務人員的辭職人數則持續增加。上述辦理公職考試的機關，最可能還擁有下列何項職權？", "o": ["糾正行政機關", "質詢政府官員", "審理公務人員彈劾案", "負責公務人員退休事宜"], "a": 3, "e": "辦理公職考試的是考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-45", "no": 45, "c": "c2", "src": "教學式講義第 51 頁 第 16 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(六)為我國政府為維護國人健康所公布的規範。圖中規範的規畫與執行，屬於政府哪一權力的展現？\n圖(六)海報內容：「注意 回國入境 攜帶電子煙重罰 最高500萬元！」", "o": ["行政權", "立法權", "考試權", "監察權"], "a": 0, "e": "規畫並執行政策（如健康規範）屬行政權。", "rep": false, "img": "c4-q45", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-46", "no": 46, "c": "c3", "src": "教學式講義第 51 頁 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "行政院為因應日益嚴重的犯罪問題，舉辦跨機關的研討會，右表是中央各院依其職權可採行的改善方案。根據表中內容判斷，哪一機關還具有「提出總統、副總統罷免案」的職權？\n表格：甲「加速審判，伸張社會正義」、乙「修改法律，加重犯罪刑罰」、丙「糾正防審不力的警政機關」、丁「招考維護治安的警察人員」", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "乙為立法院（修改法律），立法院也能提出總統、副總統罷免案。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-47", "no": 47, "c": "c6", "src": "評量單第 7 回 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "下列哪一中央政府機關負責監督政府的施政及經費運用，具有糾正、糾舉、彈劾、審計等權力？", "o": ["司法院", "立法院", "監察院", "考試院"], "a": 2, "e": "監察院具有糾正、糾舉、彈劾、審計權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-48", "no": 48, "c": "c1", "src": "評量單第 7 回 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "下列何人統率全國陸海空三軍，決定國家安全大政方針，且有權發布緊急命令？", "o": ["總統", "大法官", "行政院院長", "立法院院長"], "a": 0, "e": "總統統率三軍、決定國家安全大政方針，並可發布緊急命令。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-49", "no": 49, "c": "c2", "src": "評量單第 7 回 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "因應流行性感冒疫情，疫苗施打需求大增，政府計畫增購 10 萬劑公費流感疫苗，儘速提供高風險對象接種。上述計畫應由我國哪一中央政府機關負責執行？", "o": ["司法院", "行政院", "監察院", "考試院"], "a": 1, "e": "執行政策、計畫的是行政院（衛生福利部）。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-50", "no": 50, "c": "c4", "src": "評量單第 7 回 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "大法官是人民基本權利保障及解決機關憲政爭議的最終途徑。下列何者是大法官的職權？", "o": ["審理法律是否違憲", "同意總統提名的官員", "提出總統、副總統彈劾案", "審理總統、副總統罷免案"], "a": 0, "e": "大法官審理法律是否違憲。同意權是立法院；彈劾案由立法院提出；罷免案交選舉人投票。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-51", "no": 51, "c": "c3", "src": "評量單第 7 回 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "立法院為我國的國會，擁有許多重要職權，下列何者不是其職責？", "o": ["質詢行政院官員", "制定、修改法律", "審查中央政府總預算", "懲戒違法的公務人員"], "a": 3, "e": "懲戒違法公務人員是司法院懲戒法院的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-52", "no": 52, "c": "c7", "src": "評量單第 7 回 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "在我國，下列哪一組公職人員的產生方式相同？", "o": ["總統、立法院院長", "監察委員、考試委員", "監察院院長、行政院院長", "監察委員、行政院副院長"], "a": 1, "e": "監察委員、考試委員都是總統提名、立法院同意。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-53", "no": 53, "c": "c6", "src": "評量單第 7 回 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "老師正在黑板整理監察院的各項職權，下列何者最可能會出現在板書中？", "o": ["審理政黨違憲的解散案件", "審查中央政府的年度預算", "彈劾政府機關的違法官員", "掌理公務人員的退休事宜"], "a": 2, "e": "監察院可彈劾違法官員。(A)憲法法庭(B)立法院(D)考試院。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-54", "no": 54, "c": "c4", "src": "評量單第 7 回 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "我國負責訴訟審判的「各級法院」，皆隸屬於中央政府的哪一機關？", "o": ["考試院", "行政院", "司法院", "監察院"], "a": 2, "e": "各級法院隸屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-55", "no": 55, "c": "c7", "src": "評量單第 7 回 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "在我國，甲編列預算並提送乙審查通過後，這些預算才得以使用。上述甲、乙分別是下列何者？", "o": ["行政院、立法院", "行政院、監察院", "立法院、監察院", "行政院、司法院"], "a": 0, "e": "行政院編列預算，送立法院審查。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-56", "no": 56, "c": "c5", "src": "評量單第 7 回 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "某官員曾表示：「作為公務人員退休、撫卹制度的主管機關，本部支持合理、永續的退撫制度改革，使未來所有公務人員都能領到退休金。」上述官員應隸屬下列哪一機關？", "o": ["考選部", "銓敘部", "內政部", "財政部"], "a": 1, "e": "公務人員退休、撫卹的主管機關是考試院銓敘部。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-57", "no": 57, "c": "c7", "src": "評量單第 8 回 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "根據我國《憲法》及《憲法增修條文》的相關規定，若要對總統、副總統進行彈劾，必須先由立法院提案通過後，再經何種程序才可完成？", "o": ["監察院表決", "憲法法庭審理", "最高法院判決", "選舉人投票複決"], "a": 1, "e": "總統、副總統彈劾案由立法院提出，交憲法法庭審理。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-58", "no": 58, "c": "c7", "src": "評量單第 8 回 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "行政院對於立法院決議之法律案、預算案、條約案，如認為有窒礙難行時，得向立法院提出覆議。上述行政院做出覆議的先決條件是什麼？", "o": ["經總統核可", "經總統解散立法院", "經大法官會議審理", "經選舉人投票複決"], "a": 0, "e": "覆議須先經總統核可。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-59", "no": 59, "c": "c7", "src": "評量單第 8 回 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "我國中央政府的行政與立法部門，對重大政策出現歧見時，可以採取提出覆議、不信任案與解散制度等方式來因應，這些制度的設計最符合下列何者的意涵？", "o": ["主權在民", "分權制衡", "責任政治", "政黨輪替"], "a": 1, "e": "覆議、不信任案與解散制度讓行政、立法互相制衡，符合分權制衡。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf", "c4-map-veto"], "chk": ""}, {"id": "c4-60", "no": 60, "c": "c1", "src": "評量單第 8 回 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "總統在發布緊急命令後，應在 10 日內提交口進行追認，如口不同意時，該緊急命令立即失效。上述口應該填入下列何者？", "o": ["監察院", "行政院", "立法院", "憲法法庭"], "a": 2, "e": "緊急命令發布後 10 日內提交立法院追認。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-61", "no": 61, "c": "c7", "src": "評量單第 8 回 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "下列為總統、副總統與公務人員的彈劾途徑比較。根據內容判斷，何者錯誤？\n表格：總統、副總統違法失職 -> 甲提出彈劾案 -> 乙審理；公務人員違法失職 -> 丙提出彈劾案 -> 丁審理。", "o": ["甲：立法院", "乙：司法院", "丙：監察院", "丁：考試院"], "a": 3, "e": "丁應為司法院懲戒法院審理，不是考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-62", "no": 62, "c": "c7", "src": "評量單第 8 回 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "2013 年，我國在野黨立法委員曾提出對行政院院長的不信任案，在立法院內表決時，以贊成 46 票、反對 66 票，不信任案未通過。根據上述，不信任案未通過後的發展應為下列何者？", "o": ["行政院院長應提出辭職", "行政院向立法院提出覆議", "立法委員必須重新選舉", "一年內不得對同一行政院院長再提不信任案"], "a": 3, "e": "不信任案未通過，一年內不得對同一行政院院長再提出不信任案。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-63", "no": 63, "c": "c4", "src": "評量單第 8 回 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "下列是兩位鄰居的對話，根據對話內容，兩人提及的甲機關，應為下列何者？\n玲玲：聽說有一名公務人員因為收受業者的賄賂，被彈劾了。\n小新：對啊！甲機關所屬懲戒法院已經受理了。", "o": ["考試院", "行政院", "司法院", "監察院"], "a": 2, "e": "懲戒法院隸屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-64", "no": 64, "c": "c3", "src": "評量單第 8 回 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "立法院有制定法律與質詢政府官員的權力，另外還具有預算審查權，決定行政部門可使用的支出。根據上述的設計，顯示立法院能發揮下列何種功能？", "o": ["懲戒行政權", "支配司法權", "監督行政權", "制衡審判權"], "a": 2, "e": "質詢、審查預算是立法院監督行政權的功能。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-65", "no": 65, "c": "c2", "src": "試題寶典評量第 32 頁 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "行政院共有 15 部，下列何者是行政院之職務？", "o": ["舉辦國家考試", "任免公務人員", "規畫國家政策", "糾舉失職之公務員"], "a": 2, "e": "行政院負責規畫國家政策並執行。(A)(B)考試院(D)監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-66", "no": 66, "c": "c5", "src": "試題寶典評量第 32 頁 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "彭先生在汐止區公所服務滿 25 年，他打算辦理退休相關事宜。彭先生若想上網查詢公務人員退休相關資料，應該到下列哪一機關的網站查詢？", "o": ["司法院", "立法院", "行政院", "考試院"], "a": 3, "e": "公務人員退休事宜由考試院（銓敘部）主管。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-67", "no": 67, "c": "c3", "src": "試題寶典評量第 32 頁 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "交通及建設部研擬針對限制電動自行車騎乘者的年齡提出《道路交通管理處罰條例》修正草案，草案仍需經哪一機關三讀通過後方能實施？", "o": ["監察院", "立法院", "行政院", "司法院"], "a": 1, "e": "法律修正草案須經立法院三讀通過。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-68", "no": 68, "c": "c5", "src": "試題寶典評量第 32 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "「選拔、任用優秀人才做為國家公務人員」此為五權中的何種權力？", "o": ["考試權", "立法權", "監察權", "行政權"], "a": 0, "e": "選拔任用公務人員屬考試權。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-69", "no": 69, "c": "c3", "src": "試題寶典評量第 32 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "許先生在當選立法委員之後，他將可以依《憲法》規定行使下列哪一種職權？", "o": ["處理公務員懲戒事項", "統一解釋法律及命令", "對各機關年度決算行使審計權", "提出總統、副總統彈劾案"], "a": 3, "e": "立法委員可提出總統、副總統彈劾案。(A)懲戒法院(B)大法官(C)監察院審計權。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-70", "no": 70, "c": "c6", "src": "試題寶典評量第 32 頁 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "近年來考試院、監察院的存廢引發爭論，下列哪一項權力不是監察院的職權？", "o": ["糾舉權", "彈劾權", "罷免權", "審計權"], "a": 2, "e": "罷免權不是監察院職權；總統罷免案由立法院提出。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-71", "no": 71, "c": "c4", "src": "試題寶典評量第 32 頁 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "雨嫣正在抄寫公民課的重點整理筆記，根據表(一)的筆記內容判斷，她應該正在抄寫哪一個政府機關的重點？\n表(一)產生方式：由總統提名，經立法院同意後任命。職權：(1)掌理各種訴訟的審判。(2)處理公務人員違法失職之懲戒事項。(3)解釋憲法及統一解釋法律、命令。(4)審理政黨違憲解散案件及總統、副總統彈劾案。", "o": ["司法院", "行政院", "監察院", "立法院"], "a": 0, "e": "表(一)內容（憲法法庭、各級法院、懲戒法院）屬司法院。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-72", "no": 72, "c": "c3", "src": "試題寶典評量第 32 頁 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "有關立法院的提案權，下列敘述何者錯誤？", "o": ["憲法修正案由選舉人投票複決", "領土變更案由選舉人投票複決", "總統、副總統罷免案由監察委員投票複決", "總統、副總統彈劾案由大法官召開憲法法庭審理"], "a": 2, "e": "總統、副總統罷免案由立法院提出，交選舉人投票，不是監察委員。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-73", "no": 73, "c": "c7", "src": "試題寶典評量第 32 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "新聞報導：「立法院日前通過《漁會法》修正案，行政院在收到立法院公文後，認為窒礙難行，且不符合公平正義，決定呈請總統核可，將法案再送回立法院重新討論。」行政院將立法院所通過的法案送回立法院重新討論，是指下列哪一種制度？", "o": ["複決", "不信任案", "覆議", "附議"], "a": 2, "e": "行政院認為窒礙難行，經總統核可移請立法院重新討論，這是覆議。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-74", "no": 74, "c": "c4", "src": "試題寶典評量第 34 頁 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "2020 年我國中央政府為防範新冠肺炎疫情，五院配合中央指揮中心展開各項工作，下列是疫情中各機關職權的配對，其中何者有誤？", "o": ["考試院：延後公務人員高考考試日期", "行政院：向民間徵用口罩以及禁止出口", "監察院：對失職的公務人員提出彈劾案", "立法院：解釋紓困條例是否有違反憲法"], "a": 3, "e": "解釋法律是否違憲是司法院大法官（憲法法庭）的職權，不是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-75", "no": 75, "c": "c2", "src": "試題寶典評量第 34 頁 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "我國每逢 520 政權交接周年，總會掀起一波對執政內閣人事的檢討聲浪。關於我國中央重要人事職務的產生方式，下列何項錯誤？", "o": ["總統由公民直接選舉產生", "立法院院長由立法委員互選產生", "行政院院長由總統直接任命", "教育部長由總統提名，立法院同意後任命"], "a": 3, "e": "行政院院長由總統直接任命，不須立法院同意。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-76", "no": 76, "c": "c7", "src": "試題寶典評量第 34 頁 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "表(二)的內容中，甲、乙、丙、丁應該分別填入哪一個政府機關？\n表(二)法律：制定（甲）、公布（乙）、執行（丙）、解釋（丁）", "o": ["行政院、立法院、司法院、監察院", "立法院、總統、行政院、司法院", "總統、行政院、立法院、司法院", "立法院、總統、行政院、監察院"], "a": 1, "e": "法律由立法院制定、總統公布、行政院執行、司法院解釋。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-77", "no": 77, "c": "c5", "src": "試題寶典評量第 34 頁 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "由圖(三)報紙報導內容判斷，這應該是中央哪一個機關所發布的新聞？\n圖(三)報紙內容：大公日報「1.院會通過今年鐵路特考開缺 601 人。2.院會通過公務人員高考三級考試暨普考考試規則第 11 條。3.召開全院審查會，討論公務人員年金制度。」", "o": ["考試院", "監察院", "行政院", "立法院"], "a": 0, "e": "特考開缺、考試規則、公務人員年金都是考試院業務。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-78", "no": 78, "c": "c4", "src": "試題寶典評量第 34 頁 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "下列是小義完成「認識我國官員」的報告，但因他的誤植，其中只有哪一位政府官員所說的內容正確？", "o": ["我是立法院院長，由行政院院長直接任命", "我是行政院院長，由總統提名後還需經考試委員同意", "我是監察委員，由監察院院長直接任命", "我是司法院大法官，總統提名我，經立法院同意後就任"], "a": 3, "e": "大法官由總統提名、經立法院同意後就任。其他三人的產生方式都說錯了。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-79", "no": 79, "c": "c7", "src": "試題寶典評量第 34 頁 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "權力分立的體制可避免政府的濫權，表(三)有關我國中央政府五權間制衡關係的敘述，何者正確？\n表(三)：甲「審查預算：監察院」、乙「質詢行政院官員：司法院」、丙「同意總統提名之人事案：考試院」、丁「提覆議案：行政院」", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "行政院可向立法院提出覆議；審查預算是立法院；質詢行政院官員是立法院；同意人事案是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-80", "no": 80, "c": "c2", "src": "試題寶典評量第 35 頁 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "我國行政院與立法院兩者的互動關係牽動著政治局勢的發展。下列關於兩者的互動，何者敘述正確？", "o": ["立法院可向行政院提起覆議", "行政院院長擁有解散立法院的權力", "行政院依法向立法院負責", "行政院可對立法院提出不信任案"], "a": 2, "e": "行政院依法向立法院負責。覆議是行政院向立法院提出；解散立法院是總統。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-81", "no": 81, "c": "c2", "src": "試題寶典評量第 35 頁 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "中央政府於「食品安全聯合稽查專案小組」會議決議，將對液蛋與夜市攤商使用之生鮮蛋品來源、產品與製程衛生是否符合規範加強檢驗，並追溯來源牧場的動物用藥管理，以維護國內液蛋供應鏈的衛生安全及保障消費者權益。召開此一會議的應為下列何者？", "o": ["行政院", "考試院", "司法院", "立法院"], "a": 0, "e": "食品安全稽查屬行政院（衛生福利部）的行政工作。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-82", "no": 82, "c": "c7", "src": "試題寶典評量第 35 頁 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "同學正在討論有關我國中央政府的組織與職權，下列何者正確？\n(A)「我爸任職法務部，是司法院的下屬單位。」\n(B)「懲戒法院可以對中央公務人員提出彈劾。」\n(C)「審計部負責審查中央政府所提出的預算。」\n(D)「立法院可對行政院院長提出不信任案。」", "o": ["我爸任職法務部，是司法院的下級單位", "懲戒法院可以對中央公務人員提出彈劾", "審計部負責審查中央政府所提出的預算", "立法院可對行政院院長提出不信任案"], "a": 3, "e": "立法院可對行政院院長提出不信任案。法務部屬行政院；彈劾是監察院；審查預算是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-83", "no": 83, "c": "c1", "src": "試題寶典評量第 35 頁 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "司法院大法官共計 15 位，其中 7 位大法官在民國 113 年任期屆滿。甲必須對此缺額進行提名，因此組成立法院大法官提名審薦小組，公開接受各界推薦大法官人選。上文中的甲應為下列何者？", "o": ["立法委員", "司法院院長", "總統", "審計長"], "a": 2, "e": "大法官由總統提名，所以甲是總統。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-84", "no": 84, "c": "c7", "src": "試題寶典評量第 35 頁 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "2012 年 9 月針對當時政府爆發前行政院秘書長涉貪以及內政問題表達不滿，在野黨對行政院院長提出不信任案，進行我國史上第 2 次倒閣案的表決。然而開票結果，46 票贊成，66 票反對，倒閣以失敗告終。有關該次不信任案的敘述，下列何者正確？", "o": ["須由監察院進行投票", "若通過，立法委員須重新選舉", "通過後，行政院院長可拒絕辭職", "如未獲通過，則三年內不得對同一行政院院長再提不信任案"], "a": 1, "e": "不信任案未通過，一年內不得對同一行政院院長再提。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-85", "no": 85, "c": "c4", "src": "試題寶典評量第 35 頁 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "小夫在某個網站讀到下列訊息：「本院『量刑準據八大系統』建置完成，未來法官可參考『量刑行情』，減少歧異，發揮司法定紛止爭的功能。」小夫應該是在哪一個中央政府機關的網頁看到此則訊息？", "o": ["行政院", "立法院", "司法院", "考試院"], "a": 2, "e": "量刑準據、法官審判屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-86", "no": 86, "c": "c3", "src": "試題寶典評量第 36 頁 第 16 題", "st": "講義", "ctx": "", "fig": "", "q": "甲在質詢行政院衛生福利部部長時，指出某飲料製造商早已知道自家產品出現變質問題，嚴重影響消費者權益，但該公司卻不主動回收處理，反而繼續販售變質的產品，對於這種明知故犯的行為，政府應予以重罰。關於甲所擔任的公職，下列敘述何者正確？", "o": ["負責審查法律是否違憲", "負責審查中央政府預算", "經由地方層級的選舉所產生", "由行政院院長提請總統任命"], "a": 1, "e": "質詢行政院部會首長的是立法委員。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-87", "no": 87, "c": "c6", "src": "試題寶典評量第 36 頁 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "監察委員看見電視上新聞報導遊行抗議的事件後，便主動申請調查此案，並表示若調查後確認民眾抗議的內容屬實，將依法對布條上的抗議對象提出糾正案。下列何者最可能是該委員在新聞中所看見的抗議事件標語？", "o": ["鴨霸縣長 官商勾結", "財政機關 政策失當", "行政官員 接受關說", "《集會遊行法》違憲"], "a": 1, "e": "糾正的對象是行政機關（對事），所以抗議對象是某行政機關。", "rep": true, "img": "c4-q87", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-88", "no": 88, "c": "c4", "src": "試題寶典評量第 36 頁 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "我國國會可對中央政府部分官員的人事提名案行使同意權，並在投票表決前，藉由提問來審查被提名人是否適任。根據我國公職人員的法定職權判斷，下列哪一個問題的提問對象最可能是大法官被提名人？", "o": ["如何提升違法官員彈劾案件的辦案效率", "如何落實嚴謹審核中央政府年度總決算", "我國仍維持死刑刑罰是否違反基本人權", "公務人員的選才制度是否有改善的空間"], "a": 2, "e": "大法官負責解釋憲法，提問應與違憲審查相關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-89", "no": 89, "c": "c3", "src": "試題寶典評量第 36 頁 第 19 題", "st": "講義", "ctx": "", "fig": "", "q": "某日阿朗透過網路觀看立法院的議事實況轉播，根據我國現行法律規定，他最可能看見下列何者的轉播情況？", "o": ["審理總統、副總統彈劾案", "表決對行政院的糾正提案", "召開行政院會議規畫施政方針", "行政院部會首長進行施政報告"], "a": 3, "e": "行政院部會首長到立法院進行施政報告。(A)憲法法庭(B)糾正是監察院(C)行政院會議在行政院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-90", "no": 90, "c": "c7", "src": "試題寶典評量第 36 頁 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "我國立法院、監察院二院分別與司法院於特定事項的處理上有先後順序，當立法院與監察院做出某些決定後，即交由司法院接續下一步的工作。表(四)為立法院與監察院的部分職權內容，其中哪些職權的行使符合上述關係？\n表(四)：\n立法院：甲「提出《憲法》修正案」、乙「提出總統、副總統彈劾案」\n監察院：丙「糾正行政機關不當施政」、丁「彈劾違法公務人員」", "o": ["甲、丙", "甲、丁", "乙、丙", "乙、丁"], "a": 3, "e": "立法院提出總統副總統彈劾案、監察院彈劾違法公務人員後，都交司法院（憲法法庭、懲戒法院）審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-91", "no": 91, "c": "c5", "src": "試題寶典第 40 頁 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "下列四人都說自己任職於「考試院」，但其中哪一個人的說法與事實不符？", "o": ["我們專門處理違法失職的懲戒事項", "我們負責國家公務人員考試", "各級公務人員退休事宜由我們主管", "我們主辦專門職業及技術人員考試"], "a": 0, "e": "懲戒事項是司法院懲戒法院的職權，不是考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-92", "no": 92, "c": "c1", "src": "試題寶典第 40 頁 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "臺灣在 921 大地震時，政府曾發布緊急命令。關於緊急命令的相關敘述，下列何者正確？", "o": ["是由行政院院長發布", "發布後十日內必須提交立法院追認", "是由總統府決議", "總統可以在任何情況下發布"], "a": 1, "e": "緊急命令由總統經行政院會議決議後發布，10 日內須提交立法院追認。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-93", "no": 93, "c": "c3", "src": "試題寶典第 40 頁 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "丹麥國會於 2016 年 1 月表決通過移民改革法案，對難民進行嚴格的控管政策，未來法律將允許當地警察沒收難民財物，並延長難民與家屬團聚申請的等待時間。丹麥國會的職權與我國中央政府哪一個機關最相近？", "o": ["監察院", "立法院", "行政院", "考試院"], "a": 1, "e": "丹麥國會表決法案，相當於我國立法院制定法律的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-94", "no": 94, "c": "c7", "src": "試題寶典第 40 頁 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "立法院與行政院的互動相當密切，下列有關兩院的關係，何者敘述錯誤？", "o": ["行政院必須向立法院提出施政方針與施政報告", "行政院可以對立法院院長提出不信任案", "立法院有向行政院院長及各部會首長進行質詢的職權", "立法院通過不信任案後，行政院院長可呈請總統解散立法院"], "a": 1, "e": "不信任案是立法院對行政院院長提出，行政院不能對立法院院長提出。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-95", "no": 95, "c": "c4", "src": "試題寶典第 40 頁 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "下列是博丞作文中的其中一段內容，從他的作文中，可以知道他的爺爺是在哪一個機關上班？「我的家人中以前爺爺的身分最特別了，因為常常在新聞中聽到有人聲請釋憲，而爺爺他的工作就是負責解釋《憲法》，這真是一個既神聖又特別的職業。」", "o": ["司法院", "立法院", "考試院", "監察院"], "a": 0, "e": "審理聲請釋憲的是司法院大法官。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-96", "no": 96, "c": "c4", "src": "試題寶典第 41 頁 第 1 題", "st": "講義", "ctx": "2018 年有女性民眾通過消防警察特考，卻因身高僅 158.9 公分，不符規定，受訓資格遭廢，因而聲請大法官審理法律是否違反《憲法》。2024 年大法官判決該規則違憲，認為該規則所設的身高標準，使女性應考試服公職的權益受到不利的差別待遇，與《憲法》保障平等權的意旨不符。內政部及考選部表示，基於勤務需要與保護消防人員安全等考量，消防人員需具備一定身高，認為此規則並無違憲。然而，在大法官宣告此規則違憲後，也等於讓制定此規則的機關必須重新修訂法規。由此案例可看出，大法官扮演著守護人民基本權利的最後一道防線。而為了讓大法官所代表的司法不受到任何干涉，維持獨立地位，《憲法》規定法官為終身職；《憲法增修條文》則規定，司法院提出的年度司法概算，行政院不得刪減，但得加註意見，編入中央政府總預算案，送立法院審議，最後送至「甲機關」審核決算。", "fig": "", "q": "文中負責審理法律是否違憲的職位，其產生方式為何？", "o": ["司法院院長直接任命", "行政院院長提名，總統任命", "總統提名，立法院同意後由總統任命", "立法院提名，總統同意後行政院院長任命"], "a": 2, "e": "大法官由總統提名，立法院同意後由總統任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-97", "no": 97, "c": "c5", "src": "試題寶典第 41 頁 第 2 題", "st": "講義", "ctx": "2018 年有女性民眾通過消防警察特考，卻因身高僅 158.9 公分，不符規定，受訓資格遭廢，因而聲請大法官審理法律是否違反《憲法》。2024 年大法官判決該規則違憲，認為該規則所設的身高標準，使女性應考試服公職的權益受到不利的差別待遇，與《憲法》保障平等權的意旨不符。內政部及考選部表示，基於勤務需要與保護消防人員安全等考量，消防人員需具備一定身高，認為此規則並無違憲。然而，在大法官宣告此規則違憲後，也等於讓制定此規則的機關必須重新修訂法規。由此案例可看出，大法官扮演著守護人民基本權利的最後一道防線。而為了讓大法官所代表的司法不受到任何干涉，維持獨立地位，《憲法》規定法官為終身職；《憲法增修條文》則規定，司法院提出的年度司法概算，行政院不得刪減，但得加註意見，編入中央政府總預算案，送立法院審議，最後送至「甲機關」審核決算。", "fig": "", "q": "文中畫雙底線處的兩個機關（內政部、考選部），分別隸屬哪兩個院？", "o": ["立法院、行政院", "行政院、司法院", "行政院、行政院", "行政院、考試院"], "a": 3, "e": "內政部屬行政院，考選部屬考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-98", "no": 98, "c": "c6", "src": "試題寶典第 41 頁 第 3 題", "st": "講義", "ctx": "2018 年有女性民眾通過消防警察特考，卻因身高僅 158.9 公分，不符規定，受訓資格遭廢，因而聲請大法官審理法律是否違反《憲法》。2024 年大法官判決該規則違憲，認為該規則所設的身高標準，使女性應考試服公職的權益受到不利的差別待遇，與《憲法》保障平等權的意旨不符。內政部及考選部表示，基於勤務需要與保護消防人員安全等考量，消防人員需具備一定身高，認為此規則並無違憲。然而，在大法官宣告此規則違憲後，也等於讓制定此規則的機關必須重新修訂法規。由此案例可看出，大法官扮演著守護人民基本權利的最後一道防線。而為了讓大法官所代表的司法不受到任何干涉，維持獨立地位，《憲法》規定法官為終身職；《憲法增修條文》則規定，司法院提出的年度司法概算，行政院不得刪減，但得加註意見，編入中央政府總預算案，送立法院審議，最後送至「甲機關」審核決算。", "fig": "", "q": "文中的「甲機關」應為下列何者？", "o": ["立法院", "審計部", "憲法法庭", "行政院"], "a": 1, "e": "審核決算的是監察院審計部。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-99", "no": 99, "c": "c2", "src": "114上翰林社會2上A卷 第5卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "2024 年我國舉行總統、副總統選舉，由民主進步黨的賴清德當選，隨之而來便是政府團隊的重組。上述的「政府團隊」是指下列何者？", "o": ["行政院", "立法院", "司法院", "考試院"], "a": 0, "e": "新總統上任後重組的「政府團隊」是行政院（內閣）。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-100", "no": 100, "c": "c3", "src": "114上翰林社會2上A卷 第5卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "現代民意政治的運作原則中，政府政策的制定，必須參考人民的需求，且獲得多數民意的同意後才能執行。根據上述說法，下列何者為政府必須依法執行？", "o": ["在野黨領袖的建議", "行政院官員的看法", "立委候選人的政見", "立法院通過的議案"], "a": 3, "e": "經立法院通過的法律，政府必須依法執行。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-101", "no": 101, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)為中央政府針對臺南強震災後重建，在預算與決算的審查程序。下列各階段負責機關的配對，何者正確？\n圖(一)：甲(編列預算) -> 乙(審查預算) -> 執行預算 -> 丙(審核決算) -> 丁(審議決算審核報告)", "o": ["甲 -> 立法院", "乙 -> 司法院", "丙 -> 審計部", "丁 -> 行政院"], "a": 2, "e": "審核決算的是監察院審計部。", "rep": false, "img": "c4-q101", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-102", "no": 102, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列各中央政府機關首長的產生方式，何者正確？", "o": ["立法院院長——人民直接選舉方式產生", "審計長——監察院院長提名，總統任命", "司法院院長——總統提名，立法院同意", "行政院院長——總統提名，立法院同意"], "a": 2, "e": "司法院院長由總統提名、立法院同意。立法院院長由立委互選；審計長由總統提名、立法院同意；行政院院長由總統直接任命。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-103", "no": 103, "c": "c2", "src": "114上翰林社會2上A卷 第5卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)是小程接受記者訪問時的談話內容，依內容判斷，小程服務的單位應是下列哪一個機關？\n圖(二)內容：記者採訪小程「近來勞工過勞死個案頻傳，但死者家屬申請理賠時，卻常遭遇提出具體因公致死的困難，因此我們決定針對身心過勞做出更寬鬆的認定。」", "o": ["行政院", "立法院", "司法院", "監察院"], "a": 3, "e": "小翔要對勞動部提出糾正案，是監察院的職權。", "rep": false, "img": "c4-q103", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-104", "no": 104, "c": "c5", "src": "114上翰林社會2上A卷 第5卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據圖(三)判斷，小明是參加我國中央政府哪一個機關所辦行的考試？\n圖(三)內容：小明背書包說「我希望能可以通過這項公職考試，然後去法務部工作。」", "o": ["文化部", "銓敘部", "考選部", "審計部"], "a": 2, "e": "辦理國家考試的是考試院考選部。", "rep": true, "img": "c4-q104", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-105", "no": 105, "c": "c1", "src": "114上翰林社會2上A卷 第5卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "總統為我國國家元首，依據《憲法》授權具有多項的人事任命權，下列哪一位職位任命權不屬於總統？", "o": ["行政院院長", "立法院院長", "監察院院長", "考試院院長"], "a": 1, "e": "立法院院長由立法委員互選，不是總統任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-106", "no": 106, "c": "c3", "src": "114上翰林社會2上A卷 第5卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據圖(四)內容判斷，下列何者最可能坐在臺下聽取施政報告？\n圖(四)內容：台上標示「行政院院長至立法院施政報告」，院長在發言台上報告，台下坐著各委員。", "o": ["司法官員", "監察委員", "立法委員", "考試委員"], "a": 2, "e": "行政院院長向立法院提出施政報告，台下聽報告的是立法委員。", "rep": false, "img": "c4-q106", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-107", "no": 107, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "當總統、副總統不適任時，依規定應由立法院提出彈劾，並交由下列哪一個機關來處理？", "o": ["審計部", "監察院", "憲法法庭", "懲戒法院"], "a": 2, "e": "總統、副總統彈劾案由立法院提出，交憲法法庭審理。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-108", "no": 108, "c": "c5", "src": "114上翰林社會2上A卷 第5卷 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "又蓉於某政府機關網站中查詢相關資訊，如圖(五)所示，她可能透過此網站獲得哪一種資訊？\n圖(五)網站導覽清單：1.簡介 2.考銓資訊 3.培訓業務 4.退撫基金", "o": ["社會福利政策實施項目", "公務員升等考試相關訊息", "國中教育會考成績公告", "十二年國教教育政策規畫內容"], "a": 1, "e": "考試院網站提供公務員考試相關訊息。", "rep": false, "img": "c4-q108", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-109", "no": 109, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "立法院得提出不信任案，若不信任案通過後，下列何者必須下臺？", "o": ["總統", "行政院院長", "立法院院長", "司法院院長"], "a": 1, "e": "不信任案通過，行政院院長須辭職。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-110", "no": 110, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "若根據我國中央政府官員產生方式來看，關於圖(六)中四人的身分，何者推論正確？\n圖(六)：甲說「我要投給小珊當立法委員。」乙說「我要任命小亮擔任行政院院長。」丙說「我要提名小紫擔任法務部部長。」丁說「我要提名小楊擔任審計長。」", "o": ["甲是人民", "乙是總統", "丙是司法院院長", "丁是監察院長"], "a": 1, "e": "乙是總統（人民直選）。依原卷答案為 (B)。", "rep": false, "img": "c4-q110", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-111", "no": 111, "c": "c4", "src": "114上翰林社會2上A卷 第5卷 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "司法院為我國最高司法機關，具有公正裁判的權力。有關該院的法定職權，下列敘述何者正確？", "o": ["應由大法官組成憲法法庭", "主管公務人員國家考試", "由法官審理法律是否違憲", "設司法委員負責訴訟審判"], "a": 0, "e": "司法院由大法官組成憲法法庭。考試是考試院；違憲審查由大法官，不是一般法官。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-112", "no": 112, "c": "c3", "src": "114上翰林社會2上A卷 第5卷 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "志強為我國的立法委員，下列何者屬於其職權？", "o": ["審理法律是否有違憲", "地方公務人員彈劾權", "考試院人事同意權", "審核國庫的決算"], "a": 2, "e": "立法委員可對考試院人事行使同意權。(A)大法官(B)監察院(D)監察院審計部。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-113", "no": 113, "c": "c5", "src": "114上翰林社會2上A卷 第5卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "某護理師因搶救患者後返任職務，搭乘黑鷹直升機墜海身亡。官員解釋本案符合「冒險犯難」因公撫卹，但請領最高等級撫卹需更嚴謹的認定。上述官員最可能屬於哪一機關？", "o": ["教育部", "銓敘部", "考選部", "審計部"], "a": 1, "e": "公務人員撫卹由考試院銓敘部主管。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-114", "no": 114, "c": "c6", "src": "114上翰林社會2上A卷 第5卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察院為我國最高監察機關，監察委員具有監督政府施政及經費運用的權力。下列何者不屬於上述委員的職權？", "o": ["對失職的公務人員提出彈劾案", "向違法的公務員之上級長官提出糾舉", "處理公務人員違法失職的懲戒事項", "對各行政機關的不當施政提出糾正案"], "a": 2, "e": "審查預算等不是監察委員的職權；監察委員可彈劾、糾舉、糾正、審計。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-115", "no": 115, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "下表中有關我國總統、副總統彈劾案的流程配對，哪一項配對正確？\n表格：\n甲：提出機關「行政院」、決議方式「選舉人投票複決」\n乙：提出機關「立法院」、決議方式「憲法法庭審理」\n丙：提出機關「監察院」、決議方式「選舉人投票複決」\n丁：提出機關「司法院」、決議方式「懲戒法院審理」", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "總統、副總統彈劾案由立法院提出，交憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-116", "no": 116, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國中央政府五院院長的產生方式，何者正確？", "o": ["考試院院長由考試委員互選產生", "司法院院長由總統提名，經立法院行使同意權", "總統直接任命司法院最高法庭審判長為司法院院長", "監察院院長由監察委員相互推舉，審計長同意後任命"], "a": 1, "e": "司法院院長由總統提名，經立法院同意。考試院院長同樣是提名同意，不是互選。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-117", "no": 117, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "針對 2024 年底(甲)三讀通過《公職人員選舉罷免法》的修正條文，增訂罷免案連署時應附身分證影本，若冒用他人個資連署可判處有期徒刑或罰金。(乙)召開院會認為此法案窒礙難行，呈請(丙)核可，移請(丁)覆議。請判斷下列選項何者正確？", "o": ["甲：司法院", "乙：監察院", "丙：行政院", "丁：立法院"], "a": 3, "e": "甲＝立法院三讀、乙＝行政院、丙＝總統核可、丁＝移請立法院覆議。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-118", "no": 118, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(七)是我國中央政府互相制衡的部分機制與互動，下列選項何者錯誤？\n圖(七)：行政院呈請解散(甲)立法院；行政院院長辭職被動解散；立法院對行政院長提(乙)；立法院三讀決議(丁)送交行政院，行政院認為窒礙難行呈請總統核可提(丙)。", "o": ["甲——否決立法院制定的法律", "乙——對行政院院長提不信任案", "丙——覆議", "丁——法律案、預算案與條約案"], "a": 0, "e": "甲處應是總統解散立法院（被動解散），總統不能否決立法院制定的法律。", "rep": false, "img": "c4-q118", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-119", "no": 119, "c": "c4", "src": "114上翰林社會2上A卷 第5卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "2024 年底，立法院針對大法官人事同意案進行投票，結果七名大法官被提名人全數遭到否決。對此，後續可能會發生下列何種狀況？", "o": ["行政院長重新提名", "總統呈請立法院覆議", "憲法法庭將缺乏院長", "影響憲法法庭的運作"], "a": 3, "e": "大法官人數不足，會影響憲法法庭的運作；大法官由總統重新提名。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-120", "no": 120, "c": "c6", "src": "114上翰林社會2上A卷 第5卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "2024 年臺北市某餐廳疑因處理食物不當，導致 6 人食物中毒死亡。相關人員查出臺北市政府進行調查，發現市府於當天中午接獲通報，卻遲至傍晚才到現場稽查，且未立即對相關據點進行採樣、封存及下架，有明顯違失，於是提案糾正。針對上述內容，推斷下列何者正確？", "o": ["文中提到的相關人員為監察委員", "呈現出行政機關受立法機關監督", "糾正的對象為臺北市衛生局稽查員", "此案將送往公務員懲戒法院審理"], "a": 0, "e": "提案糾正的是監察委員。糾正對象是機關（臺北市政府），不是個人，也不移送懲戒法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-121", "no": 121, "c": "c5", "src": "114上翰林社會2上A卷 第5卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(八)為某政府機關舉辦遴選後所頒發的獎項。此「政府機關」應是下列何者？\n圖(八)證書內容：「公務人員傑出貢獻獎……此獎被譽為公務員的最高殊榮……經嚴選後選出 10 位公務人員，給予獎金及公假。」", "o": ["考選部", "教育部", "銓敘部", "福利部"], "a": 2, "e": "公務人員遴選、獎勵等人事事務屬考試院銓敘部。", "rep": false, "img": "c4-q121", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-122", "no": 122, "c": "c3", "src": "114上翰林社會2上A卷 第5卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "公民老師請同學們分組扮演五院的官員做自我介紹，下列哪一位同學的委詞正確？", "o": ["第一組「我是監察委員，可以彈劾總統」", "第二組「我是考試院長，負責違憲審查」", "第三組「我是行政院長，可解散立法院」", "第四組「我是立法委員，可以提案修憲」"], "a": 3, "e": "立法委員可以提出憲法修正案。監察委員不能彈劾總統；違憲審查是大法官；行政院院長不能主動解散立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-123", "no": 123, "c": "c7", "src": "114上翰林社會2上A卷 第5卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "行政院提出的覆議案在遭立法院 1/2 以上立委決定維持原決議，則行政院院長依法必須採取何種作為？", "o": ["呈請總統解散立法院", "執行立法院通過的決議案", "負起政治責任立即請辭下臺", "提出不信任案，要求罷免立法委員"], "a": 1, "e": "覆議時立法院 1/2 以上維持原決議，行政院院長應接受並執行該決議。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-124", "no": 124, "c": "c2", "src": "114上翰林社會2上A卷 第5卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "先前為了堅守疫情，行政院院長出席「桃園市防疫醫院聯防會議」，領導相關組織一同守護臺灣。有關上述公務人員，下列何者正確？", "o": ["應為我國的國家元首", "須到立法院接受質詢", "直接任命各部會首長", "得主動發布緊急命令"], "a": 1, "e": "行政院院長須到立法院接受質詢。元首是總統；部會首長由院長提請總統任命；緊急命令由總統發布。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-125", "no": 125, "c": "c3", "src": "114上翰林社會2上A卷 第5卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "許多選民遇到問題時經常向民意代表陳情，下列哪一封陳情信內容屬於立法院的職權？", "o": ["請您們編列預算時增加國民教育經費", "某縣政府公務員違法失職，請彈劾", "《社會秩序維護法》部分條文引發爭議，請提出《憲法》解釋", "《勞動基準法》部分條文已不合時宜，希望提案修改"], "a": 3, "e": "修改法律屬立法院職權。彈劾是監察院；釋憲是司法院。", "rep": false, "img": "c4-q125", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-126", "no": 126, "c": "c3", "src": "114上翰林社會2上B卷 第5卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)為日籍人民藤井嚴思推動的國家議案海報。由內容判斷，通過此一議案的流程應為何者？\n圖(一)內容：18歲公投海報。", "o": ["行政院提案由司法院審理", "立法院提案由司法院審理", "行政院提案由立法院投票複決", "立法院提案由選舉人投票複決"], "a": 3, "e": "憲法修正案（18 歲公民權）由立法院提出，交選舉人投票複決。", "rep": false, "img": "c4-q126", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-127", "no": 127, "c": "c3", "src": "114上翰林社會2上B卷 第5卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "政府機關三讀修正通過《勞動基準法》部分條文，明定每週工時不得超過四十小時，確立週休二日法源，雇主如果違反規定，須處以罰鍰。上文中的政府機構應是指下列何者？", "o": ["立法院", "司法院", "監察院", "行政院"], "a": 0, "e": "三讀通過法律的是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-128", "no": 128, "c": "c2", "src": "114上翰林社會2上B卷 第5卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列為我國中央政府某機關所發布的新聞摘要。由內容可知，此機關主要擁有何種權力？「銓敘部日前函請各機關加強法規宣導，不得赴中國設籍、領用身分證、護照或申請定居證、居住證，並填寫具結書一套，否則將會喪失擔任我國公職的權利。此通函完全是依據《臺灣地區與大陸地區人民關係條例》之規定，依法有據，並未擴張解釋相關規定。」", "o": ["行政權", "立法權", "監察權", "考試權"], "a": 3, "e": "銓敘部屬考試院，掌理公務人員銓敘等事務，屬考試權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-129", "no": 129, "c": "c4", "src": "114上翰林社會2上B卷 第5卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "憲法法庭 113 年憲判字第 11 號判決，就《遺產及贈與稅法》第 15 條規定：「被繼承人死亡前 2 年內贈與配偶之財產，應於被繼承人死亡時，視為被繼承人遺產，併入遺產總額，依規定徵稅。」憲法法庭認定此規定已侵害《憲法》保障人民的平等權與財產權。根據上述，關於憲法法庭的敘述何者正確？", "o": ["擁有立法權", "負責公務人員懲戒", "擁有法律的解釋權", "法官經國家考試合格任用"], "a": 2, "e": "憲法法庭（大法官）擁有解釋憲法與法律的權力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-130", "no": 130, "c": "c6", "src": "114上翰林社會2上B卷 第5卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據我國《審計法》規定，審計部之職權包括監督預算執行、審核財務收支、審核決算、考核財務效能、稽查財務上之違失、核定財務責任等，藉此提升政府施政績效，對抗貪腐等情事，充分發揮監督之角色。文中的審計部應隸屬於何者？", "o": ["監察院", "司法院", "行政院", "立法院"], "a": 0, "e": "審計部隸屬監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-131", "no": 131, "c": "c2", "src": "114上翰林社會2上B卷 第5卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "在野黨於新會期力推民生法案，修法通過「紀念日及節日實施條例」還給勞工 5 天國定假日。不過內政部報告指出，目前全年總放假日數已達到 115～116 日，放假日常多，應從國家整體利益綜合評估。上述提出報告的政府單位應隸屬於何者？", "o": ["司法院", "立法院", "行政院", "考試院"], "a": 2, "e": "內政部隸屬行政院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-132", "no": 132, "c": "c3", "src": "114上翰林社會2上B卷 第5卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "日前我國中央政府機關三讀通過「114年度中央政府總預算案」，共刪減約 2,075 億元，刪減金額創下歷史新高，仍較 113 年中央政府總預算增加 2.5%，故 114 年歲出預算仍為史上最高。上文中提到的中央政府機關應是指何者？", "o": ["立法院", "司法院", "行政院", "考試院"], "a": 0, "e": "三讀通過總預算的是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-133", "no": 133, "c": "c7", "src": "114上翰林社會2上B卷 第5卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "日前我國提名司法院正副院長與 7 位大法官人選，然而經過甲機關審查，進行大法官人事同意權案投票，最後 7 位大法官提名人全數遭到否決，導致憲法法庭因人數不足面臨癱瘓危機。上述中的甲與乙依序應為何？", "o": ["行政院、總統", "總統、立法院", "立法院、司法院", "總統、全民公投"], "a": 1, "e": "行使大法官人事同意權的是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-134", "no": 134, "c": "c5", "src": "114上翰林社會2上B卷 第5卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列何者為我國人事行政最高主管機關，專門負責文官的選拔與任用？", "o": ["行政院", "立法院", "考試院", "司法院"], "a": 2, "e": "考試院是最高考試機關，負責文官的選拔與任用。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-135", "no": 135, "c": "c6", "src": "114上翰林社會2上B卷 第5卷 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)為一則監察院發布的新聞稿。圖中○○部分應是指下列何者？\n圖(二)新聞稿：「行政院農業部及內政部未積極督導考核地方政府，加強查核及裁處農舍及其農業用地違規使用，致全國農舍及具農舍用地大量違規使用，嚴重破壞農業生產環境及妨礙農村發展，核有違失，爱依法提案○○。」", "o": ["糾舉", "彈劾", "糾正", "審計"], "a": 2, "e": "對機關的不當施政提出的是糾正案。", "rep": true, "img": "c4-q135", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-136", "no": 136, "c": "c1", "src": "114上翰林社會2上B卷 第5卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "依我國《憲法》規定，政府首長中何者有權統率全國三軍，決定國家安全大政方針？", "o": ["總統", "參謀總長", "國防部部長", "各軍總司令"], "a": 0, "e": "總統統率全國陸海空三軍，決定國家安全大政方針。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-137", "no": 137, "c": "c4", "src": "114上翰林社會2上B卷 第5卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列哪一機關下轄各級法院，包括地方法院、高等法院、最高法院以及行政法院？", "o": ["監察院", "立法院", "考試院", "司法院"], "a": 3, "e": "各級法院隸屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-138", "no": 138, "c": "c2", "src": "114上翰林社會2上B卷 第5卷 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據我國《憲法增修條文》規定，行政院院長應如何產生？", "o": ["公民直選", "立法委員投票", "總統直接任命", "參加國家考試"], "a": 2, "e": "行政院院長由總統直接任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-139", "no": 139, "c": "c6", "src": "114上翰林社會2上B卷 第5卷 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "孫中山先生結合三權分立的體制創立五權憲法架構，在我國的五權分立當中，何者具有監督政府施政及運用經費的權力？", "o": ["監察權", "司法權", "行政權", "考試權"], "a": 0, "e": "監察權負責監督政府施政及經費運用。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-140", "no": 140, "c": "c3", "src": "114上翰林社會2上B卷 第5卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據《憲法增修條文》，我國若要進行修憲，除了在該政府機關中要有四分之一席次人員提議、四分之三人員出席，以及必須要通過出席人員四分之三的決議，最後還要以公投複決。該政府機關最可能為下列何者？", "o": ["行政院", "立法院", "考試院", "司法院"], "a": 1, "e": "憲法修正案由立法院提出，交公民投票複決。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-141", "no": 141, "c": "c7", "src": "114上翰林社會2上B卷 第5卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)為總統、行政院與立法院三者在我國憲政設計上的關係圖示說明。根據圖中內容判斷，①、②分別為下列何者？\n圖(三)：行政院院長辭職被動解散；立法院向行政院提①；行政院院長辭職並呈請總統②解散立法院。", "o": ["①：被動解散，②：呈請解散立法院", "①：發布緊急命令，②：呈請總統解散立法院", "①：提出不信任案，②：呈請總統解散立法院", "①：提出不信任案，②：被動解散"], "a": 2, "e": "不信任案通過→行政院院長辭職並呈請總統解散立法院→總統被動解散立法院。", "rep": true, "img": "c4-q141", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-142", "no": 142, "c": "c7", "src": "114上翰林社會2上B卷 第5卷 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國司法院依《憲法》規定設有 15 位大法官，大法官產生方式與下列何者相同？", "o": ["審計長", "外交部部長", "行政院副院長", "立法院副院長"], "a": 0, "e": "大法官和審計長都由總統提名、立法院同意。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-143", "no": 143, "c": "c4", "src": "114上翰林社會2上B卷 第5卷 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "某地方政府經濟發展局局長於任期內，假借職務上的權力，要求並收受與業務上有利害關係者之賄賂等招待，同時不當指示下屬怠惰行事，造成開發案與採購案進度延宕與公庫損失，經彈劾通過後依法移送相關機關審理。上文中的相關機關應為何？", "o": ["立法院", "懲戒法院", "地方法院", "憲法法庭"], "a": 1, "e": "公務人員被彈劾後，移送懲戒法院審理。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-144", "no": 144, "c": "c7", "src": "114上翰林社會2上B卷 第5卷 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "韓國總統日前無預期發布戒嚴令，宣布全國進入戒嚴狀態，後在國會壓力下宣布解嚴，國會因此通過彈劾案。若依我國《憲法》規定，彈劾總統的程序應為何？", "o": ["行政院提案由司法院審理", "立法院提案由司法院審理", "監察院提案由司法院懲戒", "立法院提案交由選舉人投票複決"], "a": 1, "e": "總統彈劾案由立法院提出，交司法院憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-145", "no": 145, "c": "c1", "src": "114上翰林社會2上B卷 第5卷 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "歷史上曾出現多次造成重大傷亡的水災、旱災等天災，各朝代的皇帝多利用祭天祈禱、廣開糧倉，希望能藉此消解天災所帶來的衝擊。若上述事件發生在我國，下列何者是政府依法所能採取的應變方式？", "o": ["由法院核發保護令，避免災民陷入緊急危難", "由總統發布緊急命令，以加快動員救災速度", "由行政院訂定行政命令，限制民眾人身自由", "由財政首長直接調高稅率，以籌措鉅額經費"], "a": 1, "e": "遇重大天災，總統可經行政院會議決議發布緊急命令。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-146", "no": 146, "c": "c4", "src": "114上翰林社會2上B卷 第5卷 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "現代民主國家為落實權力分立的原則，各有不同的作法。我國將中央政府規畫成五院，其中某院除掌理各種訴訟審判之外，尚有懲戒違法失職公務人員的職權。由上述內容判斷，下列何者也屬該院的職權？", "o": ["質詢中央政府官員", "掌理公務員退休事宜", "審理政黨違憲解散事項", "對行政機關提出糾正"], "a": 2, "e": "掌理訴訟審判並懲戒公務人員的是司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-147", "no": 147, "c": "c7", "src": "114上翰林社會2上B卷 第5卷 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "某立委召開記者會，呼籲總統召開國是會議，讓臺灣社會能有安全溝通，就四個爭議、建立兩岸談判監督機制、修改公投法等議題，凝聚共識。下列有關立委與總統的敘述，何者正確？", "o": ["總統是我國最高行政機關", "總統有權主動解散立法院", "立法院可對總統行使罷免權", "立委與總統皆由人民選舉產生"], "a": 3, "e": "立法委員與總統都由人民直接選舉產生。(A)最高行政機關是行政院；(B)總統只能被動解散；(C)罷免案由立法院提出，交選舉人投票。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-148", "no": 148, "c": "c4", "src": "114上翰林社會2上B卷 第5卷 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "大風在某中央政府組織網站上看到象徵該組織的圖片（如圖(四)），上面寫著「公正、莊嚴、專業」，當人民權利受非法侵害時，可作為秉公處理的組織。該中央政府組織應是指下列何者？\n圖(四)：象徵司法審判的天秤圖像。", "o": ["行政院", "立法院", "考試院", "司法院"], "a": 3, "e": "「公正、莊嚴、專業」的院徽，是司法院。", "rep": false, "img": "c4-q148", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-149", "no": 149, "c": "c6", "src": "114上翰林社會2上B卷 第5卷 第 1 題", "st": "考卷", "ctx": "某檢察官因積案嚴重，遭「甲院」彈劾，移送懲戒法院後，被裁處休職半年。但某位主任檢察官表示，該檢察官對辦案有其堅持，要將案子調查清楚後才會結案，所以通常都會超過法務部規定的期限。", "fig": "", "q": "上文中的「甲院」應該是指下列何者？", "o": ["行政院", "司法院", "監察院", "立法院"], "a": 2, "e": "彈劾檢察官的「甲院」是監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-150", "no": 150, "c": "c4", "src": "114上翰林社會2上B卷 第5卷 第 2 題", "st": "考卷", "ctx": "某檢察官因積案嚴重，遭「甲院」彈劾，移送懲戒法院後，被裁處休職半年。但某位主任檢察官表示，該檢察官對辦案有其堅持，要將案子調查清楚後才會結案，所以通常都會超過法務部規定的期限。", "fig": "", "q": "上文中的懲戒法院隸屬於哪一個中央政府組織？", "o": ["行政院", "監察院", "立法院", "司法院"], "a": 3, "e": "懲戒法院隸屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-151", "no": 151, "c": "c2", "src": "114上翰林社會2上B卷 第5卷 第 3 題", "st": "考卷", "ctx": "某檢察官因積案嚴重，遭「甲院」彈劾，移送懲戒法院後，被裁處休職半年。但某位主任檢察官表示，該檢察官對辦案有其堅持，要將案子調查清楚後才會結案，所以通常都會超過法務部規定的期限。", "fig": "", "q": "上文中提及的法務部在組織層級上是隸屬行政院部會之一，而法務部部長的產生方式為何？", "o": ["總統直接任命", "人民直接選舉", "行政院院長直接任命", "行政院院長提請總統任命"], "a": 3, "e": "各部會首長由行政院院長提請總統任命。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-152", "no": 152, "c": "c7", "src": "114上翰林社會2上B卷 第5卷 第 4 題", "st": "考卷", "ctx": "某檢察官因積案嚴重，遭「甲院」彈劾，移送懲戒法院後，被裁處休職半年。但某位主任檢察官表示，該檢察官對辦案有其堅持，要將案子調查清楚後才會結案，所以通常都會超過法務部規定的期限。", "fig": "", "q": "官員彈劾案是由數個機關各司其職的運作，此為民主國家政府運作的何種原則？", "o": ["權力分立", "主權在民", "覆議制度", "專權政治"], "a": 0, "e": "彈劾案由監察院提出、司法院審理，各機關分工制衡，是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-153", "no": 153, "c": "c7", "src": "114上翰林社會2上B卷 第5卷 第 5 題", "st": "考卷", "ctx": "(甲)機關修正三讀通過攸關中央、地方財源分配的《財政收支劃分法》，對此財政部表示，114 年度中央政府因此需釋出財源新臺幣 3,753 億元，此將衝擊中央財政，造成預算調適困難。因此依照《憲法》增修條文第 3 條第 2 項第 2 款規定，經財政部提出並討論後，由(乙)院會提出並經總統核可，提出覆議案，請求《憲法》救濟，惟覆議案最後仍遭到(甲)否決……", "fig": "", "q": "上文中的甲與乙依序應為下列何者？", "o": ["立法院、行政院", "立法院、司法院", "行政院、司法院", "行政院、監察院"], "a": 0, "e": "甲三讀通過法律是立法院；乙院會提出覆議是行政院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-154", "no": 154, "c": "c3", "src": "114上翰林社會2上B卷 第5卷 第 6 題", "st": "考卷", "ctx": "(甲)機關修正三讀通過攸關中央、地方財源分配的《財政收支劃分法》，對此財政部表示，114 年度中央政府因此需釋出財源新臺幣 3,753 億元，此將衝擊中央財政，造成預算調適困難。因此依照《憲法》增修條文第 3 條第 2 項第 2 款規定，經財政部提出並討論後，由(乙)院會提出並經總統核可，提出覆議案，請求《憲法》救濟，惟覆議案最後仍遭到(甲)否決……", "fig": "", "q": "上文中的甲機關其職權應包含下列何者？", "o": ["制定行政命令", "質詢政府官員", "覆決總統副總統罷免案", "審核中央政府總預算決算"], "a": 1, "e": "立法院可質詢政府官員。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-155", "no": 155, "c": "c2", "src": "114上翰林社會2上B卷 第5卷 第 7 題", "st": "考卷", "ctx": "(甲)機關修正三讀通過攸關中央、地方財源分配的《財政收支劃分法》，對此財政部表示，114 年度中央政府因此需釋出財源新臺幣 3,753 億元，此將衝擊中央財政，造成預算調適困難。因此依照《憲法》增修條文第 3 條第 2 項第 2 款規定，經財政部提出並討論後，由(乙)院會提出並經總統核可，提出覆議案，請求《憲法》救濟，惟覆議案最後仍遭到(甲)否決……", "fig": "", "q": "上文中提到的財政部部長，其相關說明何者錯誤？", "o": ["擁有行政權", "負責國家財政規畫", "必須接受立法委員質詢", "須由總統提名立法院同意"], "a": 3, "e": "財政部部長由行政院院長提請總統任命，不須立法院同意。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-156", "no": 156, "c": "c4", "src": "114上翰林社會2上C卷 第5卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)中的新聞事件，若民眾對於此事件法律上是否違法有疑慮時，可以向下列何者聲請憲法法庭解釋？\n圖(一)新聞內容：臺北市公共工程關說弊案風波不斷，司法單位面臨各界的關議，處理關說在法律上是否違法……。", "o": ["立法院", "司法院", "法務部", "監察院"], "a": 1, "e": "聲請憲法法庭解釋，要向司法院提出。", "rep": false, "img": "c4-q156", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-157", "no": 157, "c": "c6", "src": "114上翰林社會2上C卷 第5卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "美華工作的機關，必須審核年度各政府機關的實際支出費用是否有不當之處，並做出報告。依據上述，美華工作的機關應該是下列何者？", "o": ["行政院", "司法院", "監察院", "審計院"], "a": 2, "e": "審核決算的是監察院審計部。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-158", "no": 158, "c": "c3", "src": "114上翰林社會2上C卷 第5卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "中央政府某院的院長由立法委員互選產生，其人事案不受總統提名。上述某院是指何者？", "o": ["行政院", "立法院", "考試院", "司法院"], "a": 1, "e": "立法院院長由立法委員互選產生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-159", "no": 159, "c": "c4", "src": "114上翰林社會2上C卷 第5卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "又青說：「我媽媽在司法院工作，每天都非常忙碌，因為他們單位要負責的事項很多。」依據上述，下列哪一項為又青媽媽的職務範圍？", "o": ["辦理國家公務人員考試", "審核公務人員任用資格", "掌管公務人員升遷事項", "懲戒違法失職公務人員"], "a": 3, "e": "懲戒違法失職公務人員是司法院懲戒法院的職權；其他是考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-160", "no": 160, "c": "c4", "src": "114上翰林社會2上C卷 第5卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "今天學校辦理家長職業分享日，阿法的母親分享她的工作內容：「曾處理過違法或失職的公務員懲戒事宜，也審理過關於違憲爭議的案件。」阿法的母親應是任職於哪一個單位？", "o": ["行政院", "司法院", "總統府", "考試院"], "a": 1, "e": "懲戒公務員、審理違憲案件都屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-161", "no": 161, "c": "c6", "src": "114上翰林社會2上C卷 第5卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "新聞報導：「某地方政府公務員疑似因長期工作過勞而猝死，對此中央政府某機構經過調查後對該單位提出糾正案，希望未來各單位也都能正視所有員工身心健康。」提出單位應為下列何者？", "o": ["行政院", "司法院", "監察院", "立法院"], "a": 2, "e": "對機關提出糾正案的是監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-162", "no": 162, "c": "c3", "src": "114上翰林社會2上C卷 第5卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "第一次當選立委的品瑜，正在熟悉立法委員的各項職權，下列哪一項屬於品瑜有權推動的事項？", "o": ["提出領土變更案", "司法院大法官的提名", "制定各級公職考試的年度計畫", "對中央五院院長皆可提出不信任案"], "a": 0, "e": "立法委員可提出領土變更案。大法官由總統提名；考試計畫是考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-163", "no": 163, "c": "c4", "src": "114上翰林社會2上C卷 第5卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "國內某企業集團已故創辦人遺產曝光，將名下約 500 多億元遺產全交由二房獨子繼承，此舉引發大房子女不滿，已委任律師提起訴訟。我國訴訟案件的審理屬於下列哪一機關？", "o": ["立法院", "行政院", "司法院", "監察院"], "a": 2, "e": "訴訟審理屬司法院各級法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-164", "no": 164, "c": "c3", "src": "114上翰林社會2上C卷 第5卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "立法院是我國中央最高民意機關，代替人民監督政府的施政，關於立法院的職權，下列說明何者正確？", "o": ["設立各級法院負責各種訴訟審判", "對總統提名的監察委員及審計長行使同意權", "立法委員須負責各項政策的規畫與法案的執行", "院長、副院長在立法委員選舉時一併經人民選舉產生"], "a": 1, "e": "立法院可對總統提名的監察委員、審計長行使同意權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-165", "no": 165, "c": "c2", "src": "114上翰林社會2上C卷 第5卷 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)為上課時老師說明「我國中央政府組織與職權」的相關內容。依內容判斷，圖中版面可能是下列哪一個中央政府機關的部分架構？\n圖(二)內容：○○院架構，轄下有教育部、運動部、國家發展委員會。", "o": ["司法院", "考試院", "立法院", "行政院"], "a": 3, "e": "圖中各部會屬行政院。", "rep": false, "img": "c4-q165", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-166", "no": 166, "c": "c5", "src": "114上翰林社會2上C卷 第5卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "新聞簡報：「這次會議以『完善考選制度，篩選適合公務人員』、『活化政府人力資源，健全契約用人制度』、『建立高階文官培訓與職務升遷結合制度，提升政府施政品質』三大議題為主，商討我國文官制度未來與平穩發展方向。」根據上述內容判斷，此新聞稿應該是中央政府的哪一機關所發布的？", "o": ["考試院", "監察院", "行政院", "立法院"], "a": 0, "e": "考選制度、文官培訓等是考試院的業務。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-167", "no": 167, "c": "c7", "src": "114上翰林社會2上C卷 第5卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "行政部門提出各種預算後，由各級民意代表審查，並由審計機關負責監督預算的執行情況，以掌握各項經費的運用是否確實並有效率。在我國，「預算的編列與審查」分別是由哪一機關負責？", "o": ["監察院、行政院", "行政院、立法院", "行政院、監察院", "考試院、行政院"], "a": 1, "e": "行政院編列預算，立法院審查預算。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-168", "no": 168, "c": "c6", "src": "114上翰林社會2上C卷 第5卷 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "明倫擔任監察委員期間，致力掃除公務機關內的不良陋習，並提出多次彈劾，希望官員能樹立典範，守法守紀。下列何者最可能是他彈劾的對象？", "o": ["副總統", "立法委員", "臺南市議員", "農業部部長"], "a": 3, "e": "監察委員可彈劾中央及地方公務人員（如地方首長、官員），不能彈劾正副總統與民意代表。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-169", "no": 169, "c": "c1", "src": "114上翰林社會2上C卷 第5卷 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "新聞報導：「○○提名大法官候選人，立法院在舉行公聽會及審查會後，進行同意權表決。」上述○○是指下列何者？", "o": ["行政院", "司法院", "總統府", "審計部"], "a": 2, "e": "大法官由總統提名，新聞稿由總統府發布。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-170", "no": 170, "c": "c7", "src": "114上翰林社會2上C卷 第5卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "行政院必須執行立法院通過的法律與政策，若行政院認為立法院決議的法律案、預算案與條約案窒礙難行時，得經總統核可後，向立法院行使哪一項職權？", "o": ["移請立法院覆議", "交付公民投票", "請求解散國會", "召開憲法法庭"], "a": 0, "e": "行政院可經總統核可，移請立法院覆議。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-171", "no": 171, "c": "c2", "src": "114上翰林社會2上C卷 第5卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列哪個政府首長的上張，最符合他自己的職權？", "o": ["監察院院長「我要為國家爭取進入聯合國」", "行政院院長「我要求全國警察機關，全力改善國內治安」", "考試院院長「我會鼓勵委員主動調查是否有公務人員違法失職，而予以彈劾」", "司法院院長「我希望將來可以推動租稅法案的修訂」"], "a": 1, "e": "行政院院長要求全國警察機關改善治安，符合行政權。其他院長說的都不是自己的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-172", "no": 172, "c": "c5", "src": "114上翰林社會2上C卷 第5卷 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據我國現行的法令規定，有關公務人員的考核與懲處，應分別由下列何機關進行？", "o": ["司法院、監察院", "考試院、司法院", "考試院、監察院", "監察院、司法院"], "a": 1, "e": "公務人員考核由考試院，懲處（懲戒）由司法院懲戒法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-173", "no": 173, "c": "c6", "src": "114上翰林社會2上C卷 第5卷 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察委員可對違法或失職的公務人員提出彈劾案，下列何者較可能為被提彈劾案的對象？", "o": ["總統", "市議員", "經濟部部長", "立法委員"], "a": 2, "e": "經濟部部長是公務人員，可被彈劾；總統、民意代表不行。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-174", "no": 174, "c": "c7", "src": "114上翰林社會2上C卷 第5卷 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "權力間的制衡是為了避免單一機構權力過度集中，並期望能相互監督之外，進一步能相互合作。關於我國權力制衡關係的敘述，下列何者正確？", "o": ["我國採行行政、立法、司法三權分立的制衡關係", "行政院對於立法院決議之法律案窒礙難行時，得經總統核可，移請立法院覆議", "立法院可對總統提出不信任案，通過後總統必須辭職下臺負起政治責任", "若總統因不信任案下臺，同時可宣布解散立法院"], "a": 1, "e": "行政院可經總統核可，移請立法院覆議。我國是五權分立；不信任案對象是行政院院長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-175", "no": 175, "c": "c4", "src": "114上翰林社會2上C卷 第5卷 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "喜愛歷史劇的小婷，發現古時候人民犯罪，負責調查和審判的是相同的單位，但現代社會負責刑事調查的是隸屬於法院，審判則是由法院進行。法院由中央政府哪一單位管理？", "o": ["行政院", "司法院", "檢察院", "考試院"], "a": 1, "e": "法院由司法院管理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-176", "no": 176, "c": "c5", "src": "114上翰林社會2上C卷 第5卷 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "小玉整理了中央機關某部門的業務單位及其職掌如下表。由表中內容可知，該部門應隸屬哪一機關？\n表格：法規司（人事政策等）、退撫司（公務人員及政務人員之保險、退休事宜）、人事管理司（各機關人事人員之管理、考試及格人員之分發）", "o": ["考試院", "司法院", "監察院", "行政院"], "a": 0, "e": "表中法規司、退撫司、人事管理司屬銓敘部，隸屬考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-177", "no": 177, "c": "c6", "src": "114上翰林社會2上C卷 第5卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察院是我國最高監察機關，下列何者為監察委員的職權？", "o": ["審查國家年度預算", "審理總統、副總統彈劾案", "處理公務人員的違法失職的懲戒事項", "對違法或失職的公務人員行使彈劾、糾舉權"], "a": 3, "e": "監察委員可對違法失職公務人員提出彈劾。(A)立法院(B)憲法法庭(C)懲戒法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-178", "no": 178, "c": "c6", "src": "114上翰林社會2上C卷 第5卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)是我國監察機關執法的相關新聞，圖中被汗漬所遮蓋的文字應該為何？\n圖(三)新聞內容：「監察委員表示：主管機關行政院、衛生福利部、環境保護署推動妥善處理違法使用農藥，防護不周，有損政府形象，本院決議對主管機關提出○○。」", "o": ["糾舉", "糾正", "彈劾", "審計"], "a": 1, "e": "對機關提出的是糾正。", "rep": false, "img": "c4-q178", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-179", "no": 179, "c": "c7", "src": "114上翰林社會2上C卷 第5卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "為了實現監督制衡的理想，我國《憲法》規定總統、副總統彈劾案的提案與決議方式，分別為何？", "o": ["司法院提案、憲法法庭審理", "立法院提案、憲法法庭審理", "司法院提案、選舉人投票複決", "立法院提案、選舉人投票複決"], "a": 1, "e": "總統、副總統彈劾案由立法院提出，交憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-180", "no": 180, "c": "c6", "src": "114上翰林社會2上C卷 第5卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據圖(四)內容判斷，監察院開會審查委員會，認定該政府官員違法或失職，因而通過此案，此時監察院行使的是下列哪一項職權？\n圖(四)內容：監察院公文「某處長利用職務涉及關說及收受回扣情事，經監察委員調查確認後，向懲戒法院提出……」", "o": ["糾正權", "審計權", "同意權", "彈劾權"], "a": 3, "e": "認定官員違法失職而通過的是彈劾案。", "rep": false, "img": "c4-q180", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-181", "no": 181, "c": "c7", "src": "114上翰林社會2上C卷 第5卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "為落實居住正義的實現，「甲」三讀通過《住宅法》、《不動產經紀業管理條例》和《平均地權條例》等修正案，將交由「乙」制定相關政策，送通過後正式實施。上述「甲」、「乙」應分別是指我國的哪些機關？", "o": ["立法院、總統", "行政院、立法院", "立法院、行政院", "行政院、監察院"], "a": 2, "e": "甲＝立法院三讀通過法律，乙＝行政院制定執行政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-182", "no": 182, "c": "c5", "src": "114上翰林社會2上C卷 第5卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "蘭嶼護理師蔡邑敏在短暫協助患者後送任務，搭乘黑鷹直升機墜海身亡，政府機關官員解釋本案符合「冒險犯難」因公撫卹認定。文中政府機關，其職權還包括下列哪一項？", "o": ["依法公布法律、發布命令", "審核各項營業規則的提案權", "舉辦技術人員的國家考試", "審理政黨違憲的解散案件"], "a": 2, "e": "撫卹由考試院銓敘部主管；考試院也舉辦專門職業及技術人員考試。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-183", "no": 183, "c": "c3", "src": "114上翰林社會2上C卷 第5卷 第 1 題", "st": "考卷", "ctx": "2024 年 12 月 3 日南韓總統尹錫悅以「防止北韓勢力進入，維護自由憲政」的理由宣布戒嚴，此舉引發各界譁然，南韓國會隨即於隔日凌晨召開臨時會議，會議通過要求解除戒嚴令，尹錫悅也在同日再召開內閣會議，表示尊重國會，結束史上最短的戒嚴，其後國會以「戒嚴恐有違憲之虞」理由，對總統提出彈劾案，目前移交憲法法庭審理中。", "fig": "", "q": "依據上文內容判斷，南韓國會的功能與我國中央政府哪一單位相似？", "o": ["行政院", "立法院", "考試院", "司法院"], "a": 1, "e": "南韓國會要求解除戒嚴、提出彈劾，功能相當於我國立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-184", "no": 184, "c": "c7", "src": "114上翰林社會2上C卷 第5卷 第 2 題", "st": "考卷", "ctx": "2024 年 12 月 3 日南韓總統尹錫悅以「防止北韓勢力進入，維護自由憲政」的理由宣布戒嚴，此舉引發各界譁然，南韓國會隨即於隔日凌晨召開臨時會議，會議通過要求解除戒嚴令，尹錫悅也在同日再召開內閣會議，表示尊重國會，結束史上最短的戒嚴，其後國會以「戒嚴恐有違憲之虞」理由，對總統提出彈劾案，目前移交憲法法庭審理中。", "fig": "", "q": "南韓總統因北事件遭國會提出彈劾，案件移交憲法法庭審理。若我國發生類似的情形，處理的機制為何？", "o": ["沒有針對元首彈劾的相關制度", "元首由立法院彈劾並審理違憲事宜", "由監察院提出對於總統、副總統的違法彈劾案", "元首彈劾需經立法院提出後，移交司法院審理"], "a": 3, "e": "我國總統彈劾案由立法院提出，交司法院憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-185", "no": 185, "c": "c3", "src": "金安版公民(三) 第5次練習 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國「立法權」的行使，其中不包括針對法律施行使下列哪一種權力？", "o": ["制定", "公布", "廢止", "修改"], "a": 1, "e": "法律由總統公布，不是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-186", "no": 186, "c": "c2", "src": "金安版公民(三) 第5次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "表：甲 法院；乙 立法院；丙 審計部；丁 交通部；戊 總統府", "q": "我國中央政府組織中，行使行政權的是指右表中哪些組織？", "o": ["甲丙丁", "乙丁戊", "丙丁", "丁戊"], "a": 3, "e": "交通部屬行政院，總統府屬總統（行政權的一部分）；依原卷答案為丁戊。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-187", "no": 187, "c": "c3", "src": "金安版公民(三) 第5次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "表（提案機關皆為立法院）：甲 正副總統罷免案—交由公民投票複決；乙 正副總統彈劾案—大法官召開憲法法庭審理；丙 憲法修正案—交由行政院覆議；丁 領土變更案—交由行政院覆議", "q": "下表為大志報告「立法院的各項提案權與決議方式」時所編製。根據內容判斷，其中何者正確？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "依表判斷只有乙正確。總統副總統彈劾案交憲法法庭；罷免案、修憲案、領土變更案依各自程序。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto", "c4-map-impeach"], "chk": ""}, {"id": "c4-188", "no": 188, "c": "c6", "src": "金安版公民(三) 第5次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "建國的父親在某中央政府機關工作，必須到立法院報告中央政府總決算審核結果。上述建國的父親最可能擔任下列哪一個職位？", "o": ["審計長", "考選部長", "銓敘部長", "行政院長"], "a": 0, "e": "向立法院報告總決算審核結果的是審計長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-189", "no": 189, "c": "c3", "src": "金安版公民(三) 第5次練習 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "立法院長韓國瑜召集朝野黨團協商，討論中央政府總預算案，由國民黨、民眾黨與民進黨的黨團代表出席，韓國瑜能成為立法院長，與下列何者有關？", "o": ["行政院院長任命", "立法委員互選", "人民直選", "總統任命"], "a": 1, "e": "立法院院長由立法委員互選產生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-190", "no": 190, "c": "c7", "src": "金安版公民(三) 第5次練習 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國中央政府的公務人員遭到彈劾後，再交由下列哪一機關審理？", "o": ["憲法法庭", "各級法院", "懲戒法院", "審計部"], "a": 2, "e": "公務人員被彈劾後，交懲戒法院審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-191", "no": 191, "c": "c2", "src": "金安版公民(三) 第5次練習 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為公民李老師說明我國中央政府機關時，所引用的資料，李老師最主要是說明下列哪一個機關？\n資料內容：＊職權：內政、教育、經濟等事務。＊下轄組織：15 部、9 會、3 獨立機關、1 行、1 院、2 總處。", "o": ["行政院", "監察院", "立法院", "司法院"], "a": 0, "e": "內政、教育、經濟等事務及下轄部會，是行政院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-192", "no": 192, "c": "c3", "src": "金安版公民(三) 第5次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列何者須經立法院提案，交由選舉人投票複決才能通過？", "o": ["總統、副總統彈劾案", "總統、副總統選舉", "《憲法》修正案", "緊急命令"], "a": 2, "e": "憲法修正案由立法院提出，交選舉人投票複決。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-193", "no": 193, "c": "c7", "src": "金安版公民(三) 第5次練習 第 9 題", "st": "考卷", "ctx": "", "fig": "圖：總統—(甲)提名→司法院長；(乙)提名→考試院長；(丁)直接任命→行政院長；(丙)直接任命→監察院長", "q": "右圖為我國總統與四院院長的關係。根據內容判斷，何者錯誤？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "監察院院長須經立法院同意才由總統任命，圖中「直接任命」錯誤；依原卷答案為丙。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-194", "no": 194, "c": "c3", "src": "金安版公民(三) 第5次練習 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國行政院將欲執行的環保法規草案，送交下列哪一政府機關審查，經審查通過後，才可以由行政院的環境部執行法規，進行環保工作？", "o": ["司法院", "立法院", "考試院", "監察院"], "a": 1, "e": "法規草案須經立法院審查通過。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-195", "no": 195, "c": "c7", "src": "金安版公民(三) 第5次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "右表為我國中央政府的公職人員，依資料內容判斷，哪些是由總統提名，經立法院同意後由總統任命？\n表格：甲「考試院院長」、乙「考試院副院長」、丙「考試委員」、丁「行政院院長」、戊「國防部長」", "o": ["甲乙丙", "丙丁戊", "甲乙戊", "甲乙丙丁戊"], "a": 0, "e": "考試院院長、副院長、考試委員都由總統提名、立法院同意。行政院長由總統直接任命，國防部長由行政院長提請任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-196", "no": 196, "c": "c2", "src": "金安版公民(三) 第5次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為我國《憲法》及增修條文所規定中央政府的職權。根據內容判斷，是指下列哪一項權力？\n職權內容：執行法律，管理公共事務的權力。", "o": ["立法權", "考試權", "監察權", "行政權"], "a": 3, "e": "執行法律、管理公共事務是行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-197", "no": 197, "c": "c6", "src": "金安版公民(三) 第5次練習 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列是某中央政府機關在網上公告的內容——「彈劾案文 109 年劾字第 41 號 內容：臺灣港務公司方姓督導，多次收受廠商交付之金融禮券，未依法令規定辦理核銷，違反《採購人員倫理準則》第 7 條，爰依法提案彈劾。」上述提案是下列哪一機關提出？", "o": ["監察院", "司法院", "立法院", "行政院"], "a": 0, "e": "彈劾案由監察院提出。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-198", "no": 198, "c": "c7", "src": "金安版公民(三) 第5次練習 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國行政院編列的總預算必須送到立法院審查，若立法院所通過的法律或預算案，行政院認為窒礙難行，可以提出覆議。上述最能說明何種概念？", "o": ["分權制衡制衡", "分工合作提升效率", "中央與地方的均權", "依事務性質劃分權限"], "a": 0, "e": "覆議是行政與立法間的分權制衡。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-199", "no": 199, "c": "c5", "src": "金安版公民(三) 第5次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "怡潔夢想成為公務員，一日她在某中央政府機關的全球資訊網搜尋到：「本年度地方特考需用名額 560 名，請欲報考者在規定期限內報名，逾期不予受理。」依內容判斷，上述資訊應該是在下列哪一機關的網站讀到此訊息？", "o": ["監察院", "考試院", "行政院", "司法院"], "a": 1, "e": "地方特考由考試院（考選部）辦理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-200", "no": 200, "c": "c4", "src": "金安版公民(三) 第5次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "圖：司法院—審判權：甲 ＿＿ 審理政黨違憲的解散事項；解釋權：乙 ＿＿ 審理法律是否違反憲法", "q": "右圖為張老師介紹經有關司法院職權所編製。依內容判斷，甲、乙二空格依序應填入下列何者？", "o": ["各級法院法官、憲法法庭的大法官", "憲法法庭的大法官、各級法院的法官", "各級法院法官、大法官會議的大法官", "憲法法庭的大法官、憲法法庭的大法官"], "a": 3, "e": "審理政黨違憲解散、法律是否違憲，都由憲法法庭的大法官負責。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-201", "no": 201, "c": "c6", "src": "金安版公民(三) 第5次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察委員有提出彈劾、糾舉、糾正的職權，但對於下列何者不得提出彈劾案？", "o": ["彰化縣民政局局長", "臺中市市議員", "新竹縣縣長", "內政部長"], "a": 1, "e": "市議員是民意代表，不在彈劾範圍。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-202", "no": 202, "c": "c7", "src": "金安版公民(三) 第6次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為公民老師介紹我國中央政府的互動關係時所引用的資料。根據內容判斷，是指下列哪些權力間的制衡關係？\n資料內容：總統、副總統的彈劾程序。", "o": ["立法權、行政權", "立法權、監察權", "行政權、司法權", "立法權、司法權"], "a": 3, "e": "總統副總統彈劾：立法院提出（立法權）、憲法法庭審理（司法權）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-203", "no": 203, "c": "c7", "src": "金安版公民(三) 第6次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "流程圖：(甲)立法院決議的條約案→(乙)行政院認為窒礙難行→(丙)經司法院核可→(丁)立法院覆議→維持原決議案／否決原決議案", "q": "右圖為大同報告我國「覆議制度」繪製的流程圖，圖中何處說明錯誤？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "覆議須經「總統」核可，不是司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-204", "no": 204, "c": "c7", "src": "金安版公民(三) 第6次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "表：(甲)行政院、(乙)司法院、(丙)考試院、(丁)監察院——院長、副院長皆「由總統提名，經立法院同意任命」", "q": "下表為宇晨所編製我國重要官員的產生程序——行政院長、司法院長、考試院長、監察院長皆由總統提名，經立法院同意任命。根據內容判斷，何者不正確？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "行政院院長由總統直接任命，不須立法院同意。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-205", "no": 205, "c": "c3", "src": "金安版公民(三) 第6次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "右表為我國《憲法》及增修條文規定有關立法院的提案權，根據內容判斷，甲、乙二案應該是下列何者？\n表格：正副總統罷免案——提案「甲」、決議「乙」", "o": ["司法院、大法官審理", "司法院、立委投票罷免", "立法院、選舉人投票複決", "立法院、選舉人投票罷免"], "a": 3, "e": "正副總統罷免案由立法院提出，交選舉人投票罷免。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-206", "no": 206, "c": "c6", "src": "金安版公民(三) 第6次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為文良整理我國監察院職權所引用的資料，由於他疏忽，造成其中哪一項出現錯誤？\n資料內容：監察院 甲、糾舉公務人員；乙、糾正行政機關；丙、彈劾總統、副總統；丁、審計機關審核決算。", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "監察院不能彈劾總統、副總統。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget", "c4-map-impeach"], "chk": ""}, {"id": "c4-207", "no": 207, "c": "c1", "src": "金安版公民(三) 第6次練習 第 25 題", "st": "考卷", "ctx": "", "fig": "", "q": "先前面對新冠疫情防護，政府制定了《嚴重特殊傳染性肺炎防治及紓困振興特別條例》，若該法無法有效維護人民健康，因應國內經濟、社會之衝擊，下一步將會發布緊急命令來穩定國內運作。關於上文的說明，下列敘述何者正確？", "o": ["該條例需由立法院三讀通過並公布", "緊急命令將由行政院召開會議後發布", "緊急命令發布後十日內需送交立法院追認", "緊急命令發布後若立法院不同意，移請立法院覆議"], "a": 2, "e": "緊急命令發布後十日內需送交立法院追認。(A)由總統公布(B)由總統發布(D)不同意即失效。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-208", "no": 208, "c": "c3", "src": "金安版公民(三) 第6次練習 第 26 題", "st": "考卷", "ctx": "2025 年 1 月 7 日，某院會三讀通過增設運動部的《運動部組織法》等相關法案，明定行政院增設運動部，負責全國運動事務及政策法規的研擬，並下設全民運動署以推廣全民運動，提升國民健康，該部會於 2025 年 8 月正式掛牌運作。", "fig": "", "q": "《運動部組織法》於下列哪一個院會三讀通過？", "o": ["司法院", "立法院", "考試院", "監察院"], "a": 1, "e": "組織法須經立法院院會三讀通過。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-209", "no": 209, "c": "c2", "src": "金安版公民(三) 第6次練習 第 27 題", "st": "考卷", "ctx": "2025 年 1 月 7 日，某院會三讀通過增設運動部的《運動部組織法》等相關法案，明定行政院增設運動部，負責全國運動事務及政策法規的研擬，並下設全民運動署以推廣全民運動，提升國民健康，該部會於 2025 年 8 月正式掛牌運作。", "fig": "", "q": "新設立的「運動部部長」，是經由下列哪一個程序產生？", "o": ["總統直接任命", "總統提名經立法院同意任命", "行政院院長提請總統任命", "行政院院長提名經立法院同意任命"], "a": 2, "e": "部長由行政院院長提請總統任命。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-210", "no": 210, "c": "c2", "src": "金安版公民(三) 第6次練習 第 28 題", "st": "考卷", "ctx": "2025 年 1 月 7 日，某院會三讀通過增設運動部的《運動部組織法》等相關法案，明定行政院增設運動部，負責全國運動事務及政策法規的研擬，並下設全民運動署以推廣全民運動，提升國民健康，該部會於 2025 年 8 月正式掛牌運作。", "fig": "", "q": "下列何者的上級機關與運動部相同？", "o": ["數位發展部", "懲戒法院", "審計部", "考選部"], "a": 0, "e": "運動部、數位發展部都隸屬行政院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-211", "no": 211, "c": "c2", "src": "金安版公民(三) 第6次練習 第 29 題", "st": "考卷", "ctx": "2025 年 1 月 7 日，某院會三讀通過增設運動部的《運動部組織法》等相關法案，明定行政院增設運動部，負責全國運動事務及政策法規的研擬，並下設全民運動署以推廣全民運動，提升國民健康，該部會於 2025 年 8 月正式掛牌運作。", "fig": "", "q": "關於「行政院」的職權敘述，下列何者正確？", "o": ["對考試院考試委員提出彈劾案", "三讀通過《民法》成年下修 18 歲", "辦理警察、國安、公職人員等國家考試", "下轄的數位發展部推動「新世代打擊詐欺策略行動綱領 2.0」"], "a": 3, "e": "數位發展部隸屬行政院。(A)監察院(B)立法院(C)考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-212", "no": 212, "c": "c1", "src": "金安版公民(三) 第6次練習 第 30 題", "st": "考卷", "ctx": "政府放寬含萊劑豬肉進口，行政院指地方政府的萊劑零檢出自治條例無效。對此，嘉義市議會及北市議會國民黨團先後提起釋憲案，以政院違反《憲法》對地方自治的制度性保障、中央與地方分權之權力分立原則提出聲請，《憲法訴訟法》有關「釋憲」新制已於 2019 年 1 月 4 日公布，至 2022 年正式施行。", "fig": "", "q": "上文提及「釋憲」新制已於 2019 年 1 月 4 日公布，下列何者有權公布《憲法訴訟法》有關「釋憲」的新制？", "o": ["行政院長", "總統", "立法院長", "司法院長"], "a": 1, "e": "法律由總統公布。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-300", "no": 300, "c": "c7", "src": "教學式講義第 47 頁 會考學力診斷 第 24 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(十)為一則新聞標題，若圖中提及的情形發生在我國，後續的發展最可能為下列何者？", "o": ["總統宣布解散立法院", "全體立法委員提出辭職", "行政院向立法委員提出彈劾", "行政院向立法院提出覆議"], "a": 0, "e": "不信任案通過，行政院院長應辭職，並得同時呈請總統解散立法院。", "rep": false, "img": "c4-x24", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-301", "no": 301, "c": "c4", "src": "教學式講義第 47 頁 會考學力診斷 第 25 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(十一)是小希去參觀憲法法庭所拍攝的照片，參觀過程中，小希不可能聽到下列哪一項介紹內容？", "o": ["由大法官所組成", "審理政黨違憲的解散案件", "負責審理正、副總統彈劾案", "依法審判違法失職的公務人員"], "a": 3, "e": "審判違法失職的公務人員是懲戒法院的職權，不是憲法法庭。", "rep": false, "img": "c4-x25", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-302", "no": 302, "c": "c7", "src": "試題寶典評量第 33 頁 基礎實力題 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "阿信在報導上看到臺灣中央政府權力分權制衡關係介紹，如圖(一)。圖中應為哪一種制度的示意圖？", "o": ["釋憲案", "不信任案", "覆議制度", "彈劾案"], "a": 1, "e": "立法院提出不信任案→行政院院長辭職並得呈請總統解散立法院，這是不信任案與解散制度。", "rep": false, "img": "c4-b10", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-303", "no": 303, "c": "c7", "src": "試題寶典評量第 33 頁 基礎實力題 第 11 題", "st": "講義", "ctx": "阿信在報導上看到臺灣中央政府權力分權制衡關係介紹，如圖(一)：①立法院提出→②院長辭職，並得呈請甲解散立法院→③被動解散。", "fig": "", "q": "承上題，圖(一)「甲」所指應為何人？", "o": ["總統", "行政院院長", "立法院院長", "司法院院長"], "a": 0, "e": "行政院院長辭職時，得呈請「總統」解散立法院。", "rep": false, "img": "c4-b10", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-304", "no": 304, "c": "c7", "src": "試題寶典評量第 33 頁 基礎實力題 第 12 題", "st": "講義", "ctx": "阿信在報導上看到臺灣中央政府權力分權制衡關係介紹，如圖(一)：①立法院提出→②院長辭職，並得呈請甲解散立法院→③被動解散。", "fig": "", "q": "承上題，當立法院提出此案通過後，提出辭職的「乙」應為何人？", "o": ["總統", "行政院院長", "立法院院長", "監察院院長"], "a": 1, "e": "不信任案通過，行政院院長應辭職。", "rep": false, "img": "c4-b10", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-305", "no": 305, "c": "c6", "src": "試題寶典評量第 33 頁 基礎實力題 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "我國公務員若違法或失職，會經由哪一機關彈劾後送交懲戒法院審理？", "o": ["監察院", "行政院", "司法院", "立法院"], "a": 0, "e": "一般公務員由監察院彈劾，移送司法院懲戒法院審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-306", "no": 306, "c": "c1", "src": "試題寶典評量第 33 頁 基礎實力題 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "民國 88 年我國發生 921 大地震，在 9 月 25 日晚間，政府隨即發布緊急命令，展開災害救助、災民安置以及災後重建工作。上述的「緊急命令」是由下列何人所發布？", "o": ["行政院院長", "立法院院長", "內政部部長", "總統"], "a": 3, "e": "緊急命令由總統經行政院會議決議後發布。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-307", "no": 307, "c": "c7", "src": "試題寶典評量第 33 頁 基礎實力題 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "依據五權憲法的架構，下列何者是我國行政權與立法權間的互動關係？", "o": ["憲法法庭審理總統、副總統彈劾案", "銓敘部考核公務員的任用資格", "立法委員質詢行政官員", "懲戒法院審理被彈劾的公務員"], "a": 2, "e": "立法委員質詢行政官員是立法權監督行政權。(A)立法與司法、(B)考試權、(D)監察與司法。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-308", "no": 308, "c": "c7", "src": "試題寶典評量第 33 頁 精熟思考題 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "據英國《經濟學人》雜誌統計，1990 年迄今至少 63 個國家曾經啟動彈劾程序，132 位國家領導人遭到彈劾，近 10 年來更有 5 位總統因而被罷免下臺。有關我國總統、副總統彈劾案與罷免案的敘述，下列何項正確？", "o": ["提案權都屬於立法院", "都以選舉人投票的方式決議", "均由司法院大法官提案", "都須交由大法官召開憲法法庭決議"], "a": 0, "e": "彈劾案、罷免案都由立法院提出；彈劾案交憲法法庭審理，罷免案交選舉人投票。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-309", "no": 309, "c": "c7", "src": "試題寶典評量第 33 頁 精熟思考題 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "為了使國家財源有效率的運用，我國中央政府總預算的「提出、審查、決算」分別隸屬於哪些機關負責？", "o": ["行政院、立法院、監察院", "行政院、司法院、立法院", "立法院、行政院、監察院", "監察院、立法院、行政院"], "a": 0, "e": "行政院提出預算、立法院審查預算、監察院審計部審核決算。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-310", "no": 310, "c": "c3", "src": "試題寶典評量第 33 頁 精熟思考題 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(二)為阿尼的公民課筆記，其中「甲」應該是中央政府的哪一機關？", "o": ["司法院", "行政院", "立法院", "監察院"], "a": 2, "e": "提憲法修正案、領土變更案、總統副總統彈劾案與罷免案，都是立法院的提案權。", "rep": false, "img": "c4-b3", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-311", "no": 311, "c": "c6", "src": "試題寶典評量第 37 頁 素養UP題組 第 3 題", "st": "講義", "ctx": "某知名食品公司爆發嚴重食安問題，導致大量消費者食物中毒，社會輿論譁然。許多民眾紛紛要求政府加強監管，並對相關企業究責，若觸犯了罪行，應由「甲機關」下設的各級法院依法審理，確保食品安全。為了防止類似的食安事件再次發生，政府應檢討現行食品安全法規，修訂食品安全相關法律，提高違規罰則，並要求加強檢驗機制。如果有公務人員失職違法的情況，再由「乙機關」調查後提出彈劾。", "fig": "", "q": "上文中提到的「乙機關」，其職權還包括以下哪一項？", "o": ["對總統提名官員行使人事同意權", "負責國家政策的規畫與法案執行", "對政府機關年度決算行使審計權", "憲法法庭審理政黨違憲的解散案"], "a": 2, "e": "提出彈劾的乙機關是監察院，監察院設審計部，對各機關年度決算行使審計權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-312", "no": 312, "c": "c2", "src": "試題寶典評量第 37 頁 素養UP題組 第 4 題", "st": "講義", "ctx": "近年來，房價持續上漲，讓許多年輕人難以負擔購屋成本，租屋市場也缺乏保障，引發社會對「居住正義」的討論。為了改善這個問題，政府推動社會住宅政策，並透過不同機關分工合作，解決民眾的住房需求。政府在推動居住正義的過程中，也遭遇一些爭議，例如有民間團體認為目前的社宅政策無法有效解決問題，因此希望透過修法來強化租屋市場的保障機制。", "fig": "", "q": "有關文中社會住宅的規畫，應由下列哪個機關負責執行這項政策？", "o": ["行政院", "立法院", "司法院", "監察院"], "a": 0, "e": "規畫與執行政策是行政院的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-313", "no": 313, "c": "c3", "src": "試題寶典評量第 37 頁 素養UP題組 第 5 題", "st": "講義", "ctx": "近年來，房價持續上漲，讓許多年輕人難以負擔購屋成本，租屋市場也缺乏保障，引發社會對「居住正義」的討論。為了改善這個問題，政府推動社會住宅政策，並透過不同機關分工合作，解決民眾的住房需求。政府在推動居住正義的過程中，也遭遇一些爭議，例如有民間團體認為目前的社宅政策無法有效解決問題，因此希望透過修法來強化租屋市場的保障機制。", "fig": "", "q": "若要修改文中法規，應由下列哪個機關負責？", "o": ["行政院", "立法院", "監察院", "司法院"], "a": 1, "e": "制定、修改法律是立法院的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-314", "no": 314, "c": "c6", "src": "試題寶典第 40 頁 第二次段考模擬試題 第 16 題", "st": "講義", "ctx": "", "fig": "表(二)：行使原因——彈劾、糾舉：公務人員有違法或失職行為；糾正：行政院及其所屬各機關有不當施政。行使對象——彈劾、糾舉：中央及地方公務人員；糾正：行政院及行政院所屬各機關。提出方式——彈劾：向公務人員的主管或上級長官提出；糾舉：提出後移送司法院；糾正：向行政院或相關部會提出。行使機關——三者皆為監察院。", "q": "表(二)是關於彈劾、糾舉及糾正權的比較，表中哪一項目敘述有誤？", "o": ["行使原因", "行使對象", "提出方式", "行使機關"], "a": 2, "e": "提出方式寫反了：彈劾是提出後移送司法院懲戒法院；糾舉才是向公務人員的主管或上級長官提出。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-315", "no": 315, "c": "c7", "src": "試題寶典第 40 頁 第二次段考模擬試題 第 17 題", "st": "講義", "ctx": "", "fig": "表(三)：甲 內政部部長—總統直接任命；乙 考試委員—考試院院長提請總統任命；丙 審計長—通過國家考試後任職；丁 立法院院長—立法委員互選", "q": "表(三)是我國各公職人員的產生方式整理，其中何者正確？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "立法院院長由立法委員互選。內政部部長由行政院院長提請總統任命；考試委員、審計長都是總統提名、立法院同意後任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-316", "no": 316, "c": "c7", "src": "試題寶典第 40 頁 第二次段考模擬試題 第 19 題", "st": "講義", "ctx": "", "fig": "圖(二)：編列預算（行政院彙編各院預算）→審查預算（立法院）→執行預算、做成決算（行政院）→審核決算（？）→審議審核報告（立法院）", "q": "圖(二)是我國政府預算、決算流程圖，圖中「？」處的機關隸屬於我國中央哪一院？", "o": ["司法院", "監察院", "考試院", "立法院"], "a": 1, "e": "審核決算的是審計部，審計部隸屬監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-317", "no": 317, "c": "c3", "src": "試題寶典第 40 頁 第二次段考模擬試題 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "新冠肺炎疫情期間，國內學者建議「相關單位」加強監督防疫期間特別預算的審查，用於勞工紓困及弱勢就業者預算分配，或運用就業安定基金辦理的薪資補貼，必須同時顧及性別、年齡、收入、家庭受扶養人口數，且要嚴加注意補助不重複原則，避免排擠或重疊既有業務與預算。根據上文，下列何項敘述正確？", "o": ["新冠肺炎特別預算由總統提出", "文中所提的「相關單位」是為立法院", "文中所提「相關單位」負責執行政策", "該「相關單位」藉審查以監督司法院"], "a": 1, "e": "審查預算的是立法院，立法院藉預算審查監督行政院。預算由行政院提出、執行。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-318", "no": 318, "c": "c3", "src": "試題寶典第 38 頁 第二次段考模擬試題 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "立法院為中央的民意機關，其任務重大，需代替人民來監督政府施政。下列有關立法院的敘述，何者有誤？", "o": ["立法委員只能連選得連任一次", "可審查中央政府提出的總預算", "立法院院長由立法委員互選產生", "對總統提名任命的官員行使同意權"], "a": 0, "e": "立法委員連選得連任，沒有次數限制；只能連任一次的是總統。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-319", "no": 319, "c": "c7", "src": "試題寶典第 38 頁 第二次段考模擬試題 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "有關我國「行政院和立法院的關係」，下列哪一位同學的說法有誤？", "o": ["大雄：立法院可對行政院院長提出不信任案", "胖虎：行政院認為法律案窒礙難行時，可提出緊急命令", "靜香：不信任案通過後，行政院院長應提出辭職，並得呈請總統解散立法院", "小夫：不信任案如未獲通過，則一年內不得對同一行政院院長再提不信任案"], "a": 1, "e": "法律案窒礙難行時，行政院應經總統核可，移請立法院「覆議」，不是緊急命令。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-320", "no": 320, "c": "c7", "src": "試題寶典第 38 頁 第二次段考模擬試題 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "行政院為我國最高行政機關，立法院則為最高立法機關，這兩者之間的互動關係不包括下列何項？", "o": ["不信任案", "正副總統彈劾案", "解散國會", "覆議制度"], "a": 1, "e": "正副總統彈劾案是立法院提出、司法院憲法法庭審理，屬於立法權與司法權的互動。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-321", "no": 321, "c": "c3", "src": "試題寶典第 38 頁 第二次段考模擬試題 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "我國立法院可對總統提名之官員行使人事同意權，下列何者是其行使同意權的對象？", "o": ["地方法院法官", "行政院院長", "大法官", "立法委員"], "a": 2, "e": "大法官由總統提名、立法院同意後任命。法官經國家考試、行政院院長由總統直接任命、立法委員由人民選舉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-322", "no": 322, "c": "c4", "src": "試題寶典第 38 頁 第二次段考模擬試題 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "之前引發動物保育和原住民狩獵文化衝突的布農族獵人案件，當時最高法院認為現行法律規定已違反《憲法》保障多元文化和原住民傳統的意旨，而決議裁定停止審判，因而向中央哪一單位聲請違憲審查？", "o": ["考試院", "司法院", "立法院", "監察院"], "a": 1, "e": "審理法律是否違憲，由司法院大法官組成憲法法庭負責。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-323", "no": 323, "c": "c3", "src": "114上翰林社會2上A卷 卷5 題組 (一) 2", "st": "考卷", "ctx": "", "fig": "", "q": "格陵蘭位於北極圈，是北美與歐洲之間的戰略要道，擁有豐富的自然資源，並具有商業航運的潛力。格陵蘭的元首是丹麥君主，2008 年格陵蘭舉行自治公投通過，可以自行管理內政及司法，但其國防、外交等相關事務仍由丹麥管轄。2025 年美國總統川普當選後接受專訪，表示有意將格陵蘭納入美國領土。上文中畫線處這種變動，若發生在我國，則須經由下列哪一程序？", "o": ["立法院召開院會三讀通過", "總統提議經行政院會同意", "立法院提案由選舉人複決", "由公民連署超過 3/4 同意"], "a": 2, "e": "領土變更案由立法院提出，公告半年後交由選舉人投票複決。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-324", "no": 324, "c": "c6", "src": "114上翰林社會2上A卷 卷5 題組 (二) 3", "st": "考卷", "ctx": "身為候選人的張偉希望建立一個「廉能政府」，下列是他所想出的競選口號：一、設廉政委員會，推動乾淨政府，揪出貪瀆、失職的公務人員，以提升政府的清廉形象。二、嚴禁政治勢力干預獨立機構。三、財產誠實陽光，不實申報課刑。", "fig": "", "q": "第一點設廉政委員會與我國哪一機關的職權重疊？", "o": ["行政院", "監察院", "考試院", "立法院"], "a": 1, "e": "揪出貪瀆、失職的公務人員，是監察院彈劾、糾舉的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-325", "no": 325, "c": "c4", "src": "114上翰林社會2上A卷 卷5 題組 (二) 4", "st": "考卷", "ctx": "身為候選人的張偉希望建立一個「廉能政府」，下列是他所想出的競選口號：一、設廉政委員會，推動乾淨政府，揪出貪瀆、失職的公務人員，以提升政府的清廉形象。二、嚴禁政治勢力干預獨立機構。三、財產誠實陽光，不實申報課刑。", "fig": "", "q": "第三點中貪瀆失職的公務人員，在我國應由下列哪一個機關審查其懲戒事項？", "o": ["考選部", "憲法法庭", "銓敘部", "懲戒法院"], "a": 3, "e": "公務人員違法失職的懲戒，由司法院懲戒法院審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-326", "no": 326, "c": "c4", "src": "114上翰林社會2上A卷 卷6 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "當政府的作為有違反《憲法》規範的疑慮時，必須透過司法機關審理法律是否違憲，以確保政府權力運作符合《憲法》要求，上述審理法律的單位為何？", "o": ["行政院", "憲法法庭", "立法院", "審計長"], "a": 1, "e": "審理法律是否違憲，由大法官組成的憲法法庭負責。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-327", "no": 327, "c": "c4", "src": "114上翰林社會2上A卷 卷6 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國中央政府設有懲戒法院，專門處理公務人員違法失職的懲戒事項。上述法院隸屬於哪一機關？", "o": ["總統府", "行政院", "考試院", "司法院"], "a": 3, "e": "懲戒法院隸屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-328", "no": 328, "c": "c6", "src": "114上翰林社會2上A卷 卷6 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察院為我國最高監察機關，下列對於它所行使各項職權的敘述，何者正確？", "o": ["任命行政院院長", "審理正副總統彈劾案", "對違法失職的公務人員提出糾正案", "對於各機關的年度決算行使審計權"], "a": 3, "e": "監察院設審計部審核決算。行政院院長由總統任命、彈劾案由憲法法庭審理；對「人」是彈劾或糾舉，糾正是針對「事」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-329", "no": 329, "c": "c3", "src": "114上翰林社會2上A卷 卷6 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列關於我國立法院相關敘述，何者錯誤？", "o": ["立法委員連選得連任", "由民選的立法委員所組成", "院長及副院長由總統指派", "是我國最高立法機關"], "a": 2, "e": "立法院院長、副院長由立法委員互選產生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-330", "no": 330, "c": "c3", "src": "114上翰林社會2上A卷 卷6 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據《憲法》規定，我國立法院擁有各項提案權，下列何者的提案權限不屬於立法院？", "o": ["《憲法》修正案", "領土變更案", "正副總統罷免案", "公務人員懲戒案"], "a": 3, "e": "公務人員由監察院彈劾、懲戒法院懲戒，不是立法院的提案權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-331", "no": 331, "c": "c7", "src": "114上翰林社會2上A卷 卷6 第 12 題", "st": "考卷", "ctx": "", "fig": "圖(二)：「甲」編列預算→「乙」審查預算→「丙」執行預算、做成決算→「丁」審核決算→「戊」審議審核報告", "q": "圖(二)為我國中央政府年度經費運用的流程簡圖，依圖中內容判斷，下列對於各階段職權機關的配對何者正確？", "o": ["甲、乙均屬行政院", "乙、丙均屬司法院", "甲、丙均屬審計部", "乙、戊均屬立法院"], "a": 3, "e": "甲編列預算、丙執行預算是行政院；乙審查預算、戊審議審核報告是立法院；丁審核決算是監察院審計部。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-332", "no": 332, "c": "c7", "src": "114上翰林社會2上A卷 卷6 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "2020 年《反滲透法》三讀通過後，在野黨批評倉促的立法與定義的不清使法案過於粗糙，建議行政院應以「窒礙難行」為由提出覆議。若行政院提出覆議，應先經下列何者的核可？", "o": ["大法官", "立法院", "總統", "監察院"], "a": 2, "e": "覆議須經總統核可，才能移請立法院覆議。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-333", "no": 333, "c": "c1", "src": "114上翰林社會2上A卷 卷6 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國總統為國家元首並具有許多職權，下列為其職權範圍？", "o": ["發布緊急命令", "任命立法院院長", "負責制定法律", "對施政提出糾正"], "a": 0, "e": "發布緊急命令是總統職權。立法院院長由立委互選、立法院制定法律、監察院提出糾正。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-334", "no": 334, "c": "c7", "src": "114上翰林社會2上A卷 卷6 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "立法院對行政院院長提出不信任案通過後，行政院院長得呈請下列何者解散立法院？", "o": ["總統", "司法院院長", "監察院院長", "大法官"], "a": 0, "e": "不信任案通過，行政院院長辭職，並得呈請總統解散立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-335", "no": 335, "c": "c2", "src": "114上翰林社會2上A卷 卷6 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "2020 年我國政府為避免疫情在國內擴大，任命衛生福利部部長擔任中央流行疫情中心指揮官，負責處理防疫事務及相關因應措施。上述政策是屬於哪一政府機關的職權？", "o": ["考試院", "行政院", "司法院", "立法院"], "a": 1, "e": "衛生福利部隸屬行政院，執行防疫政策是行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-336", "no": 336, "c": "c7", "src": "114上翰林社會2上A卷 卷6 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "日前因人為疏失造成全臺數百萬戶大停電，立法院要求行政院院長提出相關專案報告。上述政府機關間的互動呈現出下列何項概念？", "o": ["政黨輪替", "主權在民", "分權制衡", "人治社會"], "a": 2, "e": "立法院監督行政院，是分權制衡的展現。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-337", "no": 337, "c": "c5", "src": "114上翰林社會2上A卷 卷6 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "真知和家人共進晚餐時，於新聞中看到與考試院相關的新聞，家人紛紛提出他們對「考試院」的認識，下列何者正確？", "o": ["爸爸：考試院是我國最高司法機關", "媽媽：考試院設有考選部及審計部", "姐姐：負責公務員違法失職的懲戒", "弟弟：負責辦理技術人員國家考試"], "a": 3, "e": "考選部主管專門職業及技術人員考試。審計部屬監察院、懲戒屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-338", "no": 338, "c": "c7", "src": "114上翰林社會2上A卷 卷6 題組 (一) 2", "st": "考卷", "ctx": "", "fig": "", "q": "2024 年 12 月 3 日晚上，韓國總統尹錫悅發布緊急命令，宣布即刻實施戒嚴，以應對「反國家勢力」及來自北韓的安全威脅。該國國會於凌晨 1 時迅速召開會議，通過解除戒嚴案。在野黨指責尹錫悅的行為構成嚴重內亂，戒嚴令也違憲，於是發動彈劾總統。國會通過總統彈劾案後，尹錫悅的總統職權被暫停，並由南韓憲法法院接手審理總統彈劾案。比較上文事件中韓國與我國政府的相關職權，何者正確？", "o": ["我國可以由行政院取消總統的緊急命令", "我國行政、立法、司法間也有分權制衡", "我國設立監察院對正副總統提出彈劾", "我國大法官在懲戒法院審理總統彈劾案"], "a": 1, "e": "我國五權之間也有分權制衡。緊急命令由立法院追認、總統彈劾由立法院提出、大法官在憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg", "c4-map-impeach"], "chk": ""}, {"id": "c4-339", "no": 339, "c": "c3", "src": "114上翰林社會2上A卷 卷6 進階思考題 1", "st": "考卷", "ctx": "", "fig": "", "q": "在民主國家中，行政權和立法權的互動攸關國家的長遠發展，下列有關兩權的互動，哪一項敘述正確？", "o": ["行政院在總統發布緊急命令的 10 日內進行追認", "立法院院長有向行政院提出施政報告的責任", "立法院有權對總統提名的官員行使人事同意權", "行政院有議決法律案與條約案的權力"], "a": 2, "e": "立法院對總統提名的官員行使人事同意權。緊急命令由立法院追認；行政院向立法院提出施政報告；議決法律案是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-340", "no": 340, "c": "c2", "src": "114上翰林社會2上A卷 卷6 進階思考題 3", "st": "考卷", "ctx": "", "fig": "", "q": "「面臨國際嚴峻疫情，總統表示前一階段是主導防疫國家隊，現在則是要率領防疫國家隊打『國際盃』，與其他國家一同區域聯防抗疫。基於人道考量，臺灣未來將會向國際社會提供口罩、藥物及技術支援。」根據上述新聞內容判斷，主要是行使下列何種權力？", "o": ["行政權", "考試權", "司法權", "立法權"], "a": 0, "e": "提供口罩、藥物等防疫政策的執行，屬於行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-341", "no": 341, "c": "c4", "src": "114上翰林社會2上A卷 卷6 進階思考題 4", "st": "考卷", "ctx": "", "fig": "", "q": "近年來死刑存廢爭議不斷，2024 年 9 月，○○針對 37 位死囚提出死刑違反《憲法》保障的生存權和平等權一案進行審查，宣判死刑本身合憲，但須符合最嚴重的犯罪情節及最嚴密的刑事程序。我國為確保公正性，上述○○的產生方式為何？", "o": ["透過考試院選拔", "由全民直選產生", "由總統提名經立法院同意", "由行政院長提請總統任命"], "a": 2, "e": "審查法律是否違憲的是大法官，由總統提名、經立法院同意後任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-342", "no": 342, "c": "c6", "src": "114上翰林社會2上A卷 卷6 進階思考題 7", "st": "考卷", "ctx": "", "fig": "", "q": "監察委員表示，國際移工職災失能率明顯高於臺籍移工，而勞動部不僅未能掌握職災失能情形，也未提出具體有效的改善措施。監察院在此案可運用下列哪一種職權？", "o": ["發動罷免勞動部長", "直接懲戒勞動部長", "對司法權提出糾舉", "對勞動部提出糾正"], "a": 3, "e": "勞動部施政不當是「事」，監察院可對行政機關提出糾正。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-343", "no": 343, "c": "c6", "src": "114上翰林社會2上B卷 卷6 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "近 3 年來全國各警察機關違規查詢個資案件計 52 件，其中 10 件涉及與不法組織勾結，監察院認定內政部警政署未落實督導、查察，使不肖員警洩漏偵查訊息及出賣民眾個資。在調查報告經審查通過後，可能會對文中內政部警政署進行下列何者？", "o": ["糾舉", "糾正", "彈劾", "懲戒"], "a": 1, "e": "對行政機關（內政部警政署）的不當施政，監察院提出糾正。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-344", "no": 344, "c": "c3", "src": "114上翰林社會2上B卷 卷6 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據我國相關規定，何者主要是由公民直選產生？", "o": ["監察委員", "立法委員", "司法院院長", "行政院院長"], "a": 1, "e": "立法委員由人民選舉產生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-345", "no": 345, "c": "c5", "src": "114上翰林社會2上B卷 卷6 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "為提升專門職業和技術人員考試水準，甲院考選部規畫協調行政院公共工程委員會，將技師才能執行的業務以法律規範，樹立執照權威。上文中的甲院應是下列何者？", "o": ["立法院", "行政院", "司法院", "考試院"], "a": 3, "e": "考選部隸屬考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-346", "no": 346, "c": "c3", "src": "114上翰林社會2上B卷 卷6 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "行政院院長率各部會首長赴「相關機關」進行施政方針及施政報告，但隨著世界性傳染病疫情持續延燒，執政黨建議該機關縮短質詢時間。但在野黨表示，質詢能讓民眾了解防疫狀況、幫助政府防止防疫漏洞，他們不會縮短質詢時間。上文中提到的「相關機關」主要是掌理政府的何種權力？", "o": ["司法權", "監察權", "立法權", "行政權"], "a": 2, "e": "行政院向立法院提出施政報告、接受質詢，立法院掌理立法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-347", "no": 347, "c": "c1", "src": "114上翰林社會2上B卷 卷6 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "總統為國家元首，下列何者屬於我國總統的職權？", "o": ["制定法律", "統率陸海空三軍", "提出領土變更案", "向立法院提出施政報告"], "a": 1, "e": "總統統率全國陸海空三軍。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-348", "no": 348, "c": "c4", "src": "114上翰林社會2上B卷 卷6 第 10 題", "st": "考卷", "ctx": "", "fig": "圖(二)：《憲法法庭審理規則》第 8 條：憲法法庭受理政黨解散案件認有必要時，得指定大法官三人小組為受命大法官行準備程序，並由資淺大法官主持之。", "q": "圖(二)為我國憲法法庭運作法源依據摘要。圖中受理案件的機關隸屬於哪一中央政府機關？", "o": ["立法院", "監察院", "司法院", "考試院"], "a": 2, "e": "憲法法庭由司法院大法官組成。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-349", "no": 349, "c": "c3", "src": "114上翰林社會2上B卷 卷6 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "中央某機關網站上提到：「依據孫中山先生首創的五權憲法，由國民大會代表全體國民行使政權，於中央分設五院，行使治權。而本院就其職權、性質及功能而言，相當於一般民主國家的國會。」關於此機關的說明，何者正確？", "o": ["擁有司法權", "擁有執行公共事務的權力", "擁有總統副總統罷免案提案權", "院長由總統提名立法委員同意"], "a": 2, "e": "相當於國會的是立法院，立法院可提出總統、副總統罷免案。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-350", "no": 350, "c": "c5", "src": "114上翰林社會2上B卷 卷6 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為明清時期為朝廷所設計的科舉制度示意圖（童生→生員→舉人→貢士→進士）。若依我國《憲法》規定，該政府機關應為掌握政府的何種權力？", "o": ["考試權", "監察權", "立法權", "行政權"], "a": 0, "e": "選拔人才相當於我國的考試權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-351", "no": 351, "c": "c6", "src": "114上翰林社會2上B卷 卷6 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "日前某中央權責機關公布中央政府總決算審核報告，對於財政狀況表達擔憂，因為若加計特別預算，除了 107、108 及 111 年度外，其餘年度皆為入不敷出。而 113 年預計將缺少 4,905 億元，建議行政院與財政部等相關單位持續精進財務管理及債務管控。上文中的中央權責機關應是擁有何種政府權力？", "o": ["司法權", "監察權", "行政權", "立法權"], "a": 1, "e": "審核總決算的是審計部，屬監察權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-352", "no": 352, "c": "c4", "src": "114上翰林社會2上B卷 卷6 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(五)為小鳳上網瀏覽中央某政府機關時看到的院徽圖示（天秤）。此中央政府機關所擁有的權力不包含何者？", "o": ["解釋權", "懲戒權", "糾正權", "審判權"], "a": 2, "e": "天秤代表司法院，司法院有解釋、審判、懲戒權；糾正權屬監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-353", "no": 353, "c": "c1", "src": "114上翰林社會2上B卷 卷6 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "新型冠狀病毒疫情蔓延全球，各國政府紛紛發布緊急命令進行封城，關閉營業場所，限制人民的外出活動，以避免疫情擴散，減少傷亡。若依我國法令而言，發布「緊急命令」須經何種程序才有效？", "o": ["行政院會議決議→總統發布→立法院追認", "行政院院長決議→立法院發布→總統追認", "行政院會議決議→總統發布→司法院追認", "立法院決議→總統公告→行政院會議追認"], "a": 0, "e": "緊急命令：行政院會議決議→總統發布→10 日內提交立法院追認。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-354", "no": 354, "c": "c5", "src": "114上翰林社會2上B卷 卷6 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列為中央政府某部會的施政目標：(1)積極推動重大法案，健全人事法制。(2)完備公務員官制官規架構，活化人力。(3)建構公務人員退休安全網絡，兼顧社會正義。(4)整合文官資訊系統，提升決策品質。(5)監理退撫基金運用效益，確保永續經營。由內容可知，該政府機關亦擁有下列何種權力？", "o": ["審判權", "糾舉權", "考試權", "人事同意權"], "a": 2, "e": "負責公務人員人事、退休的是銓敘部，隸屬考試院，擁有考試權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-355", "no": 355, "c": "c6", "src": "114上翰林社會2上B卷 卷6 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "身為監察委員的大佑，在某段期間看到媒體揭露下列四則新聞。根據大佑的職權判斷，哪一則新聞的報導對象，最可能被他提出彈劾？", "o": ["民調顯示，民眾對於內閣官員的滿意度大幅下滑", "警方破獲史上最大幫派分子製毒、販毒集團", "現任總統疑似洩漏國家機密，影響國家安全", "中央政府部會首長涉嫌官商勾結，從中舞弊"], "a": 3, "e": "彈劾的對象是違法失職的公務人員，但不包括總統。部會首長官商勾結可提出彈劾。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-356", "no": 356, "c": "c3", "src": "114上翰林社會2上B卷 卷6 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(六)為我國的中央政府總預算分配圓餅圖，根據圖中內容判斷，這項報告主要是由下列何者負責審查通過？", "o": ["監察院", "立法院", "司法院", "行政院"], "a": 1, "e": "中央政府總預算由立法院審查。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-357", "no": 357, "c": "c7", "src": "114上翰林社會2上B卷 卷6 第 23 題", "st": "考卷", "ctx": "", "fig": "表：甲 監察院—人事任命同意權；乙 司法院—解釋《憲法》、法律權；丙 立法院—調查糾正彈劾權；丁 行政院—行政訴訟審判權", "q": "老師將班上分為四組，分別上臺報告各政府機關及其職權，如下表所示。哪一組報告內容最正確？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "司法院有解釋《憲法》、法律權。人事同意權屬立法院、糾正彈劾屬監察院、行政訴訟審判屬司法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-358", "no": 358, "c": "c3", "src": "114上翰林社會2上B卷 卷6 題組 1", "st": "考卷", "ctx": "(甲)近日再次提名司法院正副院長與大法官人選，共有 7 位被提名人，其身分、背景專長多元。高層期許這些提名人能守護自由、民主憲政制度、提升國安案件專業能量。依規定這批大法官提名人最快 4 月底就能經由(乙)進行同意權表決，以補足大法官缺額，符合最新《憲法訴訟法》修法規定，明定大法官人數不得低於 9 人限制，避免憲法法庭面臨停擺危機。", "fig": "", "q": "上文中提到的《憲法訴訟法》，其修法的政府機關應為下列何者？", "o": ["總統", "行政院", "司法院", "立法院"], "a": 3, "e": "修改法律是立法院的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-359", "no": 359, "c": "c4", "src": "114上翰林社會2上B卷 卷6 題組 2", "st": "考卷", "ctx": "(甲)近日再次提名司法院正副院長與大法官人選，共有 7 位被提名人，其身分、背景專長多元。高層期許這些提名人能守護自由、民主憲政制度、提升國安案件專業能量。依規定這批大法官提名人最快 4 月底就能經由(乙)進行同意權表決，以補足大法官缺額，符合最新《憲法訴訟法》修法規定，明定大法官人數不得低於 9 人限制，避免憲法法庭面臨停擺危機。", "fig": "", "q": "上文中提到的新任大法官，主要是擁有政府的何種權力？", "o": ["立法權", "解釋權", "懲戒權", "糾正權"], "a": 1, "e": "大法官負責解釋《憲法》、審理法律是否違憲。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-360", "no": 360, "c": "c1", "src": "114上翰林社會2上B卷 卷6 題組 3", "st": "考卷", "ctx": "(甲)近日再次提名司法院正副院長與大法官人選，共有 7 位被提名人，其身分、背景專長多元。高層期許這些提名人能守護自由、民主憲政制度、提升國安案件專業能量。依規定這批大法官提名人最快 4 月底就能經由(乙)進行同意權表決，以補足大法官缺額，符合最新《憲法訴訟法》修法規定，明定大法官人數不得低於 9 人限制，避免憲法法庭面臨停擺危機。", "fig": "", "q": "上文中提到的(甲)應是指下列何者？", "o": ["總統", "立法院院長", "行政院院長", "司法院院長"], "a": 0, "e": "大法官由總統提名。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-361", "no": 361, "c": "c3", "src": "114上翰林社會2上B卷 卷6 題組 4", "st": "考卷", "ctx": "(甲)近日再次提名司法院正副院長與大法官人選，共有 7 位被提名人，其身分、背景專長多元。高層期許這些提名人能守護自由、民主憲政制度、提升國安案件專業能量。依規定這批大法官提名人最快 4 月底就能經由(乙)進行同意權表決，以補足大法官缺額，符合最新《憲法訴訟法》修法規定，明定大法官人數不得低於 9 人限制，避免憲法法庭面臨停擺危機。", "fig": "", "q": "下列關於文中所述的說明，何者正確？", "o": ["(甲)依法對立法院負責", "(乙)可提出領土變更案", "司法院副院長擁有懲戒權", "(乙)院長由總統提名，立法院同意產生"], "a": 1, "e": "(乙)是立法院，可提出領土變更案。對立法院負責的是行政院；立法院院長由立委互選。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-362", "no": 362, "c": "c2", "src": "114上翰林社會2上B卷 卷6 題組 5", "st": "考卷", "ctx": "根據法務部調查發現，原本臺電向某民營公司採購數萬具變壓器，藉以改善全臺供電量穩定，造福工商業，但卻發現有 3.4 萬具變壓器遭偷換料，造成多起變壓箱爆炸事件，因此經□□院調查後，認定臺電確有疏失，擬糾正臺電公司。", "fig": "", "q": "上文中所提到的「法務部」隸屬於哪一中央政府組織？", "o": ["行政院", "監察院", "立法院", "司法院"], "a": 0, "e": "法務部是行政院的部會之一。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-363", "no": 363, "c": "c2", "src": "114上翰林社會2上B卷 卷6 題組 6", "st": "考卷", "ctx": "根據法務部調查發現，原本臺電向某民營公司採購數萬具變壓器，藉以改善全臺供電量穩定，造福工商業，但卻發現有 3.4 萬具變壓器遭偷換料，造成多起變壓箱爆炸事件，因此經□□院調查後，認定臺電確有疏失，擬糾正臺電公司。", "fig": "", "q": "承上題，該中央政府組織主要掌理何種權力？", "o": ["司法權", "考試權", "立法權", "行政權"], "a": 3, "e": "行政院掌理行政權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-364", "no": 364, "c": "c6", "src": "114上翰林社會2上B卷 卷6 題組 7", "st": "考卷", "ctx": "根據法務部調查發現，原本臺電向某民營公司採購數萬具變壓器，藉以改善全臺供電量穩定，造福工商業，但卻發現有 3.4 萬具變壓器遭偷換料，造成多起變壓箱爆炸事件，因此經□□院調查後，認定臺電確有疏失，擬糾正臺電公司。", "fig": "", "q": "上文中□□處應該填入下列何者？", "o": ["立法", "行政", "監察", "司法"], "a": 2, "e": "提出糾正案的是監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-365", "no": 365, "c": "c3", "src": "114上翰林社會2上C卷 卷5 題組 (二) 3", "st": "考卷", "ctx": "下列是某三則新聞的重點摘要：(甲)審查《所得稅法》修正草案，降低遺產稅的門檻。(乙)針對中央政府各單位的預算進行審查。(丙)對考試院考試委員的被提名人進行同意權投票。", "fig": "", "q": "依上文中新聞摘要判斷，皆屬於哪一個中央政府機關的職權？", "o": ["行政院", "司法院", "監察院", "立法院"], "a": 3, "e": "修法、審查預算、行使人事同意權，都是立法院的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-366", "no": 366, "c": "c5", "src": "114上翰林社會2上C卷 卷5 題組 (二) 4", "st": "考卷", "ctx": "下列是某三則新聞的重點摘要：(甲)審查《所得稅法》修正草案，降低遺產稅的門檻。(乙)針對中央政府各單位的預算進行審查。(丙)對考試院考試委員的被提名人進行同意權投票。", "fig": "", "q": "上文丙新聞摘要中，考試委員的被提名人是經由下列何種方式所產生？", "o": ["選舉產生", "總統提名", "行政院院長提名", "通過國家考試而來"], "a": 1, "e": "考試委員由總統提名，經立法院同意後任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-367", "no": 367, "c": "c7", "src": "金安版公民(三) 第5次練習 第 18 題", "st": "考卷", "ctx": "", "fig": "表：甲 行政院副院長、立法院副院長；乙 司法院副院長、立法院副院長；丙 考試院副院長、監察院副院長；丁 司法院副院長、行政院副院長", "q": "表中為我國五院副院長的產生程序，哪一組皆屬於總統提名經立法院同意後任命？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "考試院、監察院副院長都由總統提名、立法院同意後任命。行政院副院長由行政院院長提請總統任命；立法院副院長由立委互選。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-368", "no": 368, "c": "c6", "src": "金安版公民(三) 第5次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "表：甲—行使對象：中央及地方公務人員；案件成立後的受理機關：向公務人員之主管長官或上級長官提出。乙—行使對象：行政院及其所屬各機關；受理機關：向行政院或有關部會提出。", "q": "表中為我國監察院的職權比較。甲、乙二者依序為下列何者？", "o": ["彈劾權、糾正權", "糾舉權、彈劾權", "糾舉權、糾正權", "彈劾權、糾舉權"], "a": 2, "e": "甲：對人、向主管或上級長官提出＝糾舉；乙：對事（行政院及所屬機關）、向行政院或部會提出＝糾正。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-369", "no": 369, "c": "c7", "src": "金安版公民(三) 第5次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "針對公務人員調薪，【甲】院編列 114 年度中央政府總預算，函請【乙】院進行審查。若審查通過後，【甲】院將依據通過的預算執行經費，執行後再由【丙】院審核決算。根據我國中央政府的職權判斷，下列敘述何者正確？", "o": ["甲有權辦理公務人員的退休事項", "乙有權提出覆議案", "乙有權提憲法修正案", "丙有權彈劾正副總統"], "a": 2, "e": "甲＝行政院、乙＝立法院、丙＝監察院。(A)退休是考試院；(B)覆議由行政院提出；(D)彈劾正副總統是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-370", "no": 370, "c": "c7", "src": "金安版公民(三) 第5次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "關於我國中央政府制衡關係，下列何者說法正確？", "o": ["振華：當監察院對公務人員依法進行彈劾後，交由司法院各級法院法官審判", "建文：行政院依法對立法院負責，立法委員有接受行政院院長及各部會首長質詢的權力", "紫晴：立法院通過對總統、副總統提出的罷免案時，由司法院大法官組成憲法法庭審理", "秀梅：行政院認為立法院決議的法律案、預算案與條約案窒礙難行時，得經總統核可，移請立法院覆議"], "a": 3, "e": "(A)交懲戒法院審理；(B)是立委有質詢行政院院長及各部會首長的權力；(C)罷免案交選舉人投票，彈劾案才交憲法法庭。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-371", "no": 371, "c": "c7", "src": "金安版公民(三) 第5次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "表：甲 行政權與立法權間的制衡。乙 總統可對立法院院長提出不信任案。丙 行政院院長辭職後，總統可在其呈請下，解散立法院。丁 總統可在行政院院長的核可下對立法院提出覆議。", "q": "表中是怡如整理出有關「總統」與「立法院」之間分權制衡關係的資料，其中哪二者不正確？", "o": ["甲乙", "丙丁", "乙丁", "甲丙"], "a": 2, "e": "乙：立法院可對行政院院長提出不信任案（不是總統對立法院院長）；丁：行政院院長經總統核可，向立法院提出覆議。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf", "c4-map-veto"], "chk": ""}, {"id": "c4-372", "no": 372, "c": "c1", "src": "金安版公民(三) 第5次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "流程圖：(甲)國家遭遇緊急危難或應付財政經濟上重大變故→(乙)行政院會議決議→(丙)行政院長發布緊急命令→(丁)立法院十日內追認→同意：緊急命令有效／不同意：緊急命令立即失效", "q": "下圖是民宗上臺報告「緊急命令」的議題時，編製的流程簡圖。根據圖中內容判斷，其中哪一項出現錯誤？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "緊急命令是由「總統」發布，不是行政院院長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-373", "no": 373, "c": "c7", "src": "金安版公民(三) 第5次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "表：甲 總統；乙 立法院院長；丙 立法委員；丁 監察委員", "q": "表中為我國的中央政府公職人員，哪二者是由人民直接選舉產生？", "o": ["甲乙", "甲丙", "甲丁", "乙丙"], "a": 1, "e": "總統、立法委員由人民直選。立法院院長由立委互選；監察委員由總統提名、立法院同意。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-374", "no": 374, "c": "c6", "src": "金安版公民(三) 第5次練習 第 25 題", "st": "考卷", "ctx": "", "fig": "", "q": "明禮在監察院全球資訊網所搜尋的資料：「類別：？？？文。案由：法務部廉政署廉政研習中心，對於公務人員考試錄取人員參加訓練班第39期專業學習期間遭受性騷擾事件，處置過程違失連連，並威嚇迫使被害人接受道歉，嚴重損及被害人權益，法務部廉政署難辭其咎，均核有違失，爰依法提案。」根據內容判斷，這是屬於監察委員所提出的何種文件？", "o": ["懲戒案", "糾正案", "糾舉案", "彈劾案"], "a": 1, "e": "對象是「法務部廉政署」這個行政機關（對事），所以是糾正案。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-375", "no": 375, "c": "c3", "src": "金安版公民(三) 第5次練習 第 26 題", "st": "考卷", "ctx": "我國中央選舉委員會於 2024 年 1 月 13 日舉行第 11 屆立法委員選舉，共選出 113 位立法委員，包括區域和不分區立法委員。本次選舉結果各政黨的立法委員席次：國民黨 52、民進黨 51、臺灣民眾黨 8、無黨籍 2。", "fig": "", "q": "我國立法委員的任期，依據相關法律規定，應為下列何者？", "o": ["3 年", "4 年", "5 年", "6 年"], "a": 1, "e": "立法委員任期 4 年，連選得連任。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-376", "no": 376, "c": "c3", "src": "金安版公民(三) 第5次練習 第 27 題", "st": "考卷", "ctx": "我國中央選舉委員會於 2024 年 1 月 13 日舉行第 11 屆立法委員選舉，共選出 113 位立法委員，包括區域和不分區立法委員。本次選舉結果各政黨的立法委員席次：國民黨 52、民進黨 51、臺灣民眾黨 8、無黨籍 2。", "fig": "", "q": "第 11 屆當選的立法委員，可以行使下列哪一項的職權？", "o": ["負責處理公務人員違法失職的懲戒事項", "提出公務人員違法的糾舉案", "執行內政、教育等事務", "提出正副總統罷免案"], "a": 3, "e": "(A)懲戒法院；(B)監察委員；(C)行政院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-377", "no": 377, "c": "c7", "src": "金安版公民(三) 第5次練習 第 28 題", "st": "考卷", "ctx": "我國中央選舉委員會於 2024 年 1 月 13 日舉行第 11 屆立法委員選舉，共選出 113 位立法委員，包括區域和不分區立法委員。本次選舉結果各政黨的立法委員席次：國民黨 52、民進黨 51、臺灣民眾黨 8、無黨籍 2。", "fig": "", "q": "根據我國《憲法增修條文》規定，立法院的委員可對下列哪一院的院長提出不信任案？", "o": ["行政院", "司法院", "監察院", "考試院"], "a": 0, "e": "經全體立法委員 1/3 以上連署，可對行政院院長提出不信任案。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-378", "no": 378, "c": "c3", "src": "金安版公民(三) 第5次練習 第 29 題", "st": "考卷", "ctx": "子瑜在網路看到一篇報導要聞：「對於社會大眾關注電價恐調漲，經濟部長日前表示，爭取政府撥補以改善臺電財務結構，期盼『院會』能夠通過預算，以利經濟部之後執行。」", "fig": "", "q": "上文報導所提到的「院會」，應是指下列哪一個機關？", "o": ["行政院", "立法院", "監察院", "司法院"], "a": 1, "e": "審查、通過預算的是立法院院會。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-379", "no": 379, "c": "c2", "src": "金安版公民(三) 第5次練習 第 30 題", "st": "考卷", "ctx": "子瑜在網路看到一篇報導要聞：「對於社會大眾關注電價恐調漲，經濟部長日前表示，爭取政府撥補以改善臺電財務結構，期盼『院會』能夠通過預算，以利經濟部之後執行。」", "fig": "", "q": "上文所提到的經濟部長，應是由下列何者提名？", "o": ["總統", "立法院長", "行政院長", "司法院長"], "a": 2, "e": "各部會首長由行政院院長提請總統任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-380", "no": 380, "c": "c3", "src": "金安版公民(三) 第6次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國中央政府組織是採五權分立的制度，其中哪一個政府組織是中央民意機關？", "o": ["司法院", "立法院", "監察院", "考試院"], "a": 1, "e": "立法委員由人民選出，立法院是最高立法機關，也是中央民意機關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-381", "no": 381, "c": "c3", "src": "金安版公民(三) 第6次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "立法院是我國最高的立法機關，下列何者不是立法院對法律的權力？", "o": ["制定", "修改", "公布", "廢止"], "a": 2, "e": "法律由總統公布，不是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-382", "no": 382, "c": "c6", "src": "金安版公民(三) 第6次練習 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察院的委員可行使彈劾權，但對於下列何者不能行使彈劾權？", "o": ["臺南市市長", "臺南市副市長", "臺南市議員", "臺南市教育處處長"], "a": 2, "e": "民意代表（如市議員）不在監察院彈劾範圍內。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-383", "no": 383, "c": "c7", "src": "金安版公民(三) 第6次練習 第 6 題", "st": "考卷", "ctx": "", "fig": "表：甲 行政院編列預算；乙 審計部審核決算；丙 行政院執行預算、做成決算；丁 立法院審查預算", "q": "表中為「政府預算及決算經費的流程」，其正確的流程順序為何？", "o": ["甲乙丙丁", "甲丁乙丙", "甲丁丙乙", "丁甲乙丙"], "a": 2, "e": "行政院編列預算→立法院審查預算→行政院執行、做成決算→審計部審核決算。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-384", "no": 384, "c": "c1", "src": "金安版公民(三) 第6次練習 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國的公職人員中，可以發布緊急命令者，同時具有下列何種職權？", "o": ["對行政院長提出不信任案", "接受立法委員的質詢", "組成憲法法庭", "提名大法官"], "a": 3, "e": "發布緊急命令的是總統；總統也有提名大法官的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-emerg"], "chk": ""}, {"id": "c4-385", "no": 385, "c": "c4", "src": "金安版公民(三) 第6次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "張老師帶著學生參觀司法院，導覽人員介紹：甲 憲法法庭、乙 各級法院、丙 懲戒法院、丁 審計部。從簡報內容判斷，下列何者是在負責各種訴訟的審判？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "民事、刑事、行政訴訟等由各級法院負責審判。（審計部其實屬監察院。）", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-386", "no": 386, "c": "c2", "src": "金安版公民(三) 第6次練習 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "行政院為我國最高行政機關，下列有關行政院的敘述何者正確？", "o": ["行政院副院長由總統直接任命", "各部會首長有質詢立法委員的權力", "職權包括衛生福利部、文化部等事務", "行政院負責選拔優秀人才做為國家公務員的權力"], "a": 2, "e": "(A)副院長由行政院院長提請總統任命；(B)是立委質詢部會首長；(D)是考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-387", "no": 387, "c": "c3", "src": "金安版公民(三) 第6次練習 第 10 題", "st": "考卷", "ctx": "", "fig": "表：甲 正副總統彈劾案；乙 領土變更案；丙 憲法修正案；丁 正副總統罷免案", "q": "表中為我國某公職人員的提案權，哪二者的決議方式是交由選舉人投票複決？", "o": ["甲乙", "甲丙", "乙丙", "乙丁"], "a": 2, "e": "領土變更案、憲法修正案由立法院提出，交選舉人投票複決。正副總統彈劾案交憲法法庭；罷免案交選舉人投票「同意或不同意」（罷免投票）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-388", "no": 388, "c": "c6", "src": "金安版公民(三) 第6次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "「 甲 對違法失職的公務人員提出彈劾，然後送交 乙 懲戒法院懲戒。」上述的甲、乙分別是什麼機關？", "o": ["行政院、監察院", "司法院、行政院", "立法院、司法院", "監察院、司法院"], "a": 3, "e": "監察院提出彈劾，移送司法院懲戒法院審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-389", "no": 389, "c": "c5", "src": "金安版公民(三) 第6次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "「113 年公務人員高等考試三級考試暨普通考試，報名日期：113 年 7 月 7 日至 7 月 9 日；報名方式：一律採網路報名，應考人請登入國家考試網路報名資訊系統報名。」上述公告最可能出現在哪個中央政府機關的網站？", "o": ["考試院", "立法院", "行政院", "監察院"], "a": 0, "e": "辦理國家考試的是考試院（考選部）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-390", "no": 390, "c": "c6", "src": "金安版公民(三) 第6次練習 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察院針對前高雄市新聞局長任內持續騷擾女記者，經監察委員認定為性騷擾，經調查後提案彈劾。該案將會移送哪個單位進行審理？", "o": ["憲法法庭", "各級法院", "懲戒法院", "大法官會議"], "a": 2, "e": "監察院彈劾公務人員後，移送懲戒法院審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-391", "no": 391, "c": "c7", "src": "金安版公民(三) 第6次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "表：甲 行政院長；乙 立法院長；丙 司法院長；丁 大法官；戊 審計長；己 法務部長；庚 監察委員；辛 臺北市長", "q": "依據《憲法》的規定，總統對中央政府相關人員的提名權，須經立法院同意的包括表中哪些人員？", "o": ["甲乙戊己", "丙丁戊庚", "乙丁己庚", "丙丁庚辛"], "a": 1, "e": "司法院院長、大法官、審計長、監察委員都須立法院同意。行政院長由總統直接任命；立法院長由立委互選；法務部長由行政院長提請任命；臺北市長民選。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-392", "no": 392, "c": "c7", "src": "金安版公民(三) 第6次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "大千話劇社演出，甲角色說：「我決定提名恰恰為大法官。」乙角色說：「我認為恰恰不適任，所以我不同意這個人事任命案。」關於角色甲、乙兩人職權的敘述，下列何者正確？", "o": ["甲可對乙提出覆議", "乙可對甲提出質詢", "甲可解釋法律命令", "乙可以提案罷免甲"], "a": 3, "e": "甲＝總統、乙＝立法委員。立法院可提出總統罷免案。(A)覆議是行政院對立法院；(B)立委質詢對象是行政院；(C)解釋法律是大法官。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-393", "no": 393, "c": "c7", "src": "114上翰林社會2上C卷 卷6 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "分權制衡制度，是透過權力分立後，權力間彼此相互牽制，以避免因濫權而侵害人民權利。下列有關我國分權制衡的敘述，何者正確？", "o": ["司法權受立法權監督", "總統可兼任行政院院長", "立法院得對行政院院長提出不信任案", "立法院須向行政院提出立法報告"], "a": 2, "e": "(A)司法獨立審判；(B)總統不可兼任行政院院長；(D)應是行政院向立法院提出施政報告。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-394", "no": 394, "c": "c6", "src": "114上翰林社會2上C卷 卷6 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "某地方政府公務人員疑涉嫌濫用職權，經常外出處理私人事務，並有掛名公務之情事，遭到民眾檢舉。依我國的制度，該事件應由何機關處理？", "o": ["由監察院提出糾舉", "由立法院提出彈劾", "由行政院逕行處分", "考試院提不信任案"], "a": 0, "e": "公務人員違法失職，可由監察院提出糾舉（或彈劾）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-395", "no": 395, "c": "c4", "src": "114上翰林社會2上C卷 卷6 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "為了避免政府專斷，孫中山自孟德斯鳩的理論中設計出現行的憲政體系。有關我國現階段各院的職權及相關敘述，下列何者正確？", "o": ["考試委員由總統選拔", "司法院審理法律違憲案", "監察院可提出不信任案", "行政院行使人事同意權"], "a": 1, "e": "(A)考試委員由總統提名、立法院同意；(C)不信任案是立法院；(D)人事同意權是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-396", "no": 396, "c": "c4", "src": "114上翰林社會2上C卷 卷6 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "唐朝史上有一知名人物狄仁傑，他在任大理寺丞時審理許多案件，且鮮少有冤案產生。大理寺是最高審判機關，主要負責審理朝廷百官犯罪以及京師徒刑以上的案件。依據文中所述，大理寺的唐朝握有何項權力？", "o": ["立法權", "司法權", "考試權", "受益權"], "a": 1, "e": "審理案件屬於司法權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-397", "no": 397, "c": "c6", "src": "114上翰林社會2上C卷 卷6 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "「暗行御史」為朝鮮時代接受皇帝命令祕密巡行地方，探訪地方的惡政官，是比較臨時性官職，因為這種督查百姓苦惱、清除貪官污吏的題材，頗受民眾歡迎。依據上述內容，「暗行御史」較為接近何種政府權力？", "o": ["立法權", "司法權", "考試權", "監察權"], "a": 3, "e": "監督、糾舉官員屬於監察權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-398", "no": 398, "c": "c6", "src": "114上翰林社會2上C卷 卷6 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "上課時，小可上臺報告說：「我哥哥服務的單位，是掌理政府各機關財政收支決算的審核。」小可哥哥服務的單位應是隸屬於下列哪一個政府機關？", "o": ["監察院", "立法院", "行政院", "司法院"], "a": 0, "e": "審核決算的審計部隸屬監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-399", "no": 399, "c": "c4", "src": "114上翰林社會2上C卷 卷6 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "司法權以法律為依據，當私人之間或與政府發生糾紛時，作為公正裁判的權力。以下有關我國的司法院介紹，何者正確？", "o": ["設立各級法院負責各種訴訟的審判", "設有懲戒法院審理總統、副總統彈劾案", "院長、副院長由司法委員相互推選產生", "大法官組成憲法法庭審理總統、副總統罷免案"], "a": 0, "e": "(B)正副總統彈劾案由憲法法庭審理；(C)院長、副院長由總統提名、立法院同意；(D)罷免案交選舉人投票。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-400", "no": 400, "c": "c7", "src": "114上翰林社會2上C卷 卷6 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列為中央政府預算及決算的部分流程示意圖：編列預算→(甲)審查預算→(乙)執行預算→(丙)審核決算。圖中(乙)、(丙)兩機關應分別為何？", "o": ["行政院、立法院", "立法院、審計部", "行政院、審計部", "立法院、行政院"], "a": 2, "e": "執行預算是行政院，審核決算是監察院審計部。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-401", "no": 401, "c": "c7", "src": "114上翰林社會2上C卷 卷6 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國立法院於民國 113 年末通過對於《公職人員選舉罷免法》相關條文修正，行政院對其內容認為窒礙難行提出覆議遭否決。執政黨對於條文修正內容進一步認為有違憲之虞，因此提出釋憲聲請。依據上述內容，下列何者正確？", "o": ["我國為三權分立體制", "監察院將召開憲法法庭審理", "本案將由總統府解釋《憲法》", "覆議案通過與否由立法委員投票決定"], "a": 3, "e": "(A)我國為五權分立；(B)(C)釋憲由司法院大法官組成憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-402", "no": 402, "c": "c7", "src": "114上翰林社會2上C卷 卷6 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "在中央政府五院中，司法院、考試院及監察院具有須超然獨立，公正客觀的特性，執行國家賦予的任務。上述這三個單位的院長、副院長是如何產生？", "o": ["人民直選", "總統提名、立法院同意", "立法院提名、選舉人複決", "行政院院長提名、總統任命"], "a": 1, "e": "司法院、考試院、監察院院長、副院長都由總統提名，經立法院同意後任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-403", "no": 403, "c": "c5", "src": "114上翰林社會2上C卷 卷6 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "「球證、旁證、技術委員、主辦、協辦、所有單位都是我的人。你們怎麼跟我鬥！」以上是電影《少林足球》的經典臺詞。現實生活中，為了避免應聘過程產生類似的弊端，我國的政府體制特別將考試權從哪一項權力中獨立出來？", "o": ["行政權", "立法權", "司法權", "監察權"], "a": 0, "e": "為避免行政首長任用私人，將考試權從行政權中獨立出來。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-404", "no": 404, "c": "c5", "src": "114上翰林社會2上C卷 卷6 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "為了完成公民課的課堂報告，書達到中央政府各機關網頁搜尋資料，下列四則資訊，何者應為考試院的職掌內容？", "o": ["三讀通過年度預算案", "公開徵求大法官候選人", "因疫情影響停辦地方特考", "交通新制上路，違規最高罰 1,800 元"], "a": 2, "e": "辦理國家考試（含地方特考）是考試院的職掌。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-405", "no": 405, "c": "c5", "src": "114上翰林社會2上C卷 卷6 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "老李當了一輩子的公務員，今年年底即可退休，為了能妥善利用退休金，好好規畫退休生活，他想要了解退休金的算法。若老李想要得到詳細的資料，可上哪一個政府機關的網站查詢？", "o": ["考試院", "立法院", "司法院", "監察院"], "a": 0, "e": "公務人員退休、撫卹等由考試院（銓敘部）主管。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-406", "no": 406, "c": "c7", "src": "114上翰林社會2上C卷 卷6 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "「政府之正當權力是得自被治理者的同意而產生」，此處所謂的「同意」，通常是指公開且普遍的直接選舉過程。在我國，下列哪一公職人員的產生符合上述原則？", "o": ["審計長", "立法委員", "司法院院長", "教育部部長"], "a": 1, "e": "立法委員由人民直接選舉產生。審計長、司法院院長由總統提名、立法院同意；部長由行政院長提請總統任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-407", "no": 407, "c": "c7", "src": "114上翰林社會2上C卷 卷6 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "2020 年菲律賓眾議院三讀通過爭議性高的反恐法案，授權政府竊聽嫌疑人、無需逮捕令就可逮捕嫌犯，此舉引發民眾要求廢止法令與罷免菲律賓總統杜特蒂。若依我國法律，總統罷免案經提案成功後，還需進行下列哪一項程序？", "o": ["立法院開會表決", "由選舉人投票決定", "由憲法法庭審理", "考試院研擬懲戒"], "a": 1, "e": "總統罷免案由立法院提出，交由選舉人投票決定。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-408", "no": 408, "c": "c3", "src": "114上翰林社會2上C卷 卷6 第 進階 3 題", "st": "考卷", "ctx": "", "fig": "表：甲 法律修正案—立法院三讀通過；乙 領土變更案—立法院三讀通過；丙 總統、副總統罷免案—憲法法庭審理；丁 行政院院長彈劾案—憲法法庭審理", "q": "表中是小翰整理立法院提案權與決議方式，糊塗的他將許多訊息都抄錯了，其中只有哪一項目資料正確？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "法律修正案由立法院三讀通過。領土變更案交選舉人投票複決；總統副總統罷免案交選舉人投票；行政院長不是彈劾案對象（不信任案由立法院表決）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-409", "no": 409, "c": "c4", "src": "114上翰林社會2上C卷 卷6 第 進階 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "某位司法院大法官卸任後整理任內的日記，其內容記錄他在任職期間的重要經歷。下列哪一段敘述最可能出現在他的日記中？", "o": ["為了能夠繼續服務鄉親，我決定再競選連任", "我們經過討論後，決議對相關部會提出糾正案", "經院長提請總統任命後，我成為執政團隊的一員", "我們進行的憲法審理案件能進一步保障民眾權益"], "a": 3, "e": "大法官組成憲法法庭審理憲法案件。(A)民選；(B)監察院；(C)行政院部會首長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-410", "no": 410, "c": "c7", "src": "114上翰林社會2上C卷 卷6 第 進階 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "權力間的制衡是在防止單一機構權力過度集中，也期望除了相互監督外，能進一步彼此合作。關於我國權力制衡關係的敘述，下列何者正確？", "o": ["我國採用行政、立法、司法三權分立的制衡關係", "總統發布緊急命令後十日內，須經由監察院追認", "立法院可對總統提出不信任案，並要求總統下臺", "行政院面對窒礙難行的政策，可移請立法院覆議"], "a": 3, "e": "(A)五權分立；(B)立法院追認；(C)不信任案對象是行政院院長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-411", "no": 411, "c": "c6", "src": "114上翰林社會2上C卷 卷6 第 進階 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中央政府某院在其官方網站發布新聞稿：「該部執行此項發展計畫，因計畫目標之定義不明確，且執行過程中出現明顯缺失，故本院通過此糾正案。」根據訊息內容判斷，該院依據其職權，最可能在網站上發布何種消息？", "o": ["7 月將舉辦公務人員高等考試", "本會期將行使審計長人事同意權", "公布釋字第 791 號憲法解釋文", "今年度的決算報告已完成審計"], "a": 3, "e": "提出糾正案的是監察院，監察院審計部負責審核決算。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-412", "no": 412, "c": "c3", "src": "114上翰林社會2上C卷 卷6 第 進階 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "某位政治人物自 1975 年起高票當選後，開始在中央某院工作，此後在同選區皆順利連選連任，更成為某黨不分區代表，他更是我國史上在該院任期最久的院長。下列何人的職務，與此人的職權最相近？", "o": ["小治：我負責審查國家預算及法案", "小中：我負責辦理國家公務人員考試", "小靚：我規畫各項政策並編列預算", "小美：我負責審理政黨違憲解散案"], "a": 0, "e": "連選連任、不分區代表、院長→立法院（院長王金平）。立法院審查預算及法案。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-500", "no": 500, "c": "c5", "src": "大魔王卷 第 1 題", "st": "考卷", "ctx": "", "fig": "新聞：銓敘部表示，現行法令嚴禁公務人員為特定候選人或政治團體站臺、助講、遊行、拜票或具名連署競選廣告，執行機關曾反映此與國情不合，有執行困難。因此在考量國情並兼顧行政中立，認為放寬輔選規定以二親等內血親、姻親為宜。", "q": "下圖為某則新聞報導——依據我國《憲法》規定，銓敘部應隸屬於下列哪一個單位？", "o": ["行政院", "司法院", "考試院", "監察院"], "a": 2, "e": "銓敘部負責公務人員的銓敘、退休、撫卹等，隸屬考試院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-501", "no": 501, "c": "c7", "src": "大魔王卷 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "行政院為處理選舉與公投合併所產生的缺失，提出公民投票法修正草案。此草案須先交由立法院開會討論三讀通過，總統公布後，行政機關才能依法執行。從上述內容可見民主國家政府間運作的何種概念？", "o": ["以民為主", "權力分立", "覆議流程", "政黨政治"], "a": 1, "e": "行政院提案、立法院三讀、總統公布、行政機關執行，各機關分工並相互牽制，就是權力分立。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-502", "no": 502, "c": "c5", "src": "大魔王卷 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "兩個朋友對話——男：「恭喜妳考試上榜！妳希望分發到哪一個機關呢？」小莉：「我希望能分發到教育部工作。」從對話內容可知，小莉參加的考試最可能是由何者所舉辦？", "o": ["教育部", "考選部", "銓敘部", "內政部"], "a": 1, "e": "公務人員考試由考試院的考選部舉辦；考上後再分發到各機關（如教育部）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-503", "no": 503, "c": "c4", "src": "大魔王卷 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "基德是一名公務人員，最近因為一些行為上的爭議，可能需要接受懲戒。請問：負責掌理公務人員懲戒事務的機關為何？", "o": ["考試院 銓敘部", "監察院 審計部", "司法院 憲法法庭", "司法院 懲戒法院"], "a": 3, "e": "公務人員的懲戒由司法院懲戒法院掌理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-504", "no": 504, "c": "c5", "src": "大魔王卷 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "□□□每年舉辦公務人員考試與專門職業及技術人員考試，藉此選拔人才。上述□□□的職權還包括下列何者？", "o": ["審查中央政府總預算", "掌理全國公務人員的懲戒事務", "掌理公務人員的銓敘、撫卹、退休等事宜", "糾正行政機關的不當施政"], "a": 2, "e": "□□□是考試院；考試院也掌理公務人員銓敘、撫卹、退休。(A)立法院(B)懲戒法院(D)監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-505", "no": 505, "c": "c7", "src": "大魔王卷 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國中央政府五院的院長，哪些須由總統提名經立法院同意後，再由總統任命？(甲)行政院院長 (乙)立法院院長 (丙)考試院院長 (丁)司法院院長 (戊)監察院院長", "o": ["甲乙丙", "甲丙戊", "乙丙丁", "丙丁戊"], "a": 3, "e": "司法、考試、監察三院院長須立法院同意；行政院院長由總統直接任命，立法院院長由立委互選。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-506", "no": 506, "c": "c4", "src": "大魔王卷 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "公民老師說明某政府機關職權時，提及：「公務員懲戒案件一經議決，即行確定。……以上法官為終身職，超出黨派，依據法律獨立審判，不受任何干涉。」上述公務員懲戒案件是由下列哪一個機關掌理？", "o": ["監察院", "考試院銓敘部", "行政院", "司法院"], "a": 3, "e": "公務員懲戒由司法院懲戒法院的法官審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-507", "no": 507, "c": "c6", "src": "大魔王卷 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "民國 104 年 6 月，八仙海岸水上樂園舉辦彩色派對活動時，曾經發生粉塵爆炸，造成民眾嚴重的傷亡事故。案件之後，【甲】單位進行調查，認為交通部及新北市政府怠忽了對遊樂業者之審查及監督職責，皆有疏失，因而對其提出糾正案。上述【甲】應為下列何者？", "o": ["總統", "行政院", "司法院", "監察院"], "a": 3, "e": "提出糾正案的是監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-508", "no": 508, "c": "c6", "src": "大魔王卷 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "監察院表示，國軍戰甲車履帶採購過程，有結構性、制度性、系統性弊端，各級主官監督不周，都有疏失，因而通過提案◆◆國防部陸軍司令部、陸軍後勤指揮部、陸軍兵工整備發展中心及海軍左營後勤支援指揮部。上述◆◆應為下列何者？", "o": ["彈劾", "糾舉", "糾正", "質詢"], "a": 2, "e": "對象是「機關」（對事），所以是糾正；彈劾、糾舉是對「人」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-509", "no": 509, "c": "c5", "src": "大魔王卷 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "一名在蘭嶼衛生所任職的護理師，協助患者後送本島就醫任務，卻於任務途中因飛安事故不幸失事遇難。主管機關表示，本案屬於因執行公務以致死亡，而後召開審查會議，會中通過該護理師符合「冒險犯難」為項目標準予以撫卹。請依上述內容推論，該主管機關應隸屬於下列哪一個政府組織？", "o": ["司法院", "行政院", "監察院", "考試院"], "a": 3, "e": "公務人員的撫卹由考試院（銓敘部）主管。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "老師卷沒附答案，此題答案由我判斷・"}, {"id": "c4-510", "no": 510, "c": "c7", "src": "大魔王卷 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "勝雄上課時抄寫了以下筆記，但因為他一時不察，將某些部分寫錯了：「……行政院對於(甲)立法院決議之(乙)法律案、預算案、條約案，如認為有窒礙難行時，得經(丙)立法院院長核可，於該決議送達行政院 10 日內，移請立法院(丁)覆議。」根據內容判斷，筆記中的哪一項內容有誤？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "覆議須經「總統」核可，不是立法院院長。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-511", "no": 511, "c": "c7", "src": "大魔王卷 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "以下是立法院與行政院的制衡示意圖——①立法院提出並通過□→②行政院院長辭職，並得呈請總統解散立法院→③總統被動解散立法院。根據內容判斷，圖中的□應填入下列何者？", "o": ["覆議", "彈劾", "糾正", "不信任案"], "a": 3, "e": "立法院通過不信任案→行政院院長辭職並得呈請總統解散立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-512", "no": 512, "c": "c6", "src": "大魔王卷 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "老師將新聞報導繪製成關係圖：「新聞報導指出，行政院某部會的局長擅請下屬利用上班時間送親友至機場搭機，並利用職務之便透露採購訊息給親友，相關事證經監察院調查，查證屬實，近期將對該局長提出【甲】案，該案一旦成立，將會送到【乙】院懲戒。」關係圖：監察院→提出甲案→違法官員；甲案成立→乙院→進行懲戒。學生應該在甲、乙處依序填上什麼才是正確的？", "o": ["糾正，立法", "糾正，考試", "彈劾，立法", "彈劾，司法"], "a": 3, "e": "對違法官員（對人）提出彈劾案，成立後移送司法院懲戒法院懲戒。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-513", "no": 513, "c": "c7", "src": "大魔王卷 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國為強化分權制衡的效果，設有不信任案的機制。下列關於「不信任案」的敘述，何者正確？", "o": ["立法院對行政院的施政不滿意時，得對總統提出不信任案", "總統面對立法院提出的不信任案，得要求行政院院長辭職", "行政院院長提出辭呈時，得呈請總統解散立法院", "總統解散立法院後，同時必須辭職下臺"], "a": 2, "e": "不信任案是立法院對「行政院院長」提出；通過後行政院院長辭職，並得呈請總統解散立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-514", "no": 514, "c": "c7", "src": "大魔王卷 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "公民老師請同學說明「司法院與立法院的制衡」關係，下列哪些同學的說法正確？(甲)司法院大法官由總統提名，須經立法院同意。(乙)立法院制定的法律可能違反《憲法》時，有賴司法院憲法法庭裁判。(丙)對於違法或失職的立法委員，由司法院懲戒法院議處。(丁)司法院對於立法院決議的法律案，如認為窒礙難行時，可移請立法院覆議。", "o": ["甲乙", "丙丁", "甲乙丁", "甲乙丙丁"], "a": 0, "e": "(丙)立法委員是民意代表，不在彈劾、懲戒範圍；(丁)覆議是行政院提出。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-515", "no": 515, "c": "c7", "src": "大魔王卷 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "修淳上網查詢政府單位的覆議案例時，看到一則「《會計法》第 99-1 條修正烏龍事件」的新聞報導：「……(甲)表示，依照修正後的《會計法》，民代不當使用業務費不罰，教授和研究人員公款私用還是要罰，明顯出現雙重標準，不符公平原則，為避免日後窒礙難行，決定移請(乙)覆議。」依照我國《憲法增修條文》規定，(甲)、(乙)依序是指下列何者？", "o": ["行政院、立法院", "立法院、行政院", "總統、行政院", "總統、立法院"], "a": 0, "e": "行政院認為窒礙難行，經總統核可移請立法院覆議。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-veto"], "chk": ""}, {"id": "c4-516", "no": 516, "c": "c3", "src": "大魔王卷 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "學生問：「老師，誰可以對總統提出彈劾案？又如何進行呢？」老師說：「根據我國法律規定，某機關的提案者可以提出，彈劾案須經全體成員 1/2 以上提議、全體成員 2/3 以上決議後，聲請司法院憲法法庭審理。」上述老師所說的「提案者」應該為下列何者？", "o": ["法官", "大法官", "監察委員", "立法委員"], "a": 3, "e": "總統、副總統彈劾案由立法院提出（立法委員），交憲法法庭審理。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-517", "no": 517, "c": "c4", "src": "大魔王卷 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "電視新聞：「憲法法庭判決違憲」。小禾：「媽，憲法法庭判決是什麼意思啊？」小禾媽：「這是大法官進行違憲審查的結果。」如果小禾想對這件事情有更深入的了解，可在搜尋引擎查找下列哪一個關鍵字，最有可能找到相關內容？", "o": ["行政院", "立法院", "司法院", "監察院"], "a": 2, "e": "憲法法庭由司法院大法官組成。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-518", "no": 518, "c": "c3", "src": "大魔王卷 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "請根據下列對話內容判斷，哪一位最可能是立法院院長？", "o": ["依芙：今天能得到總統的提名當上院長，首先要感謝我在擔任地方法院法官時，同事的指導與協助……", "阿森：我在大學任教法律多年，後來受到總統的任命，才有今天當上院長的機會", "阿梅：我是來自全臺灣最南端選區的委員，感謝各位委員的支持，讓我當選院長", "大明：我來自務農的家庭，當上醫生後決定從政，努力通過國家考試，成為為民服務的公務人員"], "a": 2, "e": "立法院院長由立法委員互選產生。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-519", "no": 519, "c": "c7", "src": "大魔王卷 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "颱風季帶來的超大豪雨，使得部分低窪地方時常發生水患。我國中央政府編列治水經費給予地方政府使用，希望能從根本解決水患問題。若依我國相關法令，關於此筆經費的預算審查與決算審核機關，下列何者的說法正確？", "o": ["大中：司法院、行政院", "小安：行政院、立法院", "阿彩：立法院、監察院", "小薇：監察院、司法院"], "a": 2, "e": "預算由立法院審查；決算由監察院審計部審核。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-budget"], "chk": ""}, {"id": "c4-520", "no": 520, "c": "c7", "src": "大魔王卷 第 21 題", "st": "考卷", "ctx": "", "fig": "表（單位：幸福幣）：年度—(甲)提出預算金額—(乙)刪減預算金額—(丙)刪減比例：2021：1,200,000,000—17,790,000—1.5%；2022：1,240,000,000—20,000,000—1.6%；2023：1,500,000,000—20,000,000—1.3%；2024：1,600,000,000—80,000,000—5%", "q": "下表為幸福國近幾年中央政府總預算、刪減預算金額及刪減比例的資料。若依表中內容及我國中央政府職權判斷，下列敘述何者正確？", "o": ["(甲)資料會由司法院提出，並交由監察院審核", "(乙)是經由監察院審查後，所做出的調整結果", "根據(丙)判斷，2024 年行政院可能提出覆議案", "未來執行以後，會做成決算交由考試院來審查"], "a": 2, "e": "2024 年刪減比例大增到 5%，行政院若認為窒礙難行，可經總統核可提出覆議。(A)預算由行政院提出；(B)由立法院審查刪減；(D)決算由監察院審計部審核。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "老師卷沒附答案，此題答案由我判斷・"}, {"id": "c4-521", "no": 521, "c": "c7", "src": "大魔王卷 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國為避免刑事案件的被告逃跑，法院會限制被告出境。然而，有經濟犯罪者藉由颱風來襲時搭船潛逃，監察院針對海巡機關未落實船隻檢查，依職權提出(甲)。海巡機關官員接受質詢時表示，會與司法院協商其他措施，以防類似事件再次發生。關於政府機關在上述事件中的職權與互動，下列敘述何者正確？", "o": ["監察院行使(甲)職權後交由司法院審理", "海巡機關隸屬於行政院並受立法院監督", "海巡機關的主委必須到監察院接受質詢", "限制出境須由大法官掌理的法院宣告之"], "a": 1, "e": "海巡署屬行政院，須接受立法院質詢監督。(A)(甲)是糾正案，不交司法院；(C)是到立法院；(D)由各級法院法官決定。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-522", "no": 522, "c": "c7", "src": "大魔王卷 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "一名政治人物接受採訪時發表看法——官員：「行政院無法抑制房價，青年失業率高，我們認為嚴重失職，將提出不信任案。」記者：「委員能說明若是成功，接下來可能會造成哪些影響嗎？」若依我國中央政府職權來回答，下列何者正確？", "o": ["一年之內無法再對行政院院長提出不信任案", "司法院會審查提案並決定行政院院長的去留", "行政院院長將辭職並得呈請總統解散立法院", "10 日之內必須轉交由監察院追認才能夠生效"], "a": 2, "e": "不信任案通過，行政院院長應辭職並得呈請總統解散立法院。(A)是「未通過」時一年內不得再提。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-523", "no": 523, "c": "c6", "src": "大魔王卷 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "一名來臺就讀技術學院的越南籍女學生，在實習工廠工讀時，遭推車壓倒送醫後不治。「甲」對此進行調查後指出，教育部怠於保障實習生權益及生命安全，未強化相關保護措施，顯然有違失之處，因而對教育部提出糾正案。關於「甲」所擔任的公職，下列敘述何者正確？", "o": ["負責提出總統副總統的彈劾案", "負責全國公務人員的懲戒事務", "由總統提名經立法院同意任命", "經由單一選區兩票制選舉產生"], "a": 2, "e": "甲是監察委員，由總統提名、立法院同意後任命。(A)立法委員(B)懲戒法院(D)立法委員。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-524", "no": 524, "c": "c4", "src": "大魔王卷 第 25 題", "st": "考卷", "ctx": "", "fig": "", "q": "某日敏哲在網路上看到「憲法法庭 言詞辯論 即將開始（LIVE）」的實況轉播，根據我國現行法律規定，他最可能看見下列何項轉播內容？", "o": ["審理民刑事的訴訟案件", "審理政黨違憲的解散案", "表決公務人員的懲戒事項", "表決行政院院長不信任案"], "a": 1, "e": "憲法法庭審理政黨違憲解散案、法令違憲案、正副總統彈劾案等。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-525", "no": 525, "c": "c5", "src": "大魔王卷 第 26 題", "st": "考卷", "ctx": "", "fig": "", "q": "媒體報導我國總統提名考試院院長、副院長及考試委員，咨請立法院行使同意權，立法委員在投票表決前，透過提問來審查被提名人是否適任。根據我國公職人員的法定職權判斷，下列何者最可能是立法委員的提問內容？", "o": ["如何增進民眾對訴訟審理公平性的信任", "如何提升公務人員選拔的公正與多元性", "如何改善傳染病防疫措施避免疫情失控", "如何超出黨派以外統一解釋法律及命令"], "a": 1, "e": "考試院負責公務人員考選，提問應與考試權相關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-526", "no": 526, "c": "c4", "src": "大魔王卷 第 27 題", "st": "考卷", "ctx": "", "fig": "", "q": "附圖為某院的職權示意圖：甲院→審理正副總統彈劾案、審理政黨違憲解散案。依據圖中內容判斷，該院也具有下列哪一項職權？", "o": ["提出正副總統罷免案", "懲戒違法的公務人員", "規畫國家的重要政策", "糾舉失職的公務人員"], "a": 1, "e": "甲院是司法院，所屬懲戒法院負責懲戒違法失職公務人員。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-527", "no": 527, "c": "c7", "src": "大魔王卷 第 28 題", "st": "考卷", "ctx": "", "fig": "", "q": "課堂上，老師以附圖說明我國中央政府之間的制衡關係：總統→(甲)→立法院；立法院→(乙)→行政院長；行政院長→(丙)→總統。關於此圖的敘述，下列何者正確？", "o": ["這是不信任案與解散立法院的示意圖", "正確的流程順序應該是甲→乙→丙", "這是總統發布法律和命令的流程簡圖", "這是行政院與立法院質詢的流程簡圖"], "a": 0, "e": "乙：立法院對行政院院長提不信任案；丙：行政院院長呈請總統解散立法院；甲：總統解散立法院。順序是乙→丙→甲。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-528", "no": 528, "c": "c7", "src": "大魔王卷 第 29 題", "st": "考卷", "ctx": "", "fig": "", "q": "我國中央政府採取五權分立的精神，將行政權、立法權、司法權、考試權及監察權分屬於不同的組織。依據中央政府的職權，下列哪一家媒體記者下的標題是正確的？", "o": ["防疫優先！「行政院」三讀通過 600 億紓困特別預算案", "「立法院」推出開放山林政策，鬆綁 81 處林道申請手續", "F-16 戰機失事釀飛官殉職，「考試院」糾正空軍及民航局", "認為《公務人員考績法》部分條文有違憲之虞，向「司法院」聲請釋憲"], "a": 3, "e": "釋憲由司法院大法官負責。(A)三讀是立法院；(B)推政策是行政院；(C)糾正是監察院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-529", "no": 529, "c": "c3", "src": "大魔王卷 第 30 題", "st": "考卷", "ctx": "", "fig": "表：甲 推動《憲法》修正，投票年齡下修為 18 歲；乙 監督社會住宅執行，落實住宅正義；丙 任命優秀外交人員，突破國際現況；丁 看緊政府荷包，不讓稅收白白浪費", "q": "某政黨的競選文宣：「政黨票投○，你的一票改變國會，送最好的不分區進國會」。該政黨強調每一位不分區的候選人皆來自各領域專業人士，每一席都是改革的關鍵席次。附表為該政黨各個候選人的改革宣言，其中哪一位候選人的宣言被誤植了？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "任命外交人員是行政院的職權，立法委員不能任命官員。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-530", "no": 530, "c": "c1", "src": "大魔王卷 第 31 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據《總統副總統選舉罷免法》規定，在中華民國地區居住 6 個月以上且設籍 15 年以上，年滿 40 歲者，得申請登記為總統、副總統的候選人。下列哪一項說法，最能符合該項職位的身分？", "o": ["感謝立法院行使同意權過關，讓我有機會擔任候選人", "對於行政權的行使，我將更謹慎做出國防相關決策", "我上任後的首要任務，是對相關部會調查並提出糾正", "我會努力完成所託，在任期內能履行憲法法庭的職務"], "a": 1, "e": "總統可決定國防、外交、兩岸等相關大政方針。(C)監察院；(D)大法官。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-531", "no": 531, "c": "c7", "src": "大魔王卷 第 32 題", "st": "考卷", "ctx": "", "fig": "", "q": "依據大法官釋字第 461 號解釋，甲院各部會首長於乙院邀請備詢時，有應邀說明的義務。依照責任政治來看，質詢權應針對甲院負責範圍的相關事務。上文提及的甲院及乙院，兩者之間還會出現哪一種互動關係？", "o": ["乙院可將法律案移請甲院覆議", "甲院可刪減乙院提出的預算案", "乙院可對甲院院長提不信任案", "甲院可對乙院官員提出彈劾案"], "a": 2, "e": "甲＝行政院、乙＝立法院。立法院可對行政院院長提不信任案。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-532", "no": 532, "c": "c7", "src": "大魔王卷 第 33 題", "st": "考卷", "ctx": "", "fig": "表：①通過的《財政收支劃分法》修正案，行政院認為侵蝕中央財源—反對 109 票，未達半數—【甲】成功；②反對通過「鳥籠」公民投票法—反對 118 票—否決【甲】；③《地政士法》修正案通過，行政院質疑會變「虛價登錄」—反對 45 票，未達半數—【甲】成功", "q": "附表節錄我國政府機關間互動的實例。關於表中【甲】的說明，下列哪一項正確？", "o": ["是對行政院提出的不信任案", "是由行政院所發起的覆議案", "司法權制衡行政、立法兩權", "行政院向立法院負責的展現"], "a": 1, "e": "行政院認為立法院通過的法律窒礙難行，提出覆議案；維持原決議須全體立委過半數，未過半即覆議成功。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-533", "no": 533, "c": "c7", "src": "大魔王卷 第 34 題", "st": "考卷", "ctx": "", "fig": "表：罷免總統案—提案機關：(甲)立法院；提案後處理方式：(丙)交由司法院決議。彈劾總統案—提案機關：(乙)司法院；提案後處理方式：(丁)交由監察院審理。", "q": "小雅在網路上查到：「西元 2006 年 9 月 9 日，30 萬身穿紅衫的反貪腐民眾，在凱達格蘭大道上靜坐抗議，要總統下臺。」依我國《憲法》，附表是解除總統職位方式的比較表，何者是正確的？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "罷免案由立法院提出、交選舉人投票；彈劾案由立法院提出、交憲法法庭審理。只有甲正確。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-impeach"], "chk": ""}, {"id": "c4-534", "no": 534, "c": "c2", "src": "大魔王卷 第 35 題", "st": "考卷", "ctx": "", "fig": "", "q": "由於我國農產品大多不耐長期保存，出口海外在運銷過程的耗損，會影響到農民收益，因此政府積極建置冷鏈系統，從生產端到消費端均維持合適、低溫的環境，以增強競爭力。針對政府上述行動，哪一項推論是正確的？", "o": ["此成果是由總統決策的外交事項", "辦理的官員是由立法院同意產生", "負責規畫系統與執行的是行政院", "此具體成果將受到監察院的糾正"], "a": 2, "e": "規畫、執行政策是行政院（農業部）的職權。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-535", "no": 535, "c": "c4", "src": "大魔王卷 題組一(1)", "st": "考卷", "ctx": "臺北市曾出現一名專割機車椅墊的怪客，這名男子每天帶著美工刀逛街，到處割椅墊，員警不斷加強巡邏，才將這名男子逮捕到案。這名割椅怪客光是賠償受害人的椅墊，就賠了上萬元，加上受害人提出損害告訴，割椅怪客不但要賠錢，還得面對司法審判。", "fig": "", "q": "由於受害人提出告訴，所以犯案男子必須面對司法的審判。而該訴訟案的審判應是屬於哪個機關的職權？", "o": ["行政院", "立法院", "司法院", "監察院"], "a": 2, "e": "訴訟審判由司法院所屬各級法院負責。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-536", "no": 536, "c": "c6", "src": "大魔王卷 題組一(2)", "st": "考卷", "ctx": "臺北市曾出現一名專割機車椅墊的怪客，這名男子每天帶著美工刀逛街，到處割椅墊，員警不斷加強巡邏，才將這名男子逮捕到案。這名割椅怪客光是賠償受害人的椅墊，就賠了上萬元，加上受害人提出損害告訴，割椅怪客不但要賠錢，還得面對司法審判。", "fig": "", "q": "假設臺北市警察局放任割椅怪客橫行，不加以處理，則哪一個機關可以提出糾正案，要求警察機關必須善盡其職責？", "o": ["行政院", "立法院", "司法院", "監察院"], "a": 3, "e": "糾正案由監察院提出。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-537", "no": 537, "c": "c7", "src": "大魔王卷 題組二(1)", "st": "考卷", "ctx": "《憲法增修條文》第 3 條第 2 款摘要：……立法院得經全體立法委員 1/3 以上連署，對行政院院長提出不信任案。不信任案提出 72 小時後，應於 48 小時內以記名投票表決之。如經全體立法委員 1/2 以上贊成，行政院院長應於 10 日內提出辭職，並得同時呈請總統解散立法院。不信任案如未獲通過，一年內不得對同一行政院院長再提不信任案。", "fig": "", "q": "我國目前立委席次為 113 席，根據《憲法增修條文》的規定，若立法院要通過對行政院院長的不信任案，至少須有多少名立委投贊成票才會通過？", "o": ["50", "57", "75", "113"], "a": 1, "e": "須全體立委 1/2 以上贊成：113÷2＝56.5，所以至少 57 人。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-538", "no": 538, "c": "c7", "src": "大魔王卷 題組二(2)", "st": "考卷", "ctx": "《憲法增修條文》第 3 條第 2 款摘要：……立法院得經全體立法委員 1/3 以上連署，對行政院院長提出不信任案。不信任案提出 72 小時後，應於 48 小時內以記名投票表決之。如經全體立法委員 1/2 以上贊成，行政院院長應於 10 日內提出辭職，並得同時呈請總統解散立法院。不信任案如未獲通過，一年內不得對同一行政院院長再提不信任案。", "fig": "", "q": "下列何者不屬於行政院與立法院的互動？", "o": ["行政院院長向立法院提出施政方針及施政報告", "立法院決議的法律案窒礙難行，由行政院提出覆議", "立法委員對行政院各部會首長提出質詢", "行政院執行預算，做成決算，交立法院審核"], "a": 3, "e": "決算是交監察院審計部審核，不是立法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["c4-map-noconf"], "chk": ""}, {"id": "c4-539", "no": 539, "c": "c7", "src": "大魔王卷 題組三(1)", "st": "考卷", "ctx": "立法院成立修憲委員會啟動修憲工程，廢除考試院、監察院成為討論焦點。贊成廢除考、監兩院方認為：(甲)這兩院的人事任命是酬庸考量，忽視了專業能力；(乙)這兩院功能有限，卻每年編列大筆經費，花費過多稅金。不贊成廢除考、監兩院方則主張：這違反五權憲法的架構與精神；另外，(丙)總統與立委同時選舉，若獲勝的政黨掌握所有權力機構，將產生不良的後果。", "fig": "", "q": "有關(甲)提到兩院的正副院長與委員被詬病的部分，應為下列哪一種產生方式？", "o": ["總統直接任命", "公民直接選舉產生", "由行政院院長提請總統任命", "總統提名，經立法院同意後任命"], "a": 3, "e": "考試院、監察院的正副院長與委員都由總統提名、立法院同意後任命。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-540", "no": 540, "c": "c7", "src": "大魔王卷 題組三(2)", "st": "考卷", "ctx": "立法院成立修憲委員會啟動修憲工程，廢除考試院、監察院成為討論焦點。贊成廢除考、監兩院方認為：(甲)這兩院的人事任命是酬庸考量，忽視了專業能力；(乙)這兩院功能有限，卻每年編列大筆經費，花費過多稅金。不贊成廢除考、監兩院方則主張：這違反五權憲法的架構與精神；另外，(丙)總統與立委同時選舉，若獲勝的政黨掌握所有權力機構，將產生不良的後果。", "fig": "", "q": "若要藉由附表補充(乙)所認為的兩院功能：考試院—丁；監察院—戊。下列何者是正確的？", "o": ["丁：甄選公務人員；戊：糾舉公務人員", "丁：懲戒公務人員；戊：彈劾公務人員", "丁：罷免公務人員；戊：考核公務人員", "丁：任免公務人員；戊：質詢公務人員"], "a": 0, "e": "考試院甄選（考選）公務人員；監察院可糾舉、彈劾公務人員。懲戒是懲戒法院。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "c4-541", "no": 541, "c": "c7", "src": "大魔王卷 題組三(3)", "st": "考卷", "ctx": "立法院成立修憲委員會啟動修憲工程，廢除考試院、監察院成為討論焦點。贊成廢除考、監兩院方認為：(甲)這兩院的人事任命是酬庸考量，忽視了專業能力；(乙)這兩院功能有限，卻每年編列大筆經費，花費過多稅金。不贊成廢除考、監兩院方則主張：這違反五權憲法的架構與精神；另外，(丙)總統與立委同時選舉，若獲勝的政黨掌握所有權力機構，將產生不良的後果。", "fig": "", "q": "針對(丙)所擔心的不良後果，有可能會出現在下列哪一個行為上？", "o": ["無法糾正相關部會，要求改善不當施政", "無法藉由追認使緊急命令立即失效", "無法以法庭裁判方式，解散違憲的政黨", "無法辦理公務人員的銓敘、撫卹等事宜"], "a": 0, "e": "若廢除監察院，又由同一政黨掌握行政、立法，就少了糾正行政機關不當施政的監督力量。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "老師卷沒附答案，此題答案由我判斷・"}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>1. 中央政府重要公職人員產生方式與任期比較表</h3><div class=\"tbl\"><table><thead><tr><th>機關名稱</th><th>主要成員職稱</th><th>產生方式</th><th>任期與連任限制</th></tr></thead><tbody><tr><td><b>總統府</b></td><td>總統、副總統</td><td>由<b>全體人民直接選舉</b>產生</td><td>任期 <b>4 年</b>，連選得連任 <b>1 次</b></td></tr><tr><td><b>行政院</b></td><td>行政院院長</td><td>由<b>總統直接任命</b>（不須立法院同意）</td><td>無明文任期，隨政局或政策進退</td></tr><tr><td><b>行政院</b></td><td>副院長、各部會首長、政務委員</td><td>由<b>行政院院長提請總統任命</b></td><td>隨內閣同進退</td></tr><tr><td><b>立法院</b></td><td>立法委員（共 113 席）</td><td>由<b>全體人民依單一選區兩票制直接選舉</b>產生</td><td>任期 <b>4 年</b>，連選<b>得連任（無次數限制）</b></td></tr><tr><td><b>立法院</b></td><td>立法院院長、副院長</td><td>由<b>立法委員互選</b>產生</td><td>隨立法委員任期</td></tr><tr><td><b>司法院</b></td><td>院長、副院長、大法官</td><td><b>總統提名，經立法院同意</b>後由總統任命</td><td>大法官任期 8 年（司法院院長、副院長不受任期保障）</td></tr><tr><td><b>考試院</b></td><td>院長、副院長、考試委員</td><td><b>總統提名，經立法院同意</b>後由總統任命</td><td>依法定任期（現行修法改為 4 年）</td></tr><tr><td><b>監察院</b></td><td>院長、副院長、監察委員、審計長</td><td><b>總統提名，經立法院同意</b>後由總統任命</td><td>任期 6 年（審計長任期 6 年）</td></tr></tbody></table></div><h3>2. 監察院職權三兄弟：彈劾 vs 糾舉 vs 糾正 比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>彈劾權</th><th>糾舉權</th><th>糾正權</th></tr></thead><tbody><tr><td><b>行使對象</b></td><td><b>「人」</b>（中央與地方公務人員違法失職）</td><td><b>「人」</b>（中央與地方公務人員違法失職）</td><td><b>「事」</b>（行政院及其所屬部會不當施政）</td></tr><tr><td><b>例外對象</b></td><td><b>不包含</b>總統、副總統與民意代表</td><td><b>不包含</b>總統、副總統與民意代表</td><td>僅針對行政機關，不針對司法、立法等</td></tr><tr><td><b>提出對象／程序</b></td><td>提案後移送<b>司法院懲戒法院</b>審理</td><td>提案後送交被糾舉人的<b>主管或上級長官</b>處置</td><td>提案後向<b>行政院或主管行政機關</b>提出促其改善</td></tr><tr><td><b>處理目的</b></td><td>追究違法失職公務員之法律與懲戒責任（免職、停職等）</td><td>迅速制止或處置現行失職行為（先予調職或處分）</td><td>督促行政機關檢討行政缺失、修訂瑕疵規範</td></tr></tbody></table></div><h3>3. 立法院四大提案之提出與決議程序比較表</h3><div class=\"tbl\"><table><thead><tr><th>提案事項</th><th>提案機關</th><th>決議／審理機關</th><th>最終生效門檻／決定者</th></tr></thead><tbody><tr><td><b>《憲法》修正案</b></td><td><b>立法院</b>提出修憲案</td><td>公告半年後交由<b>全體選舉人投票複決</b></td><td>需有效同意票<b>過半數選舉人總額</b>通過</td></tr><tr><td><b>領土變更案</b></td><td><b>立法院</b>提出領土變更案</td><td>公告半年後交由<b>全體選舉人投票複決</b></td><td>需有效同意票<b>過半數選舉人總額</b>通過</td></tr><tr><td><b>總統、副總統罷免案</b></td><td><b>立法院</b>提出罷免案</td><td>交由<b>中華民國自由地區全體選舉人投票罷免</b></td><td>選民投票過半數同意通過</td></tr><tr><td><b>總統、副總統彈劾案</b></td><td><b>立法院</b>提出彈劾案</td><td>交由<b>司法院大法官組成「憲法法庭」</b>審理</td><td>憲法法庭判決成立後即解職</td></tr></tbody></table></div><h3>4. 行政權 vs 立法權：不信任案 vs 覆議案 比較表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>不信任案（倒閣）</th><th>覆議案</th></tr></thead><tbody><tr><td><b>提出主體</b></td><td>由<b>立法院</b>向行政院院長提出</td><td>由<b>行政院</b>經<b>總統核可</b>後移請立法院覆議</td></tr><tr><td><b>提出事由</b></td><td>對行政院院長的施政方針或整體表現不滿意</td><td>認為立法院決議之<b>法律案、預算案、條約案窒礙難行</b></td></tr><tr><td><b>通過之法定結果</b></td><td><b>行政院院長應辭職</b>，並得同時呈請總統<b>解散立法院</b></td><td>若全體立委 <b>1/2 以上維持原決議</b>，行政院長應接受該決議</td></tr><tr><td><b>未通過之法定結果</b></td><td>不信任案失敗，<b>一年內不得對同一行政院院長再提</b></td><td>原立法院決議失效</td></tr><tr><td><b>制度設計初衷</b></td><td>立法權制衡行政權、促使責任政治落實之終極手段</td><td>行政權自我防衛、防止立法權專斷破壞施政可行性</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "制衡流程", "html": "<h3>中央政府預決算五階段運作時間軸與流程</h3><figure class=\"cimg\"><img src=\"img/c4-map-budget.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中央政府預算、決算流程簡圖</figcaption></figure><div class=\"tbl\"><table><thead><tr><th>階段</th><th>負責機關</th><th>法定職掌與運作要點</th></tr></thead><tbody><tr><td><b>第一階段：編列預算</b></td><td><b>行政院</b></td><td>彙編各部會及各院年度需求，於規定期限前向立法院提出中央政府總預算案。</td></tr><tr><td><b>第二階段：審查預算</b></td><td><b>立法院</b></td><td>各委員會審查、院會三讀議決預算案，依法監督把關政府財政收支。</td></tr><tr><td><b>第三階段：執行與決算</b></td><td><b>行政院</b></td><td>依立法院通過之法定預算確實執行，並於會計年度終了時編製總決算。</td></tr><tr><td><b>第四階段：審核決算</b></td><td><b>監察院審計部</b></td><td>依法獨立審核總決算，考核有無浪費或違失，並編製「年度總決算審核報告」。</td></tr><tr><td><b>第五階段：審議審核報告</b></td><td><b>立法院</b></td><td>審議審計部提出之審核報告，作為下一年度審查總預算之重要依據。</td></tr></tbody></table></div><h3>不信任案與解散國會連鎖流程圖</h3><figure class=\"cimg\"><img src=\"img/c4-map-noconf.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>不信任案與解散制度</figcaption></figure><pre class=\"flow\">【立法院】主動提出對行政院院長之「不信任案」\n     │\n     ├──［表決未通過］──→ 一年內不得對同一院長再提不信任案。\n     │\n     └──［表決通過］────→ ① 行政院院長應於十日內提出辭職。\n                             ② 院長得同時呈請總統「解散立法院」。\n                             ③ 總統宣告解散後，全體立法委員進行重新改選。</pre><h3>覆議制度運作流程圖</h3><figure class=\"cimg\"><img src=\"img/c4-map-veto.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>覆議制度流程簡圖</figcaption></figure><pre class=\"flow\">【立法院】三讀通過法律案、預算案或條約案決議\n     ↓ 送交行政院執行\n【行政院】認為該決議窒礙難行\n     ↓ 報請總統核可\n【行政院】移請立法院覆議\n     ↓ 立法院全體委員開會投票重新表決\n     ├──［全體立委 1/2 以上維持原決議］──→ 行政院院長必須接受並執行該決議。\n     └──［未達 1/2 維持原決議］───────→ 原立法決議立即失效。</pre>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>1. 總統發布緊急命令流程圖</h3><figure class=\"cimg\"><img src=\"img/c4-map-emerg.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>總統發布緊急命令流程簡圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：總統發布緊急命令程序示意圖。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>發布前置條件</b>：國家遭遇緊急危難或應付財政經濟上重大變故，且必須先經<b>行政院會議之決議</b>，總統方得發布。</p><p class=\"li sub\">2. <b>事後追認期限</b>：發布後<b>十日內</b>，必須提交<b>立法院</b>追認。</p><p class=\"li sub\">3. <b>追認效果差異</b>：立法院若表決「同意」，緊急命令繼續有效；立法院若「不同意」，該緊急命令<b>立即失效</b>。</p><p class=\"li\"><b>常見判讀方式與考點</b>：</p><p class=\"li sub\">• 題目常挖空「行政院會議決議」或「十日內提交立法院追認」，測試發布緊急命令是否屬於總統個人專斷權力（答案：否，必須受行政院與立法院制衡）。</p><p class=\"li sub\">• 921 大地震時政府發布緊急命令即為此制度之經典歷史範例。</p><h3>2. 行政院部會架構圖</h3><figure class=\"cimg\"><img src=\"img/c4-map-cabinet.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>行政院 15 部架構圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：行政院組織部會架構圖。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 行政院院長綜理院務，轄下有各部會，包含新設立之部會（如：數位發展部、環境部、農業部、運動部）。</p><p class=\"li sub\">2. 每個部會掌理不同業務領域：外交（國防部、外交部）、財政（財政部）、社會保障與安全（內政部、法務部、衛生福利部、勞動部）等。</p><p class=\"li\"><b>常見判讀方式與考點</b>：</p><p class=\"li sub\">• 題目常以新聞時事入題（如查緝蛋品食安問歸哪個部會——衛生福利部；成立體育運動部會的法律由誰通過——立法院通過法案，行政院執行）。</p><h3>3. 司法院組織與大法官「憲法法庭」職能圖</h3><figure class=\"cimg\"><img src=\"img/c4-map-judicial.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>司法院職權架構圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：司法院「解釋權、審判權、懲戒權」權限架構圖。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>憲法法庭（大法官）</b>：負責「審理法律是否牴觸憲法（違憲審查）」、「總統與副總統彈劾案」、「政黨違憲解散案」。</p><p class=\"li sub\">2. <b>各級法院</b>：負責審理民事、刑事與行政訴訟案件。</p><p class=\"li sub\">3. <b>懲戒法院</b>：專門處理公務人員違法失職案件之司法懲戒。</p><p class=\"li\"><b>常見判讀方式與考點</b>：</p><p class=\"li sub\">• 會考極常考「政黨解散」是由憲法法庭判決，而非內政部或行政院決定。</p><p class=\"li sub\">• 「公務員受彈劾」後移送懲戒法院，而「總統受彈劾」則是移送憲法法庭審理，二者審理單位截然不同。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>特別提醒（會考熱門陷阱）</h3><p>1. <b>行政院院長不需立法院同意</b>：總統任命行政院院長直接指派即可生效，<b>無須</b>立法院行使人事同意權。（但司法院、考試院、監察院院長、副院長、大法官、考試委員、監察委員及審計長，均須經立法院同意）。</p><p>2. <b>彈劾對象大不同</b>：</p><p class=\"li sub\">• 總統、副總統違法失職：由<b>立法院</b>提案提出彈劾，交由<b>司法院大法官組成憲法法庭</b>審理。</p><p class=\"li sub\">• 一般公務人員違法失職：由<b>監察院</b>提出彈劾，交由<b>司法院懲戒法院</b>審理。</p><p class=\"li sub\">• 監察院<b>絕對不能</b>對總統、副總統提出彈劾，亦不能彈劾民意代表（立委、議員）。</p><p>3. <b>覆議與不信任案的發起端</b>：</p><p class=\"li sub\">• 「覆議」是<b>行政院</b>覺得立法院通過的決議窒礙難行，移請立法院重新表決。</p><p class=\"li sub\">• 「不信任案」是<b>立法院</b>對行政院院長不滿意，主動提出要行政院院長下臺。</p><p>4. <b>預決算的順序口訣</b>：<b>行政編、立法審、行政執、審計核、立法再審議</b>。行政機關負責編列與執行，立法機關負責初審與最終審議報告，監察院審計部負責審核。</p><h3>考前速記口訣</h3><div class=\"poem\">💡 <b>口訣一：中央五院分工定位</b></div><div class=\"poem\"><b>「政執行、立法定；司公正、考拔才；監察監督查失職。」</b></div><div class=\"poem\">*(行政院執行政策、立法院制定法規、司法院公正審判、考試院選拔人才、監察院監督官員)。*</div><div class=\"poem\">💡 <b>口訣二：人事提名與任命</b></div><div class=\"poem\"><b>「閣揆總統直接派；司考監審立院審；大法官入憲法庭，懲戒法院辦貪官。」</b></div><div class=\"poem\">*(行政院長由總統直接任命；司法院、考試院、監察院全體與審計長皆須立法院同意；大法官負責憲法法庭，懲戒法院審理一般公務員違失)。*</div><div class=\"poem\">💡 <b>口訣三：行政與立法互制</b></div><div class=\"poem\"><b>「窒礙難行提覆議，立院過半院長吞；施政不滿倒閣起，院長請辭散國會。」</b></div><div class=\"poem\">*(法律窒礙難行由行政院提覆議，立院二分之一維持則院長接受；立院提不信任案通過，院長請辭並可呈請總統解散立法院)。*</div>"}]});
